(window.TA_BLOBS = window.TA_BLOBS || {})['ta-acts'] = "[{\"id\":\"register-for-class\",\"topic\":\"01\",\"name\":\"Register for a class\",\"desc\":\"Student wants to enroll in a specific course section (and any linked discussion/lab/quiz) for the current or an upcoming term.\",\"system\":\"Web Registration (webreg.usc.edu), signed in with USC NetID or opened from myUSC/Experience USC\",\"steps\":[\"Confirm you have a Permit to Register and that it is at or after your appointment time (Web Registration > myInfo > Registration Appointment, or Experience USC > My Academics beneath the left side of the calendar).\",\"Clear any activity-restriction holds first (Experience USC > My Academics > View Registration Information; contact the office that placed each hold).\",\"Log in to Web Registration and select the term.\",\"Find the course under [Term] Classes by school and major, or search by prefix; use Advanced search for section number, instructor, units or times.\",\"If the section number ends in D, obtain D-clearance from the department first and confirm it under myInfo > Cleared Sections.\",\"Click 'Add to myCourseBin' for the lecture and any discussion/lab/quiz section listed directly under that lecture.\",\"Open myCourseBin, confirm the sections show 'Scheduled but Not Registered' and that there are no time conflicts.\",\"Click 'Register'; review the Checkout tab (it processes all pending changes) and click 'Submit'.\",\"Wait for the system response confirming success; an automated confirmation email is sent to your USC email.\"],\"req\":[\"Permit to Register (registration appointment) for the term.\",\"No registration-blocking holds; the Registrar cannot release holds outside its purview.\",\"D-clearance for D sections; prerequisites/co-requisites met or waived by the department offering the course.\",\"Undergraduates can register for up to 20 units in Web Registration (more requires advisor approval entered in SIS); graduate students up to 30 units.\",\"Courses with a time conflict cannot be registered in Web Registration (Time Conflict form required).\",\"Registration is not permitted after the third week of classes.\",\"Limited Status students do not have access to Web Registration (they email the Registrar).\",\"Students with an RNR01 (academic notice) hold register through their Academic Counselor.\"],\"deadlines\":[\"Spring 2027: registration for continuing students began October 26, 2026.\",\"Spring 2027: last day to register and settle without a late fee is January 8, 2027 (session 001).\",\"Spring 2027: last day to register for session 001 courses is January 29, 2027.\",\"Fall 2026: last day to register for session 001 courses was September 11, 2026.\",\"All changes must be made by 11:59 PM PT on the deadline; non-001 sessions: Calendar icon in the Schedule of Classes.\"],\"costs\":[\"2026-27 undergraduate tuition: $37,692 per semester for 12-18 units; unit basis $2,539 per unit.\",\"Late Registration Fee if a student first registers after classes begin (amount not stated on the pages read).\",\"Tuition Refund Insurance is added automatically at registration: 0.3 of 1 percent of tuition and mandatory fees (can opt out by the deadline).\"],\"fields\":[\"term\",\"course prefix/number and 5-digit section number(s), including linked discussion/lab/quiz\",\"D-clearance status for D sections\",\"unit value (variable-unit courses)\",\"grading option (letter, P/NP, audit)\",\"time conflicts with current schedule\",\"total units after adding (20-unit cap)\",\"registration appointment time and holds\",\"any other pending changes in Checkout\"],\"sources\":[{\"url\":\"https://arr.usc.edu/web-registration/\",\"title\":\"Web Registration System - Office of Academic Records and Registrar\"},{\"url\":\"https://ask.usc.edu/s/article/000001833\",\"title\":\"How do I add a course?\"},{\"url\":\"https://ask.usc.edu/s/article/000003017\",\"title\":\"Do I need a Permit to Register to enroll by Web Registration?\"},{\"url\":\"https://arr.usc.edu/registration-services/\",\"title\":\"Registration Services - Office of Academic Records and Registrar\"}]},{\"id\":\"drop-a-class\",\"topic\":\"01\",\"name\":\"Drop a class\",\"desc\":\"Student wants to remove a registered course from their schedule (before or after the refund deadline).\",\"system\":\"Web Registration (webreg.usc.edu) > myCourseBin; Registrar One Stop via askUSC if Web Registration gives an error\",\"steps\":[\"Log in to Web Registration and open myCourseBin for the term.\",\"Click 'Unschedule' under the course; for a course with lecture plus discussion/lab/quiz, unschedule all of its sections.\",\"Click 'Drop' (unscheduling alone does not drop you; you would stay on the roster).\",\"Review the Checkout tab, which processes all pending changes, then click 'Submit'.\",\"Wait for the system response and the confirmation email.\",\"If Web Registration gives an error, email the Registrar's office via askUSC before the deadline.\"],\"req\":[\"Must be done officially through Web Registration or the Registrar One Stop; informing the instructor or department does not constitute withdrawal.\",\"International students must obtain OIS clearance to drop below full-time enrollment (12 undergraduate / 8 master's / 6 doctoral units).\",\"Financial aid recipients should consult a financial aid counselor before withdrawing from courses.\",\"Students on academic notice (RNR01 hold) must process changes through their Academic Counselor.\",\"Students may not withdraw from a course in which they have committed or are accused of an academic integrity violation.\"],\"deadlines\":[\"Fall 2026 (session 001): drop with refund by September 11 (Monday-only classes September 15); drop without a W by October 9; withdraw with a W by November 13, 2026.\",\"Spring 2027 (session 001): drop with refund by January 29 (Monday-only classes February 2); drop without a W by February 26; withdraw with a W by April 9, 2027.\",\"Deadlines are at 11:59 PM PT; other sessions use course-specific dates (Calendar icon in the Schedule of Classes).\"],\"costs\":[\"No fee stated for dropping.\",\"Refund only if dropped before the refund deadline (20% mark); USC has no pro-rated tuition and no refund after the refund deadline.\",\"Eligible refunds become available via USCe.pay.\"],\"fields\":[\"term\",\"course and every linked section number to drop\",\"today's date versus refund / no-W / withdrawal deadlines\",\"resulting transcript mark (none or W)\",\"refund eligibility\",\"units remaining and full-time status (financial aid, international status)\",\"other pending changes in Checkout\"],\"sources\":[{\"url\":\"https://ask.usc.edu/s/article/000001779\",\"title\":\"How do I drop a course?\"},{\"url\":\"https://arr.usc.edu/web-registration/\",\"title\":\"Web Registration System - Office of Academic Records and Registrar\"},{\"url\":\"https://arr.usc.edu/registration-services/\",\"title\":\"Registration Services - Office of Academic Records and Registrar\"},{\"url\":\"https://arr.usc.edu/tuition-and-fees/\",\"title\":\"Tuition and Fees - Office of Academic Records and Registrar\"}]},{\"id\":\"switch-sections\",\"topic\":\"01\",\"name\":\"Switch to a different section of the same course\",\"desc\":\"Student wants to move from one section of a course to another section of the same course (different time or instructor).\",\"system\":\"Web Registration while registration is open (first three weeks); after that, a section-change request routed instructor > department > Registrar's office\",\"steps\":[\"Weeks 1-3 (while registration is open): make the change yourself in Web Registration, which is how students add and drop courses: drop the old section and register for the new one (with its linked discussion/lab/quiz), reviewing Checkout since it processes all pending changes together. Get D-clearance first if the new section is a D section; if Web Registration gives an error, email the Registrar's office.\",\"Weeks 4-12: email the instructor of the new section to request approval.\",\"The instructor forwards approval to the academic department for final review and D-clearance, if necessary.\",\"The academic department forwards the request to the Registrar's office for processing.\",\"You receive an email confirmation once the request is approved and complete.\"],\"req\":[\"Course prefix, course number and session number must be identical (e.g., BUAD-301 session 001 to another BUAD-301 session 001 section, not to BUAD-104).\",\"New instructor and department approval are required for weeks 4-12 changes.\",\"The section-change policy does not apply to instructional labs in the natural sciences.\",\"D-clearance is section-specific, so the new section may need its own clearance.\",\"WRIT 150: during the first two weeks students may move between available sections without instructor approval (Writing Program).\"],\"deadlines\":[\"Self-service changes only while registration is open; registration is not permitted after the third week (Fall 2026 last day to register: September 11; Spring 2027: January 29).\",\"Requested section changes: weeks 4 through 12 of the semester.\"],\"costs\":[\"none stated\"],\"fields\":[\"course prefix/number and session code\",\"current section number\",\"new section number and linked sections\",\"D-clearance for the new section\",\"new instructor approval (weeks 4-12)\",\"time conflicts with the new section's meeting time\"],\"sources\":[{\"url\":\"https://ask.usc.edu/s/article/000002542\",\"title\":\"How do I switch sections of a class?\"},{\"url\":\"https://ask.usc.edu/s/article/000002943\",\"title\":\"I want to switch sections of the course I am already enrolled in, but Web Registration says I need D-clearance. Why do I need D-clearance if I\u2019m already taking the course?\"},{\"url\":\"https://arr.usc.edu/web-registration/\",\"title\":\"Web Registration System - Office of Academic Records and Registrar\"},{\"url\":\"https://arr.usc.edu/registration-services/\",\"title\":\"Registration Services - Office of Academic Records and Registrar\"}]},{\"id\":\"add-course-to-mycoursebin\",\"topic\":\"01\",\"name\":\"Add a course to myCourseBin\",\"desc\":\"Student wants to save/plan a course section in their course bin before (or as a step toward) registering.\",\"system\":\"Web Registration (webreg.usc.edu) > [Term] Classes or search > myCourseBin\",\"steps\":[\"Log in to Web Registration and select the term.\",\"Browse [Term] Classes by school, then major, or enter a course prefix (e.g., HIST) in the search box; use Advanced to search by section, instructor, units or start/end times.\",\"Click a class name to see its description, units, number of registered students, meeting days/times, instructor and location.\",\"Click 'Add to myCourseBin' for the section, plus any discussion/lab/quiz listed directly under that lecture.\",\"Open myCourseBin to review; the courses show 'Scheduled but Not Registered' (yellow on myCalendar).\",\"Optionally Unschedule (keeps it in the bin on hold) or Unschedule then Remove (deletes it from the bin).\",\"To actually enroll, click Register, review Checkout and Submit at or after your registration appointment.\"],\"req\":[\"Adding a course to myCourseBin does not register you or reserve a seat on the roster.\",\"Sections you have D-clearance for can be added from myInfo > Cleared Sections.\"],\"deadlines\":[\"none stated for building the course bin (registration itself follows the term's deadlines)\"],\"costs\":[\"none stated\"],\"fields\":[\"term\",\"course and 5-digit section number(s)\",\"linked discussion/lab/quiz\",\"whether the section is D or R\",\"whether the student also wants to register now\"],\"sources\":[{\"url\":\"https://arr.usc.edu/web-registration/\",\"title\":\"Web Registration System - Office of Academic Records and Registrar\"},{\"url\":\"https://ask.usc.edu/s/article/000001746\",\"title\":\"How do I search for classes and use the Advanced Search option?\"},{\"url\":\"https://ask.usc.edu/s/article/000001833\",\"title\":\"How do I add a course?\"}]},{\"id\":\"request-d-clearance\",\"topic\":\"01\",\"name\":\"Request D-clearance\",\"desc\":\"Student needs departmental clearance to register for a D section (or for a course that requires clearance after classes start).\",\"system\":\"The academic department offering the course, which enters clearance in the Student Information System (SIS); status visible in Web Registration > myInfo > Cleared Sections\",\"steps\":[\"Find the course in the Schedule of Classes and read any departmental instructions shown at the top of the listing.\",\"If there are no instructions, contact the department offering the course (phone, office or email shown on its Web Registration page).\",\"Request clearance for the specific section (and unit value, for variable-unit courses) following the department's process.\",\"Follow up with the department if it takes time; each department handles its own process.\",\"Check Web Registration > myInfo > Cleared Sections.\",\"Add the cleared section to myCourseBin from Cleared Sections, then Register and Submit.\"],\"req\":[\"The Registrar's office is not authorized to grant D-clearance; an instructor emailing the Registrar does not grant it (the department enters it in SIS, or emails the Registrar explicitly granting it if it cannot enter it).\",\"D-clearance is section-specific.\",\"For variable-unit courses the clearance must reflect the requested unit value.\",\"Internship courses for Curricular Practical Training have a dedicated 'Request for D-Clearance' form on the Registrar's Student Forms page.\"],\"deadlines\":[\"From the start of week 1 (ENGL), week 2 (WRIT, MATH, PR, JOUR, AMST, ITP) or week 3 (ART, CRIT, DES, CNTV, CTCS, CTIN, CMPP, CTPR, CTWR, IML, ASCJ, COMM) these prefixes require D-clearance for all session 001 sections.\",\"Registration is not permitted after the third week of classes.\"],\"costs\":[\"none stated\"],\"fields\":[\"course and exact section number\",\"term/session\",\"department contact and its instructions\",\"requested unit value (variable-unit courses)\",\"whether the clearance now appears under Cleared Sections\"],\"sources\":[{\"url\":\"https://ask.usc.edu/s/article/000003059\",\"title\":\"What should I do if the Web Registration portal says my registration failed because the course I want to register in requires departmental clearance?\"},{\"url\":\"https://ask.usc.edu/s/article/000002743\",\"title\":\"Can a course instructor email the Registrar to grant D-clearance?\"},{\"url\":\"https://ask.usc.edu/s/article/000002190\",\"title\":\"Web Registration says my class requires D-clearance. How do I obtain this?\"},{\"url\":\"https://ask.usc.edu/s/article/How-do-I-know-if-I-have-D-clearance-for-the-section-I-want-to-register-in\",\"title\":\"How do I know if I have D-clearance for the section I want to register in?\"}]},{\"id\":\"check-registration-appointment-and-holds\",\"topic\":\"01\",\"name\":\"Check registration appointment time and holds\",\"desc\":\"Student wants to know when they can register and whether any holds will block registration.\",\"system\":\"Web Registration > myInfo (Registration Appointment); Experience USC > My Academics (Permit to Register and activity restrictions)\",\"steps\":[\"In Web Registration, select the term and open the myInfo tab; the Registration Appointment section shows your date and time.\",\"Or log in to Experience USC > My Academics; the Permit to Register is just beneath the left side of the calendar.\",\"On the same My Academics page, look just below the calendar on the right for activity restrictions (or a message that you have none).\",\"Click 'View Registration Information' to see each hold's code, description and the department to contact.\",\"Contact each issuing department to clear holds before your appointment.\",\"No permit? An LOA hold must be cleared by your advisor; students graduating this term are not assigned one; otherwise email the Registrar's office via askUSC.\"],\"req\":[\"A Permit to Register is required to register in Web Registration.\",\"The Registrar does not have authority to clear holds outside its purview and cannot temporarily release them.\",\"Mandatory advisement holds are removed by the academic advisor; the One Stop cannot remove them for the department.\"],\"deadlines\":[\"Spring 2027: registration appointment times and Permit to Register information posted October 5, 2026; registration for continuing students began October 26, 2026.\"],\"costs\":[\"none stated\"],\"fields\":[\"term\",\"appointment date and time\",\"hold codes and issuing offices\",\"whether the expected graduation term is correct (graduating students get no permit)\"],\"sources\":[{\"url\":\"https://arr.usc.edu/web-registration/\",\"title\":\"Web Registration System - Office of Academic Records and Registrar\"},{\"url\":\"https://ask.usc.edu/s/article/000001820\",\"title\":\"Where can I view my Web Registration Permit to Register?\"},{\"url\":\"https://ask.usc.edu/s/article/000002136\",\"title\":\"How do I know if there are holds on my account that will block my registration?\"},{\"url\":\"https://ask.usc.edu/s/article/000002705\",\"title\":\"Can the registrar temporarily release a hold so I can register for a course?\"}]},{\"id\":\"change-grading-option-pass-no-pass\",\"topic\":\"01\",\"name\":\"Change grading option to Pass/No Pass (or back to letter grade)\",\"desc\":\"Student wants to switch a registered course between letter grade, Pass/No Pass or Audit.\",\"system\":\"Web Registration (webreg.usc.edu) > myCourseBin > Grade Option drop-down\",\"steps\":[\"Log in to Web Registration and open myCourseBin for the term.\",\"Make sure the section is scheduled (the Grade Option drop-down does not appear for unscheduled sections).\",\"Select the new option from the course's Grade Option drop-down and click 'Update'.\",\"Review the Checkout tab (all pending changes are processed) and click 'Submit'.\",\"Wait for the system response confirming the grading option changed.\",\"If the drop-down still does not appear, email the Registration office via askUSC with a screenshot.\"],\"req\":[\"Undergraduate P/NP is not available in courses numbered 390 or 490, WRIT-140 or 340, or for minor requirements; a maximum of 24 P/NP units apply toward the degree, with at most 4 toward General Education.\",\"P/NP courses cannot fulfill major requirements unless the major department gives written permission.\",\"Graduate students need departmental approval, and P/NP coursework cannot be applied toward a graduate degree.\",\"Instructor permission may be needed for P/NP or Audit.\",\"Courses offered only as Credit/No Credit cannot take any other grading option.\",\"Freshman Forgiveness repeats must be taken for a letter grade.\",\"After the deadline a change requires a petition, allowed only for registration errors (not GPA or financial purposes).\"],\"deadlines\":[\"Fall 2026 (session 001): switch to P/NP or Audit by September 11 (Monday-only classes September 15); P/NP to letter grade by October 9.\",\"Spring 2027 (session 001): switch to P/NP or Audit by January 29 (Monday-only classes February 2); P/NP to letter grade by February 26.\",\"Changes are due by 11:59 PM PT on the deadline.\"],\"costs\":[\"Standard tuition applies regardless of grading option.\",\"Late change by petition: $150 petition fee.\"],\"fields\":[\"course and section\",\"current grading option\",\"new grading option\",\"today's date versus the deadline\",\"effect on major/minor/GE requirements and the 24-unit/4-unit P/NP caps\",\"whether the course is being used for Freshman Forgiveness\"],\"sources\":[{\"url\":\"https://arr.usc.edu/web-registration/\",\"title\":\"Web Registration System - Office of Academic Records and Registrar\"},{\"url\":\"https://ask.usc.edu/s/article/000002228\",\"title\":\"How do I change my grading option to Pass/No Pass or Audit?\"},{\"url\":\"https://ask.usc.edu/s/article/000002951\",\"title\":\"How do I change the grading option for a course if Web Registration won't let me?\"},{\"url\":\"https://ask.usc.edu/s/article/000001727\",\"title\":\"Can I petition to change the grading option from letter grade to Pass/No Pass or vice versa?\"}]},{\"id\":\"withdraw-from-class-w\",\"topic\":\"01\",\"name\":\"Withdraw from a class (mark of W)\",\"desc\":\"Student wants to drop a course after the no-W deadline but before the withdrawal deadline, accepting a W.\",\"system\":\"Web Registration (myCourseBin > Unschedule > Drop > Submit); One Stop Center by email if Web Registration won't allow it; Petition Services after the deadline\",\"steps\":[\"Confirm the date is after the no-W deadline and on or before the withdrawal deadline for the course's session.\",\"In Web Registration open myCourseBin, click 'Unschedule' under every section of the course, then click 'Drop'.\",\"Review Checkout and click 'Submit'; wait for the confirmation.\",\"If you cannot drop via Web Registration, email the One Stop Center with your request before the deadline.\",\"After the withdrawal deadline, only a petition to Petition Services (rarely approved) can withdraw you.\"],\"req\":[\"A W has no effect on GPA and satisfies the continuous enrollment requirement; there is no refund at this stage.\",\"Stopping attendance without officially withdrawing results in a UW, computed as zero grade points.\",\"Instructors cannot withdraw students; students cannot withdraw from a course involving an academic integrity violation or accusation.\",\"International students need OIS clearance to drop below full-time; financial aid recipients should consult a financial aid counselor.\",\"Tuition Refund Insurance claims require withdrawal from all courses before the withdrawal deadline (80% point).\"],\"deadlines\":[\"Fall 2026 (session 001): W period runs after October 9 through November 13, 2026 (last day to withdraw).\",\"Spring 2027 (session 001): W period runs after February 26 through April 9, 2027.\",\"Other sessions: 80% mark of the session (Calendar icon in the Schedule of Classes); 11:59 PM PT.\"],\"costs\":[\"No refund (after the refund deadline).\",\"Late withdrawal by petition: $150 petition fee.\"],\"fields\":[\"course and all linked sections\",\"confirmation that a W will appear\",\"no refund\",\"units remaining and full-time status\",\"financial aid or visa implications\",\"whether an Incomplete is more appropriate (documented emergency after week 12)\"],\"sources\":[{\"url\":\"https://ask.usc.edu/s/article/000001707\",\"title\":\"How do I drop a course with a mark of \u201cW\u201d?\"},{\"url\":\"https://arr.usc.edu/registration-calendar/\",\"title\":\"Registration Calendar - Office of Academic Records and Registrar\"},{\"url\":\"https://arr.usc.edu/grades/\",\"title\":\"Grades - Office of Academic Records and Registrar\"},{\"url\":\"https://ask.usc.edu/s/article/000003067\",\"title\":\"Do grades of W satisfy the continuous enrollment requirement?\"}]},{\"id\":\"order-official-transcript\",\"topic\":\"01\",\"name\":\"Order an official transcript\",\"desc\":\"Student wants an official USC transcript (PDF or paper) sent to themselves or a third party.\",\"system\":\"Experience USC > My Academics > My Transcripts & Verifications (orders processed by Parchment); former students order directly through Parchment\",\"steps\":[\"Check Experience USC for holds and make sure pending grades, degrees or changes have posted.\",\"Log in to Experience USC and go to the My Academics page.\",\"Scroll to 'My Transcripts & Verifications' near the bottom of the page and start an order (Parchment).\",\"Choose PDF or paper, enter the recipient (for PDF, the recipient's email), and any special handling.\",\"Pay by Visa, MasterCard or Discover; the card is pre-authorized and billed when the order is fulfilled.\",\"Track the order on the Parchment site; for PDFs the recipient receives a link email and a passcode email.\"],\"req\":[\"Holds must be cleared before the Transcripts department processes an order.\",\"Online ordering is available to students who have attended USC since 1981.\",\"First-time Parchment users (former students) must sign a Consent to Release form.\",\"PDF recipients must open the file in Adobe Reader/Acrobat 9.0 or higher.\"],\"deadlines\":[\"Special handling requests must be submitted by 12:00 PM PT.\",\"Orders are fulfilled within one business day.\",\"PDF recipients have 30 days from notification to download (three failed passcode tries invalidate it).\"],\"costs\":[\"$12 per PDF transcript.\",\"$15 per paper transcript.\",\"Domestic Overnight Express: $32 per destination plus transcript fee.\",\"International Express Mail: $62 per destination plus transcript fee.\",\"Continuing Education (CEU) transcripts: $15 by mail.\"],\"fields\":[\"format (PDF or paper)\",\"recipient name and email/mailing address\",\"number of copies\",\"delivery method (standard, overnight, international express)\",\"total fee\",\"whether to wait for current-term grades or degree to post\",\"any holds\"],\"sources\":[{\"url\":\"https://arr.usc.edu/transcripts-services/\",\"title\":\"Transcripts Services - Office of Academic Records and Registrar\"}]},{\"id\":\"request-enrollment-verification\",\"topic\":\"01\",\"name\":\"Request an enrollment (or degree/GPA) verification\",\"desc\":\"Student needs official proof of enrollment, degree or GPA for an employer, insurer, lender or other third party.\",\"system\":\"Experience USC > My Academics > Order Transcripts or Verifications (processed by Parchment); alumni order through Parchment\",\"steps\":[\"Check Experience USC for holds and confirm pending grades, degrees or changes have posted.\",\"Log in to Experience USC, select My Academics and scroll to the bottom to choose Order Transcripts or Verifications.\",\"Place the order through Parchment (hard-copy verifications and secure electronic PDF verifications are both available).\",\"Pay the processing fee by Visa, MasterCard or Discover.\",\"Watch for email status notifications; check the order on the Parchment site.\"],\"req\":[\"Requests from students with holds are rejected unless the student is deferring student loans and shows supporting documentation.\",\"The Registrar does not fill out third-party verification forms; the Official Enrollment Verification substitutes for them.\",\"The verification viewable in Experience USC is for personal use and is not official.\",\"Verifications show enrollment history/status, class level, degree objective, units attempted, degrees and expected graduation date; Enrollment Verifications also show semester and cumulative GPA; no course-by-course grades.\",\"Electronic verifications are available to students who first enrolled in 1980 or later.\"],\"deadlines\":[\"Special handling requests by 12:00 PM PT.\",\"Requests are processed Monday through Friday during business hours, except holidays and winter recess.\"],\"costs\":[\"$2 processing fee per online order.\",\"Domestic Overnight Express: $25 per destination plus verification fee.\",\"International Express Mail: $47.50 per destination plus verification fee.\"],\"fields\":[\"type (enrollment, degree, GPA)\",\"recipient and delivery method\",\"terms to be covered\",\"holds on the record\",\"fee total\"],\"sources\":[{\"url\":\"https://ask.usc.edu/s/article/000002176\",\"title\":\"How do I request a verification of my enrollment, degree, or GPA?\"},{\"url\":\"https://arr.usc.edu/verification/\",\"title\":\"Verification - Office of Academic Records and Registrar\"},{\"url\":\"https://ask.usc.edu/s/article/000002510\",\"title\":\"I have a Sibling Verification Form from another organization that I need USC to fill out. How do I get this form completed?\"},{\"url\":\"https://ask.usc.edu/s/article/000003054\",\"title\":\"Can I access my verification online?\"}]},{\"id\":\"update-address-emergency-contact\",\"topic\":\"01\",\"name\":\"Update addresses and emergency contact\",\"desc\":\"Student wants to change their current/permanent or diploma mailing address, or register an emergency contact.\",\"system\":\"Experience USC > My Profile (addresses; Academics tab > Diploma Services for diploma address); USC Housing (confidential emergency contact for residents); MySHR (Student Health emergency contact)\",\"steps\":[\"Log in to myUSC, go to myServices and click Experience USC.\",\"Click your profile icon in the upper right-hand corner and go to My Profile.\",\"Verify your Current Address and Permanent Address; if incorrect, click Edit, enter the correct address and click Save.\",\"For the diploma address: My Profile > Academics tab > Diploma Services > Edit.\",\"Emergency contact (housing residents): register or update your confidential emergency contact with USC Housing.\",\"Emergency contact (health): add it to your profile in MySHR, the Student Health patient portal.\"],\"req\":[\"Online address updates are described for current students.\",\"The Registrar does not keep parent contact information; parents email parentsoftroy@usc.edu.\",\"An invalid address prevents a diploma from being printed.\"],\"deadlines\":[\"none stated (graduating students are told to confirm their mailing address in Experience USC before commencement)\"],\"costs\":[\"none stated\"],\"fields\":[\"which address (current, permanent, diploma)\",\"new address\",\"emergency contact name and phone\",\"which system for the emergency contact (Housing or MySHR)\"],\"sources\":[{\"url\":\"https://ask.usc.edu/s/article/000002071\",\"title\":\"How do current students update their address?\"},{\"url\":\"https://arr.usc.edu/registration-services/\",\"title\":\"Registration Services - Office of Academic Records and Registrar\"},{\"url\":\"https://ask.usc.edu/s/article/000002080\",\"title\":\"Where will USC mail my diploma?\"},{\"url\":\"https://ask.usc.edu/s/article/000002126\",\"title\":\"How can I update my parent's contact information?\"}]},{\"id\":\"set-preferred-name\",\"topic\":\"01\",\"name\":\"Set a preferred (chosen) name and pronouns\",\"desc\":\"Student wants their chosen first name, pronouns or gender identity used in USC systems without a legal name change.\",\"system\":\"Experience USC > My Profile > Personal Info (chosen first name, pronouns, gender identity); OCRC supportive-measures form for NetID, USCard or first-issue diploma\",\"steps\":[\"Go to experience.usc.edu and click your profile icon in the upper right-hand corner, then My Profile.\",\"Scroll to the Personal Info section and click Edit.\",\"In the Update Personal Info window, update Name (First) and select Next.\",\"Confirm the changes and click Update to save.\",\"Pronouns and gender identity are also updated from the Experience USC profile; Brightspace pronouns are set separately under Account Settings.\",\"For a new NetID, a USCard with the chosen name, or a first-issue diploma with the chosen name, complete the OCRC gender identity supportive-measures form.\"],\"req\":[\"Only the chosen first name can be changed in Experience USC; last-name or legal-name changes require the Request for Change/Correction form with documentation.\",\"Changes appear in Brightspace within a day.\",\"NetID changes are requested by the OCRC office; allow up to 2 weeks.\"],\"deadlines\":[\"none stated (the LGBTQ+ Student Center page shows only an outdated 2024 deadline for chosen-name diploma requests)\"],\"costs\":[\"none stated\"],\"fields\":[\"new chosen first name\",\"pronouns\",\"gender identity (optional)\",\"whether a NetID, USCard or diploma change is also wanted\"],\"sources\":[{\"url\":\"https://www.brightspacehelp.usc.edu/students/update-pronouns-and-name-used/\",\"title\":\"Update Pronouns and Name Used \u2013 USC Brightspace Help\"},{\"url\":\"https://ask.usc.edu/s/article/000002151\",\"title\":\"How do I update my name?\"},{\"url\":\"https://lgbtqplus.usc.edu/services-and-resources/transusc/name-and-gender-change/\",\"title\":\"Name and Gender Change - LGBTQ+ Student Center\"},{\"url\":\"https://sites.usc.edu/experience-usc/\",\"title\":\"Experience USC\"}]},{\"id\":\"grant-parent-ferpa-access\",\"topic\":\"01\",\"name\":\"Grant parents/family access to records (FERPA release via OASIS for Guests)\",\"desc\":\"Student wants to let a parent or family member view grades, schedule, degree progress, holds or financial information.\",\"system\":\"Experience USC > My Profile > Guest Access (OASIS for Guests); USCe.pay guest access for billing/payments\",\"steps\":[\"Log in to Experience USC with your USC NetID and password.\",\"Select My Profile, then the Guest Access tab.\",\"Select Create New Guest Access, enter a Guest Login ID and Guest PIN (optionally the guest's email), and click 'I Agree' to authorize release.\",\"Give the guest your 10-digit USC ID, the Guest Login ID and the Guest PIN.\",\"The guest logs in on the OASIS for Guests login page.\",\"Revoke access at any time in Experience USC.\",\"For billing statements and payments, also set up guest access in USCe.pay if needed.\"],\"req\":[\"Only the student can create, revoke and release Guest Login IDs and PINs.\",\"Up to two guest accounts.\",\"Guests can view grades, courses, degree progress, transfer credits, restrictions and financial data; OASIS for Guests does not hold disciplinary or medical records.\",\"Students cannot restrict directory information selectively to only parents.\"],\"deadlines\":[\"none stated; authorization takes effect immediately and lasts until revoked or it expires (the page gives both 'one year after the last term of enrollment' and 'six years after authorization')\"],\"costs\":[\"none stated\"],\"fields\":[\"guest's name/relationship\",\"Guest Login ID and PIN to create\",\"guest email (optional)\",\"which access is wanted (academic via OASIS, billing via USCe.pay)\",\"how to share credentials securely\"],\"sources\":[{\"url\":\"https://arr.usc.edu/oasis-for-guests/\",\"title\":\"OASIS for Guests - Office of Academic Records and Registrar\"},{\"url\":\"https://ask.usc.edu/s/article/000001358\",\"title\":\"How do I set up my parent as a Guest on OASIS?\"},{\"url\":\"https://arr.usc.edu/ferpa-for-parents/\",\"title\":\"FERPA for Parents - Office of Academic Records and Registrar\"},{\"url\":\"https://ask.usc.edu/s/article/000003051\",\"title\":\"How can I pay for my child's account if you can't even tell me how much is owed?\"}]},{\"id\":\"apply-for-graduation-degree-check\",\"topic\":\"01\",\"name\":\"Apply for graduation / check degree progress\",\"desc\":\"Student wants to make sure they are on track to graduate in a specific term and that their degree will be conferred.\",\"system\":\"STARS report and Experience USC (My Profile > Academics > My Degree); Degree Progress (Office of Academic Records and Registrar); school-specific graduation applications (e.g., myViterbi for Viterbi master's)\",\"steps\":[\"Review your STARS report in Experience USC (or request an updated one from your academic advisor) and resolve any unmet requirements with your advisor.\",\"Confirm your expected graduation term: myUSC > Experience USC > My Profile > Academics tab > My Degree; if incorrect, click Edit, select the term and save.\",\"Graduate students: complete your school's graduation application (e.g., Viterbi master's students submit the Application to Graduate on myViterbi by January 22, 2027).\",\"Clear holds and confirm your permanent/diploma mailing address (My Profile > Academics > Diploma Services).\",\"Complete all degree requirements, including submitting supporting documents, by the last day of the term and the term's administrative deadline.\",\"Watch your USC email for the degree conferral email; the diploma is ordered afterward.\"],\"req\":[\"Undergraduates do not need to apply to graduate per the Viterbi graduation checklist; requirements must be complete and the grad term updated on STARS.\",\"Graduate students' prior degrees must be verified before the graduate degree can be awarded.\",\"Students graduating in the current semester are not assigned a Permit to Register.\",\"Name changes must be completed before the student graduates.\",\"If the Edit button is disabled, the degree is already complete or an advisor has not yet set the expected graduation term.\"],\"deadlines\":[\"Administrative deadlines: Fall - January 15; Spring - June 15; Summer - September 15.\",\"Viterbi master's Application to Graduate: January 22, 2027.\",\"Changing the degree date more than three terms ahead: contact the Registrar's office.\"],\"costs\":[\"none stated for applying to graduate\",\"Degree check for former students who last attended before Fall 1998: $300 nonrefundable\"],\"fields\":[\"expected graduation term\",\"degree, major(s) and minor(s)\",\"outstanding STARS requirements\",\"school-specific application and deadline\",\"diploma name and mailing address\",\"holds\"],\"sources\":[{\"url\":\"https://viterbigrad.usc.edu/academic-services/commencement-information/\",\"title\":\"Commencement Information - USC Viterbi Graduate\"},{\"url\":\"https://ask.usc.edu/s/article/000002991\",\"title\":\"How is a student\u2019s degree date determined?\"},{\"url\":\"https://ask.usc.edu/s/article/000002110\",\"title\":\"How do I update my graduation date?\"},{\"url\":\"https://arr.usc.edu/stars-report/\",\"title\":\"STARS Report - Office of Academic Records and Registrar\"}]},{\"id\":\"submit-time-conflict-form\",\"topic\":\"01\",\"name\":\"Request registration in two overlapping classes (Time Conflict form)\",\"desc\":\"Undergraduate wants to be registered in a course that overlaps another course on their schedule.\",\"system\":\"DocuSign 'Approval to Register with a Course Time Conflict' form (linked from the Registrar's Student Forms page), processed by the Registrar One Stop\",\"steps\":[\"Talk with both instructors before starting.\",\"In Web Registration, register for ONE of the conflicting courses.\",\"Open the Time Conflict form in DocuSign; list first the instructor of the course you're registered in, second the instructor of the course to add.\",\"Click BEGIN SIGNING, agree to electronic records, use the gold START button to fill every field, explain your reason in Student Comments, enter section numbers and session codes, then click FINISH.\",\"The form routes to instructor 1, then instructor 2; follow up with each (ask them to check spam/junk).\",\"After both decide, the Registrar One Stop reviews it (typically one to two business days) and emails a copy; confirm the course was added.\",\"Graduate students instead register for one course and email the 5-digit section number(s) of the other via the askUSC Email Us form.\"],\"req\":[\"Only forms submitted via DocuSign are reviewed; printed paper forms are not accepted.\",\"Approval is at both instructors' discretion, with or without conditions.\",\"LAW, MAT, SOWK and Marshall graduate courses: contact the academic department instead.\",\"Courses with a time conflict cannot be registered through Web Registration; the Registrar registers you manually if approved.\"],\"deadlines\":[\"In fall and spring the form becomes available to continuing students during the week of registration; it is unavailable shortly after the spring Schedule of Classes is released in October and in February after the summer/fall schedule is released.\",\"Registration is not permitted after the third week of classes.\"],\"costs\":[\"none stated\"],\"fields\":[\"both courses with 5-digit section numbers and session codes\",\"both instructors' names and emails\",\"which course is already registered\",\"student's reason/comments\",\"undergraduate vs graduate route\"],\"sources\":[{\"url\":\"https://ask.usc.edu/s/article/000002468\",\"title\":\"How do I complete the time conflict form?\"},{\"url\":\"https://ask.usc.edu/s/article/000002427\",\"title\":\"When is the Time Conflict form available?\"},{\"url\":\"https://ask.usc.edu/s/article/000002215\",\"title\":\"Web Registration says I have a time conflict in my schedule. How do I fix this?\"},{\"url\":\"https://ask.usc.edu/s/article/000003022\",\"title\":\"How long does it take to be registered in my courses after submitting a \u201cTime Conflict\u201d registration form?\"}]},{\"id\":\"opt-out-tuition-refund-insurance\",\"topic\":\"01\",\"name\":\"Opt out of (or into) Tuition Refund Insurance\",\"desc\":\"Student wants to decline (or re-add) the Tuition Refund Insurance charge automatically added at registration, or check whether they have it.\",\"system\":\"Web Registration > select term > Tuition Refund Insurance (myTRI) tab\",\"steps\":[\"Log in to myUSC and open Web Registration.\",\"Select the term.\",\"Click the 'Tuition Refund Insurance' / 'myTRI' tab at the top of the page to see your status.\",\"Follow the prompts to opt out (or opt in) and submit your changes.\"],\"req\":[\"Web Registration automatically enrolls students in TRI when they register.\",\"Courses in special sessions outside the main session still require opting out before that term's deadline.\",\"TRI covers one semester; claims require withdrawing from all classes for illness or injury.\"],\"deadlines\":[\"Fall and spring: until the end of the third week of classes (20-percent mark of session 001) - Fall 2026: September 11; Spring 2027: January 29.\",\"Summer: deadline listed in the Schedule of Classes / registration calendar for the term.\"],\"costs\":[\"0.3 of 1 percent of tuition and mandatory fees, charged to the student account if not waived.\"],\"fields\":[\"term\",\"current TRI status\",\"opt in or opt out\",\"deadline check\"],\"sources\":[{\"url\":\"https://ask.usc.edu/s/article/000003012\",\"title\":\"How do I purchase or opt out of Tuition Refund Insurance?\"},{\"url\":\"https://ask.usc.edu/s/article/000003064\",\"title\":\"How much does Tuition Refund Insurance cost?\"},{\"url\":\"https://ask.usc.edu/s/article/000002570\",\"title\":\"How do I find out if I have Tuition Refund Insurance?\"},{\"url\":\"https://arr.usc.edu/registration-calendar/\",\"title\":\"Registration Calendar - Office of Academic Records and Registrar\"}]},{\"id\":\"submit-registration-petition\",\"topic\":\"01\",\"name\":\"Submit a registration petition (missed deadline)\",\"desc\":\"Student wants a retroactive registration change (late add, late withdrawal, delete, late grading-option or unit change) because of a registration error or extenuating circumstance.\",\"system\":\"Petition Services, Office of Academic Records and Registrar: Registration Petition Inquiry Form; fee paid through the petition fee storefront\",\"steps\":[\"Consult your instructor(s), academic advisor and any affected offices (Financial Aid, Student Financial Services, OIS) about the implications.\",\"Complete the Registration Petition Inquiry Form (fillable PDF; complete it electronically, not handwritten) describing the request and what prevented you from meeting the deadline.\",\"Attach supporting documentation substantiating your claims (e.g., a police report; for health issues, a medical summary sheet rather than medical records).\",\"Petition Services contacts your instructors (and other offices, depending on type).\",\"Pay the $150 petition fee (select Registration Petition Fee on the payment page); no decision is made until payment is received.\",\"Follow up with Petition Services; the Registrar reviews first, and denied/deferred petitions go to CAPP (delete petitions get one review only).\"],\"req\":[\"Registration petitions are for registration errors or extenuating circumstances, not GPA or financial purposes; being unaware of a deadline is not a registration error.\",\"Not eligible if you have graduated or discontinued enrollment, or if a hold prevented the registration change.\",\"Delete petitions: only one per matriculation; not eligible if you attended past the add/drop deadline; cannot be combined with a Tuition Refund Insurance claim.\",\"Petitions cannot be expedited.\"],\"deadlines\":[\"Within two years of the term; a department No Objection Memo can extend this up to five years.\",\"Average processing time about two weeks.\",\"Late-registration special consideration memos are due the Wednesday after the registration deadline.\"],\"costs\":[\"$150 petition fee, charged once Petition Services receives a complete inquiry, regardless of outcome; waived for OSAS-verified disability, approved Student Health Leave, Title IX accommodation, or if another department pays.\"],\"fields\":[\"petition type (late add, late withdrawal, delete, grading option, unit value)\",\"term and course/section\",\"what prevented meeting the deadline\",\"supporting documentation\",\"dates of first/last attendance and participation (delete petitions)\",\"awareness of the $150 fee\"],\"sources\":[{\"url\":\"https://ask.usc.edu/s/article/000001751\",\"title\":\"How do I initiate a Registration Petition?\"},{\"url\":\"https://ask.usc.edu/s/article/000002473\",\"title\":\"When and how is the petition fee assessed?\"},{\"url\":\"https://ask.usc.edu/s/article/000002522\",\"title\":\"How soon do petition inquiries need to be submitted?\"},{\"url\":\"https://arr.usc.edu/petition-services/\",\"title\":\"Petition Services - Office of Academic Records and Registrar\"}]},{\"id\":\"restrict-directory-information\",\"topic\":\"01\",\"name\":\"Restrict release of directory information (FERPA)\",\"desc\":\"Student wants USC to stop releasing directory information (address, phone, email, enrollment, degrees, etc.) without consent.\",\"system\":\"Student Request to Restrict Directory Information form, emailed to gtv@usc.edu (Office of Academic Records and Registrar)\",\"steps\":[\"Download and complete the Student Request to Restrict Directory Information form (choose online directory only, or all directory information).\",\"Email the completed form to gtv@usc.edu.\",\"Renew the request at the beginning of each academic year.\"],\"req\":[\"The restriction can't be selective (e.g., releasing only to parents).\",\"Restricted students won't appear in the Commencement Bulletin or other university publications, and employers, lenders and scholarship committees will be told USC has no information.\",\"Directory information can otherwise be released without consent.\"],\"deadlines\":[\"Must be renewed at the beginning of each academic year.\"],\"costs\":[\"none stated\"],\"fields\":[\"scope (online directory only vs all directory information)\",\"awareness of consequences\",\"academic year for the request\"],\"sources\":[{\"url\":\"https://arr.usc.edu/ferpa-for-students/\",\"title\":\"FERPA for Students - Office of Academic Records and Registrar\"},{\"url\":\"https://ask.usc.edu/s/article/000003052\",\"title\":\"Can a student have directory information released to just their parents?\"},{\"url\":\"https://ask.usc.edu/s/article/000003048\",\"title\":\"How can someone tell if a student has requested that directory information not be disclosed?\"}]},{\"id\":\"order-replacement-diploma\",\"topic\":\"01\",\"name\":\"Order a replacement diploma\",\"desc\":\"Graduate wants a new diploma because the original was lost, stolen or damaged, or needs a duplicate.\",\"system\":\"Office of Academic Records and Registrar diploma ordering process (Diploma replacement option, 'Order Now' on the Diplomas page)\",\"steps\":[\"Go to the Registrar's Diplomas page and use the ordering process, selecting the Diploma replacement option.\",\"Provide: full name used at USC, 10-digit USC ID (if applicable), dates of attendance, date of birth, major/degree, and the mailing address.\",\"Pay the replacement fee.\",\"Email the Registrar to check status if needed.\"],\"req\":[\"The replacement bears the names of officials in office when it is produced.\",\"Records before 1980 need extra research time (microfilm).\",\"Holds or an invalid address can prevent printing.\"],\"deadlines\":[\"Processing may take four to six weeks from ordering.\"],\"costs\":[\"$125 replacement diploma fee.\",\"Certified electronic diploma (CeDiploma), if wanted: $16.95.\"],\"fields\":[\"name to print (as used at USC)\",\"USC ID\",\"degree/major\",\"dates of attendance\",\"date of birth\",\"mailing address\",\"fee\"],\"sources\":[{\"url\":\"https://arr.usc.edu/diploma/\",\"title\":\"Diplomas - Office of Academic Records and Registrar\"},{\"url\":\"https://arr.usc.edu/tuition-and-fees/\",\"title\":\"Tuition and Fees - Office of Academic Records and Registrar\"}]},{\"id\":\"book-academic-advising-appointment\",\"topic\":\"02\",\"name\":\"Book an academic advising appointment\",\"desc\":\"Student wants to schedule an in-person or Zoom meeting with their assigned academic advisor (e.g., required pre-registration/mandatory advising, course planning, major questions).\",\"system\":\"Advise USC (usc.edu/advise; also reachable from the myUSC 'Advise USC' module or Experience USC)\",\"steps\":[\"Log in to Advise USC (usc.edu/advise, or open it from myUSC / Experience USC).\",\"In the My Appointments section, click 'Schedule an Appointment'.\",\"Click 'Assigned' and select your assigned advisor's name (Dornsife students may choose any advisor on their case team).\",\"Under 'Select a Topic', choose a topic and subtopic.\",\"Select the earliest date and time that works for you.\",\"Add a comment describing what you want to discuss (major/minor interests, goals, questions).\",\"Proceed to schedule the appointment; to change it later go to My Appointments and click 'Reschedule or Cancel'.\",\"If no time works, go to Advisor Connect > 'Create a New Case' to request an appointment and include your availability.\"],\"req\":[\"You must be assigned to (or referred to) the advising office; for an office not on your Success Team, submit an Advise USC referral first.\",\"AEA appointments must be booked at least 24 hours in advance (in person or Zoom).\",\"Dornsife: a minimum of one advising appointment is required each semester; mandatory advising (weeks 6-12) is required to enroll in the upcoming term.\",\"Mandatory advising holds can only be lifted by your declared major's advisor.\",\"Some schools (e.g., Thornton) email booking instructions 3 business days before your advisement week.\"],\"deadlines\":[\"Dornsife mandatory advising: semester weeks 6-12 (Dornsife first-years: Pre-Registration Advising weeks 7-13).\",\"Complete required advising before your Permit to Register opens.\",\"Thornton undergraduate pre-registration advisement for Spring 2027 began Oct 5 (96+ units), Oct 19 (64-95), Oct 28 (32-63), Nov 6 (0-31).\"],\"costs\":[\"none stated\"],\"fields\":[\"student's school/major (determines advisor or case team)\",\"appointment purpose/topic and subtopic\",\"in-person vs Zoom\",\"preferred date and time (at least 24 hours out for AEA)\",\"comment/questions to include\",\"whether this is the required mandatory/pre-registration appointment\"],\"sources\":[{\"url\":\"https://academicprograms.usc.edu/offices-and-units/academic-exploration-advising/connect-with-an-aea-advisor/appointments-and-drop-in-advising/\",\"title\":\"Appointments and Drop-in Advising - Office of Academic Programs\"},{\"url\":\"https://academicprograms.usc.edu/offices-and-units/academic-exploration-advising/connect-with-an-aea-advisor/declared-advising/\",\"title\":\"Declared Advising - Office of Academic Programs\"},{\"url\":\"https://dornsife.usc.edu/advising/faqs-2/\",\"title\":\"FAQs - Dornsife Undergraduate Academic Advising\"},{\"url\":\"https://dornsife.usc.edu/advising/academic-advising/\",\"title\":\"Advising Appointments - Dornsife Undergraduate Academic Advising\"}]},{\"id\":\"view-degree-progress-report\",\"topic\":\"02\",\"name\":\"View my degree progress (STARS report)\",\"desc\":\"Student wants to see which degree requirements (GE, writing, language, major, minor, GPA) are complete or remaining, or explore a what-if major/minor.\",\"system\":\"Experience USC > My Academics (STARS report and STARS Interactive Audit); updates requested through the academic advisor / Degree Progress\",\"steps\":[\"Log in to myUSC and open Experience USC.\",\"Go to the My Academics page and open your STARS report.\",\"Review requirements: skill level, General Education, major, minor and GPA, including in-progress and transfer coursework.\",\"Optional: open the STARS Interactive Audit (STARS IA) to explore alternative majors/minors and view Course History (GPA by term).\",\"If the report is outdated or wrong, ask your academic advisor to request an updated STARS report; contact Degree Progress if transfer coursework is missing.\",\"View/print the updated report on Experience USC (note it is not an official university document).\"],\"req\":[\"Undergraduate STARS reports update each fall and spring immediately after the Add/Drop deadline.\",\"Graduate STARS reports are made available when the advisor submits an application.\",\"STARS isn't available for undergraduates on catalogue years before 1985, master's before 1997, or doctoral before 1994.\",\"STARS is not an official university document (employers may not accept it).\"],\"deadlines\":[\"Automatic undergraduate updates follow each fall/spring Add/Drop deadline (Spring 2027 session 001: January 29, 2027 is the last day to register/drop with refund).\"],\"costs\":[\"none stated\"],\"fields\":[\"undergraduate or graduate\",\"which program(s)/catalogue year to review\",\"whether an advisor-requested update is needed\",\"what-if major/minor to explore\",\"specific requirement that looks wrong\"],\"sources\":[{\"url\":\"https://arr.usc.edu/stars-report/\",\"title\":\"STARS Report - Office of Academic Records and Registrar\"},{\"url\":\"https://ask.usc.edu/s/article/000003083\",\"title\":\"How do I request a STARS report or obtain a new copy if I lost my report?\"},{\"url\":\"https://ask.usc.edu/s/article/000003085\",\"title\":\"Can I use the STARS report to prove to a prospective employer that I am near graduation? Is the STARS report an official university document?\"},{\"url\":\"https://music.usc.edu/students/advising-process-majors/\",\"title\":\"Advising Process For Majors | USC Thornton School of Music\"}]},{\"id\":\"declare-change-major-or-minor\",\"topic\":\"02\",\"name\":\"Declare/change a major or add a minor\",\"desc\":\"Student wants to switch majors, add a second major, add a minor, or drop a minor/second major.\",\"system\":\"The academic school offering the program (its advising/admission office and application, e.g., Marshall internal transfer application, Viterbi Pre-Engineering Interest Form, AEA via Advise USC); the school's advisor adds the PoSt/minor code to the record\",\"steps\":[\"Find the program in the USC Catalogue ('Programs, Minors and Certificates') and check whether it is selective (separate application) or open (declared with advising staff).\",\"Review the offering school's advising/admission website for requirements and deadlines (e.g., Marshall internal transfer page, Viterbi Pre-Engineering page, Marshall minors page).\",\"Contact the offering school (drop-in advising, Advise USC referral/support case, or email) with remaining questions.\",\"Complete any prerequisite or pre-application courses (Marshall: WRIT 140/150, MATH 118+, ECON 351x; Viterbi: interest form plus three pre-engineering courses with B+ or better, 14-18 units per semester and a 3.5+ cumulative USC GPA).\",\"Submit the school's application if selective (e.g., Marshall internal transfer application) or meet with the school's advisor to declare if open.\",\"Once approved, the school's advisor updates your record by adding the PoSt (major) or minor code.\",\"Check your STARS report and update your course plan with your advisor(s).\",\"To drop a minor or second major, ask your academic advisor to expire it from your record.\"],\"req\":[\"Selective majors have no open declaration and no guaranteed admission.\",\"Some open majors have minimum GPAs (Gerontology 2.0, Keck 3.0, select Price programs 2.0).\",\"Exploratory students should declare before Junior standing (64 units); students with 64+ units can't change their major to Exploratory.\",\"Marshall internal transfer: apply no more than twice; applying before 64 units strongly recommended; no unresolved grades.\",\"Marshall minors: 32-48 completed units, a declared major, minimum 2.75 USC GPA; max three Marshall courses before admission.\",\"Progressive degree students changing majors must submit a new signed course plan and a Change of Major form.\",\"Viterbi Pre-Engineering: 14-18 units per semester, 3.5+ cumulative USC GPA and B+ or better in each of the three pre-engineering courses, or you will not be admitted (students who applied before March 25, 2026 are reviewed under previous criteria).\"],\"deadlines\":[\"Marshall internal transfer (Fall 2026 application): due Friday, December 4, 2026.\",\"Viterbi Pre-Engineering: application window opens at the end of each fall, spring and summer term.\",\"Marshall minors: applications accepted throughout the year (decisions typically within 10 business days).\"],\"costs\":[\"none stated\"],\"fields\":[\"current major(s)/minor(s)\",\"target program and offering school\",\"action type: add, change or drop\",\"units completed and cumulative USC GPA\",\"status of required prerequisite courses\",\"application cycle and deadline\",\"impact on expected graduation date and course plan\"],\"sources\":[{\"url\":\"https://ask.usc.edu/s/article/000002737\",\"title\":\"How do I change my major/home department as an undergraduate?\"},{\"url\":\"https://academicprograms.usc.edu/offices-and-units/academic-exploration-advising/what-is-exploratory/\",\"title\":\"What is Exploratory? - Office of Academic Programs\"},{\"url\":\"https://students.marshall.usc.edu/current-students/applying-marshall-current-usc-students/business-administration-major\",\"title\":\"Business Administration Major | USC Marshall\"},{\"url\":\"https://students.marshall.usc.edu/current-students/applying-marshall-current-usc-students/marshall-minors\",\"title\":\"Marshall Minors | USC Marshall\"}]},{\"id\":\"book-kortschak-coaching\",\"topic\":\"02\",\"name\":\"Book a Kortschak Center academic coaching session\",\"desc\":\"Student wants help with time management, study strategies, organization or procrastination through a one-time or weekly coaching appointment.\",\"system\":\"Kortschak Center for Learning and Creativity: online intake survey that returns a Calendly scheduling link; returning students email kortschakcenter@usc.edu\",\"steps\":[\"Go to the KCLC Academic Coaching page (kortschakcenter.usc.edu).\",\"Fill out the coaching survey linked on the page.\",\"Use the Calendly link you receive to book a 30-minute One-Time Coaching Appointment (up to 10 days ahead, at least 6 hours before).\",\"Attend the appointment at KCLC (Student Union, Room 311) or online.\",\"For weekly coaching (undergraduates only), tell your coach at the one-time appointment that you're interested; it's a 6-week commitment at the same time each week.\",\"Returning coaching students instead email kortschakcenter@usc.edu with past semesters, past coach names, online vs in-person preference, and availability (10 AM-4 PM, Mon-Fri).\"],\"req\":[\"Academic support is free for enrolled USC students.\",\"One-time appointments: all undergraduate and graduate students; weekly coaching: undergraduates only, after a one-time appointment.\",\"Online coaching requires video access and is currently limited to Mondays.\",\"Coaching is not subject tutoring, homework help or paper editing.\"],\"deadlines\":[\"Weekly coaching enrollment open until November 2026.\",\"Fall 2026 hours 9:30 AM-5:00 PM; closed for Labor Day and Thanksgiving Break.\"],\"costs\":[\"Free for enrolled USC students\"],\"fields\":[\"one-time vs weekly coaching\",\"undergraduate or graduate status\",\"online vs in person\",\"preferred date/time within the next 10 days\",\"topics to work on (time management, study strategies, etc.)\",\"returning-student details (past semesters/coach)\"],\"sources\":[{\"url\":\"https://kortschakcenter.usc.edu/programs-services/academic-coach-program/\",\"title\":\"Academic Coaching \u2013 Kortschak Center For Learning and Creativity\"},{\"url\":\"https://kortschakcenter.usc.edu/\",\"title\":\"Kortschak Center For Learning and Creativity\"}]},{\"id\":\"book-writing-center-appointment\",\"topic\":\"02\",\"name\":\"Book a Writing Center appointment\",\"desc\":\"Student wants feedback on a paper, application essay, cover letter or other writing from a Writing Center consultant.\",\"system\":\"USC Writing Center online scheduler (usc.mywconline.com)\",\"steps\":[\"Open the Writing Center Appointments page and click 'Click here to book an appointment' (usc.mywconline.com); log in.\",\"Choose an open slot: daytime (9am-5pm) appointments can be in person (Taper Hall 216) or online; evening appointments (after 5pm) are online.\",\"On the Appointment Form, set the length: it defaults to 30 minutes; extend to 60 minutes by adjusting the 'stop-time' field.\",\"Avoid booking a consultant who is currently your TA or instructor.\",\"Attend on time with your writing; the session ends if you're more than 15 minutes late.\"],\"req\":[\"Open to current USC students, faculty and staff.\",\"Two 25-minute or one 50-minute appointment per week; complete the first before booking the second.\",\"No proofreading; no help with take-home exams unless the instructor emails permission to writing@usc.edu.\",\"Consultants only help with your own work and won't discuss grades.\"],\"deadlines\":[\"Fall 2026 operating period: August 31 - December 4; Mon-Thu 10am-8pm (online or in person), Fri 10am-4pm (online).\"],\"costs\":[\"Free (all Writing Center services are free)\"],\"fields\":[\"25 vs 50 minutes\",\"in-person vs online\",\"date and time\",\"type of writing and stage (e.g., brainstorming, draft)\",\"whether the student already used this week's appointment allowance\"],\"sources\":[{\"url\":\"https://dornsife.usc.edu/writingcenter/appointments/\",\"title\":\"Appointments - USC Dornsife Writing Center\"},{\"url\":\"https://dornsife.usc.edu/writingcenter/about-us/\",\"title\":\"About Us - USC Dornsife Writing Center\"},{\"url\":\"https://dornsife.usc.edu/writingcenter/\",\"title\":\"Welcome to the Writing Center - USC Dornsife Writing Center\"}]},{\"id\":\"apply-study-abroad\",\"topic\":\"02\",\"name\":\"Apply to a semester/year study abroad program\",\"desc\":\"Student wants to apply to a USC Dornsife Overseas Studies semester or year program (or Pembroke Cambridge Summer Programme).\",\"system\":\"USC Dornsife Office of Overseas Studies online application (via program pages on studenttravelabroad.usc.edu) plus the host institution's own application; advising via AdviseUSC referral\",\"steps\":[\"Confirm eligibility: 3.0+ cumulative USC GPA, third semester or later, enrolled at USC the prior semester, language prerequisite met, no disqualifying conduct status.\",\"Choose a program (Programs by Major / by Region); optionally self-refer to an Overseas Studies advisor in AdviseUSC and attend the Study Abroad Fair (week 3).\",\"Make sure you have a passport valid at least six months after the program ends (or proof you've applied).\",\"Meet your academic advisor(s) to complete and sign the Course Pre-Approval Form.\",\"Request your recommendation letter(s) or questionnaire and write a 300-600 word personal statement.\",\"Order an official USC transcript through Parchment ($12 per PDF), email it to yourself and upload it.\",\"Submit the Overseas Studies application by the USC deadline (only one program unless applying to a 'more selective' program plus one backup).\",\"Apply separately to the host institution by its deadline (not required for USC Paris and USC Madrid).\",\"Complete the interview and conduct check; await decisions from USC (usually 3-4 weeks after the deadline) and the host (2-8 weeks).\"],\"req\":[\"Minimum 3.0 cumulative USC GPA at the time of application (some programs higher).\",\"Third semester at USC is the earliest semester abroad; transfers after two semesters at USC.\",\"Language: completed, enrolled in, or tested out of at least the second semester of the host-country language (if taught at Dornsife).\",\"Maximum two semester programs or one year-long program; cannot study abroad after completing graduation requirements.\",\"Students on disciplinary probation or deferred suspension in the prior or planned semester are not eligible.\",\"GE and WRIT requirements cannot be completed abroad; courses abroad appear as Credit/No Credit (except USC Paris/Madrid catalogue courses).\"],\"deadlines\":[\"Spring 2027: closed (Spain deadline August 3, 2026; all others September 10, 2026).\",\"Fall 2027 / Academic Year 2027-28: applications open in December (mid-December); due mid-February.\",\"Pembroke Cambridge Summer Programme: opened October 26; due mid-December.\"],\"costs\":[\"Official USC transcript: $12 per PDF.\",\"USC tuition ($37,692 per semester, 2026-27) for USC Madrid, USC Paris, CUHK, Sciences Po and Trinity College Dublin exchanges; other programs: host tuition plus a $5,000 administrative fee.\",\"Commitment fee (amount on the program cost sheet) if withdrawing after the Overseas Studies withdrawal deadline.\"],\"fields\":[\"program and term\",\"cumulative USC GPA and number of semesters completed\",\"language level for the destination\",\"advisor-signed course pre-approval status\",\"host institution deadline\",\"passport validity\",\"financial aid/scholarship plans and estimated cost\"],\"sources\":[{\"url\":\"https://dornsife.usc.edu/overseas-studies/apply/\",\"title\":\"How to Apply - Office of Overseas Studies\"},{\"url\":\"https://dornsife.usc.edu/overseas-studies/eligibility/\",\"title\":\"Eligibility - Office of Overseas Studies\"},{\"url\":\"https://dornsife.usc.edu/overseas-studies/\",\"title\":\"Home Page - Office of Overseas Studies\"},{\"url\":\"https://dornsife.usc.edu/overseas-studies/finances-cost-aid-scholarships/\",\"title\":\"Finances - Cost, Aid, Scholarships - Office of Overseas Studies\"}]},{\"id\":\"request-advise-usc-referral\",\"topic\":\"02\",\"name\":\"Request an advising referral (e.g., Overseas Studies, Pre-Health, Exploratory)\",\"desc\":\"Student wants to connect with an advising office not on their Success Team (study abroad, pre-health, exploratory/AEA, Marshall/Accounting major).\",\"system\":\"Advise USC > Advisor Connect > Create a New Case > 'Get a referral to an academic department or special program'\",\"steps\":[\"Log in to Advise USC (from myUSC).\",\"Open the 'Advisor Connect' tab and click 'Create a New Case'.\",\"Select 'Get a referral to an academic department or special program'.\",\"Search for and select the program (e.g., Overseas Studies, Pre-Health, Exploratory, BA) and choose a referral reason.\",\"Add comments (e.g., region of interest, reason for referral) and submit.\",\"Watch your USC email for confirmation and complete any required steps.\",\"After processing, find the new advisor on your Success Team and schedule an appointment.\"],\"req\":[\"Overseas Studies: allow 1 business day for processing.\",\"AEA: continuing-student referrals processed in a minimum of three business days; new students after first-semester registration.\",\"Being referred to AEA doesn't change your major; your declared major advisor still lifts mandatory advising holds.\"],\"deadlines\":[\"not stated on USC sites\"],\"costs\":[\"none stated\"],\"fields\":[\"program/office to be referred to\",\"reason for referral\",\"comments to include\",\"whether the student also wants to change majors\"],\"sources\":[{\"url\":\"https://dornsife.usc.edu/overseas-studies/study-abroad-advisors/\",\"title\":\"Meet Our Staff - Office of Overseas Studies\"},{\"url\":\"https://academicprograms.usc.edu/offices-and-units/academic-exploration-advising/connect-with-an-aea-advisor/referred-advising/\",\"title\":\"Referred Advising - Office of Academic Programs\"},{\"url\":\"https://dornsife.usc.edu/pre-health/pre-health-on-advise-usc/\",\"title\":\"Book an Appointment - Dornsife Pre-Health Advisement Office\"},{\"url\":\"https://students.marshall.usc.edu/current-students/applying-marshall-current-usc-students/business-administration-major\",\"title\":\"Business Administration Major | USC Marshall\"}]},{\"id\":\"book-academic-counselor-appointment\",\"topic\":\"02\",\"name\":\"Book an Academic Counselor appointment (Academic Notice)\",\"desc\":\"Student on Academic Notice (or seeking readmission) needs to meet their Academic Counselor to register or meet the three-meetings-per-semester requirement.\",\"system\":\"Advise USC (Office of Academic Counseling, Office of Academic Records and Registrar, FIG 107)\",\"steps\":[\"Sign in to Advise USC.\",\"Click the blue 'Schedule Appointment' box.\",\"Select 'Teams' and the name of your Academic Counselor.\",\"Choose 'General Academic Advice' and then 'Academic Performance'.\",\"Pick a date and time from the available appointments and click 'Submit'.\",\"Complete the pre-assessment survey your counselor sends before your first appointment.\",\"To register, bring the Academic Counseling Advisement Record form signed by your departmental advisor and an authorized school representative.\"],\"req\":[\"Students on Academic Notice must meet their Academic Counselor at least three times per semester.\",\"Before registering, meet both your departmental advisor and your Academic Counselor and clear all holds/departmental clearances.\",\"Registration-related changes are completed in person with the Academic Counselor; only courses on the advisement form can be added.\"],\"deadlines\":[\"Spring 2027 classes begin January 11, 2027; last day to register/add for session 001 is January 29, 2027.\"],\"costs\":[\"none stated for counseling appointments; Petition for Readmission fee is $125 (non-waivable) if disqualified\"],\"fields\":[\"student's academic standing (Academic Notice vs disqualified)\",\"Academic Counselor name\",\"appointment date/time\",\"whether the Academic Counseling Advisement Record form is completed and signed\",\"courses approved for registration\"],\"sources\":[{\"url\":\"https://arr.usc.edu/academic-counseling/\",\"title\":\"Academic Counseling - Office of Academic Records and Registrar\"},{\"url\":\"https://ask.usc.edu/s/article/000002237\",\"title\":\"What Are Academic Disqualification and Readmission?\"},{\"url\":\"https://arr.usc.edu/registration-calendar/\",\"title\":\"Registration Calendar - Office of Academic Records and Registrar\"}]},{\"id\":\"request-gesm-dclearance\",\"topic\":\"02\",\"name\":\"Request GESM D-clearance (juniors/seniors)\",\"desc\":\"A junior or senior who never completed the GE Seminar wants a seat in a GESM for Spring 2027.\",\"system\":\"Email to the General Education Program office (gened@usc.edu), then register in Web Registration\",\"steps\":[\"Pick five preferred GESM sections in the Spring 2027 Schedule of Classes and note their five-digit section numbers.\",\"On or after December 1, 2026, email gened@usc.edu with your name, USC student ID number and the five section numbers.\",\"Wait for the GE office's reply (it plans to respond within two business days).\",\"Once D-cleared, register for the section in Web Registration during/after your registration appointment.\"],\"req\":[\"For juniors and seniors who have not fulfilled the GESM requirement (freshmen/sophomores register without D-clearance).\",\"Students with priority registration and sophomore standing had to request by Monday, October 26 (three preferred sections).\",\"Transfer students don't need a GESM; Thematic Option students may not take GESM.\"],\"deadlines\":[\"Juniors/seniors: requests accepted on or after December 1, 2026.\",\"GESM seat-add dates (9:00 am): Nov 10, 11, 12, 16, 17, 18.\"],\"costs\":[\"none stated\"],\"fields\":[\"class standing\",\"whether GESM is still unfulfilled on STARS\",\"five preferred GESM section numbers\",\"USC ID number\"],\"sources\":[{\"url\":\"https://dornsife.usc.edu/ge/registration/\",\"title\":\"Registration Information - General Education Program\"},{\"url\":\"https://dornsife.usc.edu/ge/policies/\",\"title\":\"Policies - General Education Program\"},{\"url\":\"https://dornsife.usc.edu/thematic-option/current-students/faq-current-students/\",\"title\":\"FAQ - Current Students - Thematic Option Honors Program\"}]},{\"id\":\"pay-balance-usce-pay\",\"topic\":\"03\",\"name\":\"Pay a balance in USCe.pay\",\"desc\":\"Student (or an invited guest payer) wants to pay all or part of the current student account balance online before the due date.\",\"system\":\"USCe.pay, opened from Experience USC \u2192 Finances & Billing \u2192 Pay My Bill (USCe.pay); guests use \\\"Log in to USCe.pay for Guests\\\" on the SFS Guest Users page\",\"steps\":[\"Log in to Experience USC and open Pay My Bill (USCe.pay) from the Finances & Billing menu (guest payers: log in through \\\"Log in to USCe.pay for Guests\\\" on the SFS Guest Users page; USCe.pay is on the My Services page).\",\"Check the account balance and confirm the due date and minimum due on the latest billing statement (eBill).\",\"Select \\\"Make Payment\\\", then \\\"Tuition and Fees\\\"; verify the amount you wish to pay and click \\\"Checkout\\\" (the flow SFS documents in its Flywire wire-payment instructions).\",\"Choose how to pay: electronic transfer (web check/ACH) from a checking or savings account, optionally saved as an ACH payment profile, or a wire option (Flywire redirects you to its site, where payment must be completed within two business days).\",\"After paying, print or save the e-receipt and confirm the payment appears in recent account activity.\"],\"req\":[\"Credit and debit cards are not accepted for tuition, fees or other student-account charges (since July 1, 2020).\",\"A check or electronic funds transfer returned by the bank for any reason incurs a $25 returned item fee, and returned items void outstanding deferments.\",\"Student loan payments (Perkins, Health Professions, Loans for Disadvantaged Students, academic loans) cannot be made in USCe.pay; they go through ECSI.\",\"Wire payments take 2\u20135 business days after the sending bank initiates them and are credited once funds reach USC's bank.\",\"Guests must first be invited by the student (My Account \u2192 Payers \u2192 \\\"Send a payer invitation\\\").\"],\"deadlines\":[\"Spring 2027 settlement deadline: January 8, 2027 at 5 p.m. Pacific time (charges paid or deferred, or payment plan enrolled).\",\"Current and upcoming monthly due dates: 11/13/26 (statement 10/17/26), 12/11/26 (statement 11/14/26), 1/8/27 (statement 12/12/26), 2/12/27, 3/19/27, 4/16/27, 5/14/27, 6/18/27.\",\"Spring 2027 late fees of $100 are assessed January 8, January 15 and January 22, 2027 if unpaid; a 12% annual finance charge applies monthly to balances not paid by the monthly due date.\"],\"costs\":[\"No USC fee for paying online is stated; USC does not charge for Flywire or Convera (the payer's bank may).\",\"$25 returned item fee if the payment is returned.\"],\"fields\":[\"student name and 10-digit USC ID\",\"which charges/term the payment covers\",\"payment amount (full balance vs. minimum due)\",\"payment method (U.S. bank account ACH vs. Flywire/Convera wire)\",\"bank account or saved payment profile to use\",\"due date being met (e.g., January 8, 2027, 5 p.m. PT)\"],\"sources\":[{\"url\":\"https://sfs.usc.edu/epay/\",\"title\":\"Log In to USCe.pay \u2013 Student Financial Services\"},{\"url\":\"https://sfs.usc.edu/payment/wire-transfers/\",\"title\":\"Wire Transfer \u2013 Student Financial Services\"},{\"url\":\"https://sfs.usc.edu/updated-forms-of-payment/\",\"title\":\"Updated Policy on Credit Card Payments for Tuition and Fees \u2013 Student Financial Services\"},{\"url\":\"https://sfs.usc.edu/student-account/common-fees/\",\"title\":\"Common Fees and Transactions \u2013 Student Financial Services\"}]},{\"id\":\"enroll-payment-plan\",\"topic\":\"03\",\"name\":\"Enroll in the USC Payment Plan\",\"desc\":\"Student (or approved guest) wants to split a fall or spring term's charges (tuition, fees, housing, meal plan, other university charges) into interest-free monthly installments.\",\"system\":\"USCe.pay \u2192 Payment Plans (U.S. bank accounts); Flywire International Payment Plan via Experience USC \u2192 Finances and Billing\",\"steps\":[\"USCe.pay plan (U.S. bank account): log in to USCe.pay (Experience USC \u2192 Finances & Billing) and select Payment Plans.\",\"Pay the $75 non-refundable application fee.\",\"Make the down payment.\",\"Set up automatic deductions from a U.S. checking or savings account; deductions are processed on the 3rd of each month.\",\"Flywire International Payment Plan (alternative): log in to Experience USC and select \\\"Flywire International Payment Plan\\\" under Finances and Billing.\",\"Select your plan, enter the amount you wish to finance in \\\"Balance for Plan\\\", and activate the plan.\",\"Arrange the first payment, including the $75 non-refundable application fee (payment options depend on the chosen country); complete each monthly installment no later than the 3rd of each month.\",\"When setting the plan budget, account for possible changes to your charges; the plan is not adjusted automatically.\"],\"req\":[\"Must be registered for classes for the upcoming term.\",\"Student account must be current.\",\"Plan must be renewed every semester; not available for summer term.\",\"Most students: down payment plus four monthly installments (August\u2013December or January\u2013May); trimester programs: down payment plus three installments (August\u2013November, December\u2013March or April\u2013July).\",\"USC may cancel the plan for failure to pay when due; a past-due plan triggers an SFS 05 hold.\",\"A refund on an account with an active plan requires a plan budget change first.\"],\"deadlines\":[\"Spring 2027 enrollment periods: Transact Regular 12/14/2026\u20131/29/2027; Transact Trimester 11/14/2026\u20131/29/2027; International Regular 12/09/2026\u20132/2/2027; International Trimester 11/25/2026\u20132/2/2027.\",\"To avoid late fees, enroll (or pay/defer) by the Spring 2027 settlement deadline: January 8, 2027, 5 p.m. Pacific time.\",\"Automatic deductions/installments: the 3rd of each month.\"],\"costs\":[\"$75 non-refundable application fee per term.\",\"Down payment (amount not stated on USC pages).\",\"Installments are interest-free.\"],\"fields\":[\"term (e.g., Spring 2027)\",\"plan type (USCe.pay regular or trimester vs. Flywire international)\",\"amount to finance / plan budget\",\"down payment amount\",\"U.S. checking or savings account for automatic deductions (USCe.pay plan)\",\"acknowledgment of the $75 non-refundable fee\",\"installment schedule (3rd of each month)\"],\"sources\":[{\"url\":\"https://sfs.usc.edu/payment/plan/\",\"title\":\"Payment Plans \u2013 Student Financial Services\"},{\"url\":\"https://sfs.usc.edu/deadlines/\",\"title\":\"Dates and Deadlines \u2013 Student Financial Services\"},{\"url\":\"https://sfs.usc.edu/student-account/holds/\",\"title\":\"Removing a Hold \u2013 Student Financial Services\"},{\"url\":\"https://sfs.usc.edu/refunds/\",\"title\":\"Refunds \u2013 Student Financial Services\"}]},{\"id\":\"add-authorized-payer\",\"topic\":\"03\",\"name\":\"Add a parent or other authorized payer (guest user)\",\"desc\":\"Student wants a parent or other third party to be able to view the bill and make payments (and optionally see academic records).\",\"system\":\"USCe.pay \u2192 My Account \u2192 Payers \u2192 \\\"Send a payer invitation\\\" (USCe.pay Guest User); optionally OASIS for Guests via Experience USC \u2192 My Profile \u2192 Guest Access\",\"steps\":[\"Log in to USCe.pay (Experience USC \u2192 Finances & Billing \u2192 Pay My Bill).\",\"Go to the My Account page and click \\\"Send a payer invitation\\\" under Payers; enter the guest's email address.\",\"The guest logs in with \\\"Log in to USCe.pay for Guests\\\" on the SFS Guest Users page; USCe.pay and Payment Plan are on the My Services page.\",\"Optional (also shares courses, grades and other records): in Experience USC choose My Profile \u2192 Guest Access tab \u2192 Create New Guest Access; create a Guest Login ID and Guest PIN (optionally the guest's email) and authorize release by clicking \\\"I Agree\\\".\",\"Give the OASIS guest your 10-digit USC ID, the Guest Login ID and the Guest PIN; they log in on the OASIS for Guests page (USCe.pay and Payment Plan are on the OASIS Financial Information menu).\"],\"req\":[\"Only students may grant parents and other third parties access; under FERPA USC will not disclose account details to family without the student's permission.\",\"USCe.pay Guest User = financial information only; OASIS guest = financial information plus courses, grades and other records.\",\"Students may create up to two OASIS guest accounts and can revoke access at any time in Experience USC.\",\"Parents and other third parties do not get Experience USC access.\",\"Make sure the guest's email is correct; eBill notifications are also sent to guest users.\"],\"deadlines\":[\"None stated; set up guests before the payment due date (Spring 2027 settlement deadline: January 8, 2027) so they can pay on time.\"],\"costs\":[\"none stated\"],\"fields\":[\"guest's name and email address\",\"type of access (USCe.pay payer only vs. OASIS for Guests)\",\"whether the guest should also see courses and grades\",\"Guest Login ID and PIN to create (OASIS)\"],\"sources\":[{\"url\":\"https://sfs.usc.edu/guest-users/\",\"title\":\"Guest Users \u2013 Student Financial Services\"},{\"url\":\"https://arr.usc.edu/oasis-for-guests/\",\"title\":\"OASIS for Guests - Office of Academic Records and Registrar\"},{\"url\":\"https://ask.usc.edu/s/article/000001358\",\"title\":\"How do I set up my parent as a Guest on OASIS?\"},{\"url\":\"https://arr.usc.edu/tuition-and-fees/\",\"title\":\"Tuition and Fees - Office of Academic Records and Registrar\"}]},{\"id\":\"set-up-direct-deposit-refunds\",\"topic\":\"03\",\"name\":\"Set up direct deposit (eRefund) for refunds\",\"desc\":\"Student wants credit-balance refunds (e.g., financial aid exceeding charges) deposited automatically to their bank account.\",\"system\":\"USCe.pay \u2192 My Account (direct deposit / eRefund)\",\"steps\":[\"Log in to USCe.pay through Experience USC (Finances & Billing \u2192 Pay My Bill).\",\"Under My Account, sign up for direct deposit (eRefund) and enter the bank account for refunds.\",\"Domestic students who receive stipends, fellowships or other ad hoc payments: also sign up for \\\"Stipends/Ad Hoc Payments for Domestic Students\\\" under My Account.\",\"Allow 3\u20135 business days for initial setup; once enrolled, credit-balance refunds are deposited automatically.\",\"Verify the funds are in your bank account before spending the refund.\"],\"req\":[\"Refunds from cash, check, web check or financial aid go to the student's bank account regardless of who paid.\",\"Parent PLUS loan refunds go to the person designated on the loan application (typically the parent borrower) in 5\u20137 business days.\",\"With an active payment plan, a plan budget change is required before a refund can be made.\",\"Wire-transfer overpayments are returned in full to the originating bank or left on the account; partial refunds are not allowed.\"],\"deadlines\":[\"First day for refunds from student accounts: Fall 2026 \u2014 August 19, 2026; Spring 2027 \u2014 January 6, 2027.\",\"Refunds are deposited within 2\u20133 business days; initial eRefund setup may take 3\u20135 business days.\"],\"costs\":[\"none stated\"],\"fields\":[\"account holder (student) name\",\"bank routing and account number\",\"account type (checking or savings)\",\"whether to also enroll for stipend/ad hoc payment direct deposit\",\"expected refund (credit balance amount and term)\"],\"sources\":[{\"url\":\"https://sfs.usc.edu/refunds/\",\"title\":\"Refunds \u2013 Student Financial Services\"},{\"url\":\"https://ask.usc.edu/s/article/000001376\",\"title\":\"How do I receive my refund once my financial aid has been disbursed?\"},{\"url\":\"https://sfs.usc.edu/deadlines/\",\"title\":\"Dates and Deadlines \u2013 Student Financial Services\"},{\"url\":\"https://sfs.usc.edu/epay/\",\"title\":\"Log In to USCe.pay \u2013 Student Financial Services\"}]},{\"id\":\"download-1098-t\",\"topic\":\"03\",\"name\":\"Download a 1098-T tax form\",\"desc\":\"Student (or family) needs the 1098-T for the prior calendar year (or a past year) to claim education tax credits.\",\"system\":\"Heartland ECSI website (USC school code 3K); SSN/ITIN updates in Experience USC \u2192 My Profile\",\"steps\":[\"Watch for ECSI's email; forms are prepared in January and available in ECSI by January 31.\",\"Go to ECSI and create an account (ECSI no longer offers single sign-on from USC).\",\"Use school code 3K when creating the account.\",\"Select the tax year and download/save the form; up to seven years of past forms are available.\",\"If no form appears because the SSN/ITIN is missing, add it in Experience USC (profile icon \u2192 My Profile \u2192 Personal Info \u2192 Edit \u2192 SSN/ITIN).\",\"If you believe the data is wrong, contact ECSI at 866-428-1098 or file a case online.\"],\"req\":[\"Issued to qualified U.S. citizens, permanent residents, and international students with a taxpayer identification number on their student record.\",\"Students who enroll agree to receive the 1098-T electronically.\",\"No form when there are no net qualified charges (e.g., scholarships, grants or third-party payments meet or exceed qualified charges).\",\"USC cannot provide tax advice.\"],\"deadlines\":[\"Forms available in ECSI by January 31 each year.\",\"International students: report SSN/ITIN by December 31 of the tax year; if added after January 1, the form is updated within 5 business days.\"],\"costs\":[\"none stated\"],\"fields\":[\"tax year needed\",\"whether an SSN/ITIN is on file\",\"whether the student already has an ECSI account\",\"official USC email for ECSI notifications\"],\"sources\":[{\"url\":\"https://sfs.usc.edu/tax/1098-t/\",\"title\":\"1098-T Tax Form \u2013 Student Financial Services\"},{\"url\":\"https://sfs.usc.edu/2026/03/31/accessing-your-1098t/\",\"title\":\"Accessing Your 1098T \u2013 Student Financial Services\"},{\"url\":\"https://sfs.usc.edu/tax/international/\",\"title\":\"International Students \u2013 Student Financial Services\"}]},{\"id\":\"view-statement-and-due-date\",\"topic\":\"03\",\"name\":\"View the current statement and due date\",\"desc\":\"Student wants to see what they owe, the minimum due and the due date, or get a printable record of charges.\",\"system\":\"USCe.pay (Experience USC \u2192 Finances & Billing \u2192 Pay My Bill); Registration and Fee Summary on the Student Resources page in Experience USC\",\"steps\":[\"Watch for the eBill notification sent to your official @usc.edu email (also sent to guest users); eBills are generated every four to five weeks.\",\"Log in to Experience USC and open Pay My Bill (USCe.pay) from the Finances & Billing menu.\",\"Check your account balance, confirm the due date, and open the billing statement (disable pop-up blockers if it won't display).\",\"Review the statement sections: previous minimum due, pending aid/deferments, due date, minimum due, finance charge section, agency billing and payment plan.\",\"For a printable summary of courses with tuition and fees, use the Registration and Fee Summary link on the Student Resources page in Experience USC (three terms back, two forward), or print an online statement from USCe.pay.\"],\"req\":[\"USC does not mail paper statements; non-receipt of a bill does not relieve you of the obligation to pay.\",\"eBills go only to your official @usc.edu account; add epayret@usc.edu to your address book.\",\"Payment plan details are a separate account under \\\"Payment Plans\\\" in USCe.pay.\"],\"deadlines\":[\"Statement 10/17/26 due 11/13/26 (current); statement 11/14/26 due 12/11/26; statement 12/12/26 due 1/8/27 (Spring 2027 tuition and fee deadline); statement 1/9/27 due 2/12/27; statement 2/13/27 due 3/19/27; statement 3/20/27 due 4/16/27; statement 4/17/27 due 5/14/27; statement 5/15/27 due 6/18/27.\"],\"costs\":[\"none stated\"],\"fields\":[\"term\",\"statement date\",\"due date\",\"minimum due vs. full balance\",\"pending aid or deferments shown\"],\"sources\":[{\"url\":\"https://sfs.usc.edu/student-account/your-bill/\",\"title\":\"Understand Your Bill \u2013 Student Financial Services\"},{\"url\":\"https://sfs.usc.edu/epay/\",\"title\":\"Log In to USCe.pay \u2013 Student Financial Services\"},{\"url\":\"https://sfs.usc.edu/deadlines/monthly-billing-schedule/\",\"title\":\"Monthly Billing Schedule \u2013 Student Financial Services\"},{\"url\":\"https://ask.usc.edu/s/article/000002552\",\"title\":\"How can I obtain a copy of my Registration and Fee Summary?\"}]},{\"id\":\"submit-sponsor-authorization\",\"topic\":\"03\",\"name\":\"Submit a sponsor/agency authorization for direct billing\",\"desc\":\"Sponsored student wants a company, government agency or invoicing 529 plan billed directly so the sponsored amount is deferred on their account.\",\"system\":\"USC Agency Billing (agbill@usc.edu; 1150 W. Jefferson Blvd., PSB 100, Los Angeles CA 90089-1052)\",\"steps\":[\"Check SFS's Approved Agencies list; if the sponsor is not listed, it must complete the Sponsoring Agency Application and be approved.\",\"Obtain from the sponsor a letter on organization letterhead, a formal voucher or a purchase order with: agency contact person, email, phone and address; your name as in USC records; your 10-digit USC ID; the charges the agency will pay; and the duration of sponsorship (optional PO number or internal student ID, max 15 characters).\",\"Email it to agbill@usc.edu (include your 10-digit USC ID) or mail it to USC Agency Billing before the settlement deadline.\",\"Agency Billing credits a deferment to your account and notifies you by email.\",\"Pay any amount not deferred by the deadline, and waive optional charges (health insurance, tuition refund insurance) the sponsor won't pay.\"],\"req\":[\"Authorizations are needed each term and must be received before that term's settlement deadline.\",\"International students who submitted a support letter for immigration must still send the authorization to Agency Billing.\",\"USC does not accept agency billing from owners of private businesses paying for themselves or their dependents.\",\"Employer reimbursement (paid after the term) is not eligible for agency billing.\",\"If the sponsor does not pay, the remaining deferment is cancelled and charged to the student; sponsor payments may reduce loans, work-study and university grant.\"],\"deadlines\":[\"Spring 2027: by the settlement deadline, January 8, 2027 (5 p.m. PT).\",\"USC invoices agencies after the last day to drop classes with a refund; agencies are expected to pay within 30 days of invoicing.\"],\"costs\":[\"none stated\"],\"fields\":[\"sponsor name and whether it is on the approved list\",\"term(s) covered\",\"charges the sponsor will pay (tuition only, tuition and mandatory fees, flat amount, housing, etc.)\",\"sponsor contact details\",\"student 10-digit USC ID\"],\"sources\":[{\"url\":\"https://sfs.usc.edu/agency/\",\"title\":\"Agency Billing \u2013 Student Financial Services\"},{\"url\":\"https://sfs.usc.edu/agency/authorizing-direct-invoicing/\",\"title\":\"Authorizing Direct Invoicing \u2013 Student Financial Services\"},{\"url\":\"https://sfs.usc.edu/agency/apply/\",\"title\":\"Applying to Be a Sponsoring Agency \u2013 Student Financial Services\"},{\"url\":\"https://sfs.usc.edu/agency/approved/\",\"title\":\"Approved Agencies \u2013 Student Financial Services\"}]},{\"id\":\"request-employer-reimbursement-deferment\",\"topic\":\"03\",\"name\":\"Request an employer reimbursement tuition deferment\",\"desc\":\"Student whose employer reimburses tuition after the term wants to defer up to 90% of tuition until the deferment expires.\",\"system\":\"Student Financial Services (Employer Reimbursement deferment application on the SFS site; uscsfs@usc.edu, 213-740-4077)\",\"steps\":[\"Confirm you are registered for the upcoming term and your student account is current.\",\"Complete the SFS deferment application and submit it together with your employer's reimbursement approval letter (both at the same time).\",\"SFS emails you a promissory note packet; sign it and send it to uscsfs@usc.edu.\",\"Before the settlement deadline, pay 10% of tuition, 100% of all fees and the $100 application fee.\",\"When the deferment expires, pay the deferred balance shown on the next billing statement.\"],\"req\":[\"Employer must reimburse tuition at the end of each term.\",\"A new deferment application and company letter are required each term.\",\"Loans or any other assistance reduce the amount eligible for deferment.\",\"You owe the deferred tuition regardless of grades or employment status; unpaid expired deferments become past due.\"],\"deadlines\":[\"Submit and pay the required portion before each term's settlement deadline (Spring 2027: January 8, 2027).\",\"Fall deferments expire in January, spring deferments in April, summer deferments in September.\"],\"costs\":[\"$100 application fee per term (SFS page), plus 10% of tuition and 100% of fees up front.\",\"The Registrar's Tuition and Fees page instead describes a non-refundable service charge of four percent of the deferment amount; confirm with SFS.\"],\"fields\":[\"term\",\"employer reimbursement letter on hand\",\"tuition amount and deferrable portion (up to 90%)\",\"up-front amount due (10% tuition + 100% fees + $100)\",\"deferment expiration month\"],\"sources\":[{\"url\":\"https://sfs.usc.edu/payment/employer-reimbursement/\",\"title\":\"Employer Reimbursement \u2013 Student Financial Services\"},{\"url\":\"https://arr.usc.edu/tuition-and-fees/\",\"title\":\"Tuition and Fees - Office of Academic Records and Registrar\"},{\"url\":\"https://sfs.usc.edu/contact/\",\"title\":\"Contact \u2013 Student Financial Services\"}]},{\"id\":\"change-or-cancel-payment-plan\",\"topic\":\"03\",\"name\":\"Change or cancel a payment plan / bring a plan current\",\"desc\":\"Student's charges changed (or they missed an installment) and they need to adjust, cancel or catch up on their payment plan.\",\"system\":\"SFS Payment Plan Change Request Form (online form on sfs.usc.edu); USCe.pay \u2192 payment plan option for past-due plans\",\"steps\":[\"To change the plan budget or cancel, submit the Payment Plan Change Request Form on the SFS website.\",\"If you are owed a refund and have an active plan, request the budget change so the refund can be issued.\",\"If the plan is past due (SFS 05 hold), log in to USCe.pay, select the payment plan option and bring the plan current.\",\"For help, contact Payment Plan and Prepayment at 213-740-4077 or uscsfs@usc.edu.\"],\"req\":[\"The payment plan is not adjusted automatically when your account changes.\",\"USC reserves the right to cancel the plan for failure to make payment when due.\",\"An active plan requires a budget change before any refund can be made.\"],\"deadlines\":[\"Installments are due by the 3rd of each month; no change-request deadline is stated.\"],\"costs\":[\"none stated for changes; the $75 application fee is non-refundable\"],\"fields\":[\"term of the plan\",\"change requested (new budget amount vs. cancellation)\",\"reason (added/dropped units, new aid, housing change, refund due)\",\"any missed installment amount\"],\"sources\":[{\"url\":\"https://sfs.usc.edu/payment/plan/\",\"title\":\"Payment Plans \u2013 Student Financial Services\"},{\"url\":\"https://sfs.usc.edu/refunds/\",\"title\":\"Refunds \u2013 Student Financial Services\"},{\"url\":\"https://sfs.usc.edu/student-account/holds/\",\"title\":\"Removing a Hold \u2013 Student Financial Services\"},{\"url\":\"https://sfs.usc.edu/contact/\",\"title\":\"Contact \u2013 Student Financial Services\"}]},{\"id\":\"request-late-fee-reversal-delayed-aid\",\"topic\":\"03\",\"name\":\"Request reversal of late fees caused by delayed financial aid\",\"desc\":\"Student was charged late settlement fees or finance charges because pending financial aid posted after the settlement deadline.\",\"system\":\"askUSC \\\"Email Us\\\" to the Financial Aid Office, topic \\\"Late Charges Waived\\\"\",\"steps\":[\"Confirm in FAST that the aid was pending for that semester and has now disbursed (or check USCe.pay for disbursement).\",\"Pay your account in full, minus the late fees and finance charges.\",\"Contact the Financial Aid Office through askUSC \\\"Email Us\\\" using the topic \\\"Late Charges Waived\\\" to request the reversal.\"],\"req\":[\"Late fees and charges are never reversed automatically.\",\"Only late settlement fees or finance charges from the semester the pending aid was intended for can be reversed.\",\"If the aid, loan or appeal is denied, the account must be settled within two weeks of the denial to remain eligible for a reversal.\",\"This is not a waiver of the student's financial obligation.\"],\"deadlines\":[\"Settle within two weeks of any aid denial; no other deadline stated.\"],\"costs\":[\"none stated\"],\"fields\":[\"semester affected\",\"late fee and finance charge amounts\",\"which aid was pending and when it disbursed\",\"confirmation the remaining balance is paid in full\"],\"sources\":[{\"url\":\"https://ask.usc.edu/s/article/000001436\",\"title\":\"What happens if I have late/finance charges or my financial aid isn't disbursed to my account before my bill is due?\"}]},{\"id\":\"opt-out-digital-course-materials\",\"topic\":\"03\",\"name\":\"Opt out of the Digital Course Materials Program\",\"desc\":\"Undergraduate wants to remove the $310 Digital Course Materials charge for a term and buy required materials independently.\",\"system\":\"Follett opt-out portal (link in USC Bookstore emails / Bookstore opt-out instructions); USC Bookstore for physical materials\",\"steps\":[\"Open the opt-out link from the program email sent to your @usc.edu account (it goes to the Follett opt-out website).\",\"Choose \\\"opt-out\\\" for the term and follow the portal instructions.\",\"If you received physical course materials, also contact the USC Bookstore (213-740-8398, 10 a.m.\u20136 p.m., or uscdcmp@follett.com) by 11:59 p.m. PT on the last day to drop classes to finalize the opt-out.\"],\"req\":[\"Applies to students with undergraduate status (including progressive-degree students in graduate courses); study abroad courses are not included.\",\"Opt-out must be done each term; there is no penalty, and opting out before the deadline gives a full refund.\",\"After opting out, you are responsible for obtaining required materials yourself.\"],\"deadlines\":[\"Before the term's opt-out deadline; students with physical materials must contact the Bookstore by 11:59 p.m. PT on the last day to drop classes (the FAQ's example: September 12 for Fall 2025).\"],\"costs\":[\"$310 per semester (fall and spring) if you stay enrolled; full refund if you opt out before the deadline.\"],\"fields\":[\"term\",\"whether any physical materials were received\",\"acknowledgment that required materials must then be purchased independently\"],\"sources\":[{\"url\":\"https://www.uscbookstore.com/student-faq\",\"title\":\"Digital Course Material FAQ (Student) - USC Bookstore\"},{\"url\":\"https://arr.usc.edu/tuition-and-fees/\",\"title\":\"Tuition and Fees - Office of Academic Records and Registrar\"}]},{\"id\":\"pay-by-international-wire\",\"topic\":\"03\",\"name\":\"Pay from abroad by international wire (Flywire or Convera)\",\"desc\":\"International student or family wants to send tuition from a foreign bank, card or e-wallet, often in local currency.\",\"system\":\"Flywire (launched from USCe.pay \u2192 Make Payment) or Convera (USC-customized Convera site)\",\"steps\":[\"Flywire: in USCe.pay select \\\"Make Payment\\\", then \\\"Tuition and Fees\\\", verify the amount and click \\\"Checkout\\\"; you are directed to Flywire.\",\"Follow Flywire's instructions and complete the payment to Flywire within two business days.\",\"Convera (alternative): go to Convera's site customized for USC students and complete the payment within two business days.\",\"Allow 2\u20135 business days after your bank initiates the transfer; the payment is credited once USC's bank receives the funds.\"],\"req\":[\"CIBC International Student Pay is no longer available as of October 30, 2026.\",\"Only wire funds for USC tuition and university fees, not for non-university expenses such as a private landlord.\",\"Overpayments by wire are either returned in full to the originating bank or left on account for future charges; partial refunds are not allowed.\"],\"deadlines\":[\"Send early enough to reach USC before the settlement deadline (Spring 2027: January 8, 2027, 5 p.m. PT).\"],\"costs\":[\"USC does not charge for Flywire or Convera; the local bank may charge fees.\"],\"fields\":[\"payer country and currency\",\"amount in USD to be credited\",\"provider (Flywire vs. Convera)\",\"student name and 10-digit USC ID\",\"timing vs. due date\"],\"sources\":[{\"url\":\"https://sfs.usc.edu/payment/wire-transfers/\",\"title\":\"Wire Transfer \u2013 Student Financial Services\"},{\"url\":\"https://sfs.usc.edu/2026/10/08/cibc-wire-payment-option-ending-october-31/\",\"title\":\"CIBC Wire Payment Option Ending Oct 30 \u2013 Student Financial Services\"}]},{\"id\":\"waive-student-health-insurance\",\"topic\":\"03\",\"name\":\"Waive the USC Student Health Insurance Plan (SHIP) charge\",\"desc\":\"Student with comparable insurance wants the automatic SHIP/Aetna charge removed from their bill.\",\"system\":\"MySHR Patient Portal (usc.edu/myshr) waiver request, per USC Student Health\",\"steps\":[\"Confirm your plan meets USC's minimum requirements, including regional coverage in Southern California.\",\"Submit the waiver request on the MySHR Patient Portal by the deadline.\",\"Wait for approval confirming that your coverage meets the university's requirements.\",\"Repeat every year by the fall deadline (spring starters waive by the spring deadline their first year, then each fall).\"],\"req\":[\"Auto-enrolled: domestic students in 6+ units; health-profession, PhD and international students regardless of units.\",\"Qualifying coverage examples: employer-based plan through a parent/guardian/spouse/partner, Medi-Cal, or federal veterans' health benefits.\",\"Waivers must be submitted annually; without one, you stay enrolled in SHIP.\",\"The Student Health Fee is separate and cannot be waived.\"],\"deadlines\":[\"Annual waiver, due by the third week of fall classes: Fall 2026 \u2014 September 11, 2026; Fall 2027 \u2014 September 10, 2027.\",\"Students starting in spring: by the spring deadline in their first year (Spring 2027 \u2014 January 29, 2027), then annually each fall.\",\"Student athletes: before the first day of practice and no later than August 15.\"],\"costs\":[\"No fee to waive is stated.\",\"SHIP charge if not waived (USC Price fee table): $1,313 fall and $2,474 spring on-campus rate; online-program rate $2,464 fall and $4,776 spring.\"],\"fields\":[\"term\",\"insurance carrier and plan type\",\"confirmation of Southern California coverage\",\"policyholder (student, parent, spouse)\"],\"sources\":[{\"url\":\"https://sites.usc.edu/ship/\",\"title\":\"Student Health Insurance Plan (SHIP)\"},{\"url\":\"https://studenthealth.usc.edu/fees-deadlines\",\"title\":\"Fees and Deadlines List \u2013 USC Student Health\"},{\"url\":\"https://sites.usc.edu/new-student-health-requirements/costs/health-insurance-requirement/\",\"title\":\"Health Insurance Requirement \u2013 Health Requirements for Students\"},{\"url\":\"https://sfs.usc.edu/student-account/common-fees/\",\"title\":\"Common Fees and Transactions \u2013 Student Financial Services\"}]},{\"id\":\"accept-or-decline-aid-in-fast\",\"topic\":\"04\",\"name\":\"Accept or decline aid (loans) in FAST\",\"desc\":\"Student wants to accept, reduce or decline the loans in their financial aid summary, or wants to know how grants, work-study and a USC Merit Scholarship are accepted.\",\"system\":\"FAST (Financial Aid Summary and Tasks) portal: Direct Loan Request form in the Document Library; studentaid.gov for the MPN and PLUS applications; iGrad (usc.igrad.com) for entrance counseling\",\"steps\":[\"Log in to FAST (myUSC for continuing students, Applicant Portal for new undergraduates, youSC for new graduate students) and review the Financial Aid Summary.\",\"Grants and scholarships: USC pages describe no acceptance step. They are credited automatically to the USC billing account no later than the Wednesday before each semester; to receive them, the student must be registered for classes and meet all disbursement requirements.\",\"To accept Federal Direct Subsidized/Unsubsidized Loans: in the Document Library complete the Direct Loan Request form (undergraduates only after receiving their financial aid summary). To decline, enter $0 on the form.\",\"Sign the Master Promissory Note (MPN) at studentaid.gov with the FSA ID (not required if an existing Direct Loan MPN from another school is no more than 10 years old).\",\"First-time USC borrowers complete entrance loan counseling at iGrad (log in with USC NetID, select \\\"Start Course\\\"; about 30 minutes; transmitted to USC in 2-3 business days). First-time undergraduate borrowers also complete the iGrad Cash Course.\",\"Parent PLUS: the parent applies at studentaid.gov and signs a PLUS MPN if approved. Private loans: apply with the chosen lender.\",\"Federal Work-Study: no acceptance form is described; the student must find a work-study job to receive the funds.\",\"New first-year USC Merit Scholarship: applied automatically if the enrollment commitment deposit is received by May 1.\",\"To change the decision later: submit \\\"Appeal to Change or Cancel a Federal Direct Loan\\\" (or the PLUS/private loan version) in the Document Library.\"],\"req\":[\"Direct Loans: enrolled at least half-time, in the number of units indicated in the financial aid summary, and maintaining Satisfactory Academic Progress.\",\"Undergraduates must wait to receive their financial aid summary before submitting the Direct Loan Request form.\",\"Units on the Financial Aid Supplement must match actual enrollment for aid to disburse.\",\"Parent PLUS is credit-based and only for parents of dependent undergraduates enrolled at least half-time (6 units).\"],\"deadlines\":[\"Complete loan steps no later than 30 days before the start of the first semester.\",\"Cancel or decrease a loan within 120 days of disbursement or by the end of the semester, whichever comes first.\",\"Request loan increases before the end of the semester (at least two weeks before is strongly encouraged).\",\"USC encourages applying for Direct PLUS Loans no sooner than 45 days before the start of a semester.\",\"USC Merit Scholarship (new first-years): enrollment commitment deposit received by May 1.\"],\"costs\":[\"Direct Loan origination fee: 1.057 percent deducted from each disbursement (loans made on or after October 1, 2020, and before October 1, 2027).\",\"Fixed interest for loans first disbursed July 1, 2026 - June 30, 2027: 6.52% undergraduate Direct Loans; 8.07% graduate unsubsidized; 9.07% Parent PLUS and Grad PLUS.\",\"No cost stated for accepting grants or scholarships.\"],\"fields\":[\"aid year and term(s)\",\"which award (Direct Subsidized, Direct Unsubsidized, Parent PLUS, private loan)\",\"amount to accept per semester, or $0 to decline\",\"whether the student is a first-time borrower (MPN and entrance counseling still needed)\",\"planned enrollment units (must match the Financial Aid Supplement)\",\"effect on remaining balance or refund\"],\"sources\":[{\"url\":\"https://financialaid.usc.edu/next-steps/\",\"title\":\"Next Steps - Financial Aid\"},{\"url\":\"https://ask.usc.edu/s/article/000001364\",\"title\":\"askUSC: I don't want to accept the Federal Direct Loans in my award. What should I do?\"},{\"url\":\"https://financialaid.usc.edu/loans/\",\"title\":\"Loans - Financial Aid\"},{\"url\":\"https://admission.usc.edu/scholarship-guide/\",\"title\":\"Scholarship Guide (2026-2027) - Undergraduate Admission\"}]},{\"id\":\"submit-requested-financial-aid-document\",\"topic\":\"04\",\"name\":\"Submit a requested financial aid document\",\"desc\":\"Student has a document request (tax return, verification form, statement, etc.) on their FAST portal and wants to submit it.\",\"system\":\"FAST portal: \\\"Required Info and Forms\\\" page and \\\"Document Library\\\" (uploads and online forms); ISEP identity form only in person at John Hubbard Hall or by mail\",\"steps\":[\"Watch for the email saying additional documents are needed.\",\"Log in to FAST (myUSC, Applicant Portal or youSC) and open Required Info and Forms to see each request and its instructions.\",\"Online forms: complete them in FAST. To have a parent complete a form, use \\\"Guest Invite\\\" at the top of the form and give the parent the Parent PIN (the parent also needs the student's 10-digit USC ID and date of birth).\",\"Uploads: choose the matching document type in the Document Library (or \\\"Unknown or Unlisted\\\" type of Financial Aid Document), make sure the USC ID appears on each document, and upload.\",\"Tax documents: upload final, signed returns or IRS transcripts sent to you (not to USC). If the file is too large, upload only Form 1040, Schedules 1-3 and A-F, W-2s and related statements (no state returns).\",\"Identity verification (ISEP): cannot be uploaded or faxed; complete it in person at John Hubbard Hall with a government-issued photo ID, or mail the notarized original with a copy of the ID.\",\"Look for the email confirmation, then check the \\\"Received Documents\\\" tab once the document is verified.\"],\"req\":[\"The student is responsible for the integrity of submitted information; falsified documents or signatures can restrict aid and lead to Student Conduct Code sanctions.\",\"Documents become the property of USC and cannot be returned or duplicated.\",\"Paper submissions are accepted but delay processing.\"],\"deadlines\":[\"Within 10 business days of the Financial Aid Office's request.\",\"Verification of submitted documents may take up to 5 business days (sometimes longer).\"],\"costs\":[\"none stated\"],\"fields\":[\"which requested item (name as shown in FAST)\",\"aid year\",\"document type to select\",\"who must complete or sign it (student or parent)\",\"USC ID shown on each document\",\"file size/format\"],\"sources\":[{\"url\":\"https://financialaid.usc.edu/undergraduate-financial-aid/applying-for-financial-aid/\",\"title\":\"Applying for Financial Aid - Financial Aid\"},{\"url\":\"https://ask.usc.edu/s/article/000001400\",\"title\":\"askUSC: How will I be notified if I need to submit additional supporting documents?\"},{\"url\":\"https://ask.usc.edu/s/article/000001471\",\"title\":\"askUSC: How will I know if the Financial Aid Office has received the documents I sent?\"},{\"url\":\"https://financialaid.usc.edu/help-contact/\",\"title\":\"Help & Contact - Financial Aid\"}]},{\"id\":\"apply-csi-emergency-loan\",\"topic\":\"04\",\"name\":\"Apply for a CSI Emergency Loan\",\"desc\":\"Student facing an unforeseen financial emergency wants short-term emergency money.\",\"system\":\"Campus Support & Intervention (CSI) Emergency Loan Application (online form on campussupport.usc.edu); approved funds disbursed through Financial Aid; repaid through Student Financial Services\",\"steps\":[\"Consult the Financial Aid Office and your academic unit first (CSI highly encourages this).\",\"Check whether the application is open: it is currently closed for Fall 2026; contact CSI ((213) 740-0411, uscsupport@usc.edu) about other resources.\",\"When open, complete the online Emergency Loan Application: name, student ID, whether you have an SSN, address, cell phone, enrollment and employment status, whether you receive financial aid, efforts to get help elsewhere, how you will repay within 90 days, a description of the situation and expenses, supporting documentation (max 15 MB per file), and the amount requested (up to $1,000).\",\"CSI contacts you within one to two business days; on approval a staff member collects your SSN by phone.\",\"Allow five to ten business days for processing; approved funds are disbursed through Financial Aid.\",\"Repay through Student Financial Services within 90 days.\"],\"req\":[\"Currently enrolled.\",\"Good financial standing with USC (no negative balance in collections).\",\"U.S.-issued Social Security Number.\",\"Documentation verifying the emergency and the financial capacity to repay.\",\"One loan per semester; CSI may decline any application regardless of eligibility.\"],\"deadlines\":[\"Application currently closed for Fall 2026 (no reopening date stated).\",\"Repayment due within 90 days.\"],\"costs\":[\"Loan of up to $1,000.\",\"If not repaid within 90 days: 10% annual interest, the account is sent to collections, a registration hold is placed, and the student becomes ineligible for future emergency loans.\"],\"fields\":[\"amount requested (maximum $1,000)\",\"nature of the emergency and supporting documentation\",\"plan to repay within 90 days\",\"whether the student has a U.S.-issued SSN\",\"current enrollment status\",\"other resources already tried (Financial Aid appeal, academic unit)\"],\"sources\":[{\"url\":\"https://campussupport.usc.edu/students/emergency-loan-application/\",\"title\":\"Emergency Loan Application - Campus Support & Intervention\"},{\"url\":\"https://campussupport.usc.edu/students/basic-needs-2/\",\"title\":\"Basic Needs - Campus Support & Intervention\"}]},{\"id\":\"apply-basic-needs-supplemental-funding\",\"topic\":\"04\",\"name\":\"Apply for Student Basic Needs Supplemental Funding\",\"desc\":\"Student with a sudden, unforeseen hardship (rent, food, medical/dental, childcare) wants one-time grant-style funding.\",\"system\":\"Student Basic Needs Supplemental Funding Award application in USC Scholarship Universe (requires Financial Aid Office approval, which Student Basic Needs requests on the student's behalf)\",\"steps\":[\"If unsure whether you qualify, submit the Student Basic Needs contact form.\",\"Connect with USC Financial Aid; Student Basic Needs contacts the Financial Aid Office on your behalf for the required approval.\",\"When the application opens (around the sixth week of the fall or spring semester), apply in USC Scholarship Universe using the USC Undergraduate Applicant or USC Graduate Applicant login option.\",\"Provide any requested bills, receipts or other documents.\",\"Wait for the review (typically up to four weeks after the two-week application window closes); you will be notified of the decision.\"],\"req\":[\"Enrolled at least half-time in the term funds are requested.\",\"Sudden financial distress due to unforeseen circumstances, with other resources exhausted.\",\"$0 bill balance with the university.\",\"Approval from Financial Aid.\",\"Allowed uses: housing/rent, food, unforeseen medical/dental, childcare. Not allowed: transportation, vehicle costs, books/supplies/technology, tuition and fees.\"],\"deadlines\":[\"Opens around the sixth week of each fall and spring semester and stays open for a two-week window.\",\"Review and processing typically takes up to four weeks.\"],\"costs\":[\"none stated (one-time funding award)\"],\"fields\":[\"term\",\"expense type and amount needed\",\"current USC bill balance ($0 required)\",\"enrollment units (at least half-time)\",\"documents available (bills, receipts)\",\"whether Financial Aid has been contacted\"],\"sources\":[{\"url\":\"https://studentbasicneeds.usc.edu/programs-and-services/economic-support/\",\"title\":\"Economic Support - Student Basic Needs\"}]},{\"id\":\"request-special-circumstances-review\",\"topic\":\"04\",\"name\":\"Request a special circumstances review (financial aid appeal)\",\"desc\":\"Student or family had a change in income or expenses (job loss, death, divorce, medical costs, disaster) and wants their aid re-evaluated.\",\"system\":\"FAST Document Library: \\\"Special Circumstances and Expected Contribution Appeals\\\" form plus uploaded supporting documents\",\"steps\":[\"Gather documentation for the type of change (e.g., parent job loss: termination/reduction letter, parent Income and Expense form, last pay stub, documentation of severance/unemployment benefits, most recent federal tax return).\",\"Log in to FAST and open the Document Library.\",\"Select and complete \\\"Special Circumstances and Expected Contribution Appeals.\\\"\",\"Upload supporting documents, making sure the USC ID appears on each one.\",\"Respond to any request for more documentation; the Financial Aid Office notifies you of its decision.\"],\"req\":[\"New students may appeal once their initial financial aid summary is available.\",\"The appeal should present new information not in the original application; USC does not compare offers from other universities.\",\"Prospective undergraduates: each appeal is reviewed once and decisions are final.\",\"Re-evaluation depends on availability of funds and the timeliness of the original application and the appeal; consumer debt and car payments are not considered.\",\"Graduate students: re-evaluations will not result in eligibility for grants or increased loan amounts.\"],\"deadlines\":[\"No specific deadline stated for income appeals; timeliness affects funding.\",\"Cost of attendance (budget) increase appeals: at least 30 days before the end of the term.\"],\"costs\":[\"none stated\"],\"fields\":[\"type of change (income loss, death, divorce/separation, medical, natural disaster, other)\",\"aid year\",\"whose income or expenses changed (parent or student)\",\"amounts and dates\",\"documents available\",\"new vs. continuing student\"],\"sources\":[{\"url\":\"https://ask.usc.edu/s/article/000002594\",\"title\":\"askUSC: Can I appeal for more financial aid after I receive my financial aid summary?\"},{\"url\":\"https://financialaid.usc.edu/undergraduate-financial-aid/admitted-and-continuing-students/special-circumstances-and-appeals-undergaduate-continuing/\",\"title\":\"Special Circumstances and Appeals (Continuing Undergraduates) - Financial Aid\"},{\"url\":\"https://financialaid.usc.edu/undergraduate-financial-aid/prospective-students/special-circumstances-and-appeals-undergraduate-prospective/\",\"title\":\"Special Circumstances and Appeals (Prospective Undergraduates) - Financial Aid\"},{\"url\":\"https://financialaid.usc.edu/financial-aid-summary-continuing/\",\"title\":\"Financial Aid Summary (Continuing) - Financial Aid\"}]},{\"id\":\"check-financial-aid-status\",\"topic\":\"04\",\"name\":\"Check financial aid status\",\"desc\":\"Student wants to know whether their aid is complete, what is missing, or why aid has not disbursed.\",\"system\":\"FAST (Financial Aid Summary and Tasks) portal; studentaid.gov for FAFSA processing status; USCe.pay for charges and disbursements\",\"steps\":[\"Log in to FAST via myUSC (continuing students), the Applicant Portal (new undergraduates) or youSC (new graduate students).\",\"Review the Financial Aid Summary tab for award amounts and the Aid Status tab for any items flagged with a red triangle.\",\"Open Required Info and Forms for outstanding requests and the \\\"Received Documents\\\" tab for verified submissions.\",\"If FAFSA data seems missing, check its status at studentaid.gov (account dashboard > My Activity).\",\"Check actual charges, balance and posted aid in USCe.pay.\"],\"req\":[\"Access to FAST through myUSC (continuing students), the Applicant Portal (new undergraduates) or youSC (new graduate students).\",\"FAFSA and CSS Profile received and matched to the USC record (Social Security number on file).\"],\"deadlines\":[\"Document verification can take up to 5 business days.\",\"For 2027-28, the Financial Aid Office does not start processing applications until November, so information may not appear in FAST until early November (an older askUSC article says CSS Profiles may not appear until late November).\"],\"costs\":[\"none stated\"],\"fields\":[\"aid year\",\"what the student wants to check (award status, missing documents, FAFSA status, bill balance)\",\"specific award or document in question\"],\"sources\":[{\"url\":\"https://ask.usc.edu/s/article/000002198\",\"title\":\"askUSC: How do I check the status of my financial aid?\"},{\"url\":\"https://financialaid.usc.edu/fast/\",\"title\":\"FAST - Financial Aid\"},{\"url\":\"https://ask.usc.edu/s/article/000001488\",\"title\":\"askUSC: Why haven't my loans disbursed to my account?\"},{\"url\":\"https://ask.usc.edu/s/article/000001487\",\"title\":\"askUSC: Why does my bill indicate a balance due when FAST says I have no estimated remaining cost?\"}]},{\"id\":\"find-and-apply-work-study-job\",\"topic\":\"04\",\"name\":\"Find and apply for a work-study (on-campus) job\",\"desc\":\"Student with a Federal Work-Study award (or looking for any campus job) wants to find and apply for a position.\",\"system\":\"Handshake (USC Career Center): Jobs > All filters > \\\"On Campus Student Employment\\\"; Virtual On-Campus Student Job Fair on Handshake\",\"steps\":[\"Confirm Federal Work-Study appears in your financial aid summary in FAST (if not, see the request work-study action).\",\"Register for Handshake (available two days after you register for classes) and log in.\",\"Go to Jobs > All filters and check \\\"On Campus Student Employment\\\" under Job Type.\",\"Apply following each posting's directions; along with a resume, the Career Center recommends attaching a cover letter and a schedule of your work availability.\",\"Attend the Virtual On-Campus Student Job Fair: Spring 2027 is Friday, January 8, 2027, 1:00-4:00 pm PT on Handshake (registration opens November 2, 2026; RSVP in Handshake Events).\",\"Check departments that hire outside Handshake (e.g., DPS applications at the DPS Front Desk, 3667 McClintock Ave).\",\"When hired, present your Social Security card and driver's license or passport.\",\"Work no more than 20 hours per week while USC is in session (40 during vacations with employer permission); stop when earnings reach your award unless re-hired as non-work-study.\"],\"req\":[\"Federal Work-Study award: financial need, all deadlines met, U.S. citizen or eligible noncitizen, enrolled in the units the aid was based on.\",\"International students are not eligible for work-study positions.\",\"Job placement is not guaranteed.\"],\"deadlines\":[\"Spring 2027 job fair: Friday, January 8, 2027 (registration opens November 2, 2026).\",\"Most fall openings are posted by the first or second week of August; departments post year-round.\"],\"costs\":[\"none stated\"],\"fields\":[\"work-study award amount and term\",\"hours available per week\",\"type of job or department of interest\",\"hiring documents on hand (Social Security card, ID)\"],\"sources\":[{\"url\":\"https://careers.usc.edu/on-campus-jobs/\",\"title\":\"On-Campus Jobs - Career Center\"},{\"url\":\"https://careers.usc.edu/resources/find-on-campus-student-jobs/\",\"title\":\"Find On-Campus Student Jobs - Career Center\"},{\"url\":\"https://careers.usc.edu/on-campus-student-job-fair/\",\"title\":\"Virtual On-Campus Student Job Fair - Career Center\"},{\"url\":\"https://financialaid.usc.edu/next-steps/\",\"title\":\"Next Steps - Financial Aid\"}]},{\"id\":\"request-add-or-increase-work-study\",\"topic\":\"04\",\"name\":\"Request (add or increase) Federal Work-Study\",\"desc\":\"Student without work-study, or who has used up their award, wants work-study added or increased (or wants to convert unused work-study to loans).\",\"system\":\"FAST: \\\"Appeal to Add Federal Work-Study\\\" upload (letter plus employer letter); conversion requests also submitted through FAST\",\"steps\":[\"Write a letter requesting Federal Work-Study (or an increase).\",\"Get an employer letter on departmental letterhead with the employer's name and contact information, your hourly rate, hours per week, and the additional amount requested (graduate students: a signed, dated letter showing intent to hire, start/end dates, role and pay).\",\"Upload both in FAST under \\\"Appeal to Add Federal Work-Study.\\\"\",\"If USC cannot increase the award, ask your employer about continuing as a non-work-study employee.\",\"To convert unused work-study to loan eligibility instead, submit a request in FAST explaining why and the amount to convert.\"],\"req\":[\"Undergraduates: work-study is awarded by class level and eligibility; students without it in their initial summary may be denied even with an appeal.\",\"Increases depend on available funds.\"],\"deadlines\":[\"not stated on USC sites\"],\"costs\":[\"none stated\"],\"fields\":[\"add vs. increase vs. convert to loans\",\"amount requested\",\"hourly rate and hours per week\",\"employer name and contact\",\"term(s)\"],\"sources\":[{\"url\":\"https://ask.usc.edu/s/article/000002458\",\"title\":\"askUSC: How do I request Federal Work-Study?\"},{\"url\":\"https://ask.usc.edu/s/article/000002958\",\"title\":\"askUSC: Can I keep my work-study job after I've exhausted my Federal Work-Study award?\"},{\"url\":\"https://financialaid.usc.edu/undergraduate-financial-aid/admitted-and-continuing-students/special-circumstances-and-appeals-undergaduate-continuing/\",\"title\":\"Special Circumstances and Appeals (Continuing Undergraduates) - Financial Aid\"},{\"url\":\"https://financialaid.usc.edu/next-steps/\",\"title\":\"Next Steps - Financial Aid\"}]},{\"id\":\"report-outside-scholarship\",\"topic\":\"04\",\"name\":\"Report an outside scholarship and send the check\",\"desc\":\"Student received a scholarship from an outside organization and needs it added to their aid and paid to their account.\",\"system\":\"FAST Document Library: \\\"Outside Agency Scholarship Notification\\\"; checks to USC Financial Aid Office, Attention: Aid Coordination (JHH 325)\",\"steps\":[\"Upload the scholarship notification letter in FAST > Document Library > \\\"Outside Agency Scholarship Notification.\\\"\",\"Have the check made payable to \\\"University of Southern California\\\" with the student's name and USC ID on the memo line; endorse it first if it is payable to both you and USC.\",\"Drop the check in the box outside JHH 325 or mail it to: USC Financial Aid Office, Attention: Aid Coordination, 700 Childs Way, JHH 325, Los Angeles, CA 90089-0914.\",\"If the award was applied to the wrong term, upload a letter from the agency confirming the term(s) and academic year (same document type).\",\"Watch for the notice of your revised financial aid summary.\"],\"req\":[\"Federal regulations require USC to consider all resources; outside scholarships typically reduce loans or work-study first.\",\"Funds are not disbursed until the check is received.\"],\"deadlines\":[\"Allow three weeks from the mailing date for mailed checks; about one week for checks dropped off in person.\"],\"costs\":[\"none stated\"],\"fields\":[\"scholarship name and amount\",\"term(s)/academic year it applies to\",\"how the check is made payable\",\"whether the notification letter is available to upload\"],\"sources\":[{\"url\":\"https://ask.usc.edu/s/article/000001120\",\"title\":\"askUSC: What do I need to do after receiving an outside scholarship?\"},{\"url\":\"https://financialaid.usc.edu/undergraduate-financial-aid/admitted-and-continuing-students/scholarships/\",\"title\":\"Scholarships - Financial Aid\"},{\"url\":\"https://ask.usc.edu/s/article/000002711\",\"title\":\"askUSC: What should I do if my outside scholarship was applied to my summary incorrectly?\"},{\"url\":\"https://financialaid.usc.edu/help-contact/\",\"title\":\"Help & Contact - Financial Aid\"}]},{\"id\":\"change-or-cancel-loan\",\"topic\":\"04\",\"name\":\"Reduce, cancel or increase a loan\",\"desc\":\"Student wants to borrow less (or return a loan) or borrow more than originally requested.\",\"system\":\"FAST Document Library: \\\"Appeal to Change or Cancel a Federal Direct Loan\\\" or \\\"Appeal to Change or Cancel a Federal PLUS or Private Loan Application or Disbursement\\\"\",\"steps\":[\"Check the loan's disbursement date in FAST.\",\"Log in to FAST and open the Document Library.\",\"Submit \\\"Appeal to Change or Cancel a Federal Direct Loan\\\" (Subsidized/Unsubsidized) or, for PLUS or private loans, \\\"Appeal to Change or Cancel a Federal PLUS or Private Loan Application or Disbursement.\\\"\",\"If canceling after receiving a refund, be prepared to pay any resulting balance on the student account.\"],\"req\":[\"Increases only if the package does not already include the maximum annual Direct Loan amounts; not granted after dropping below half-time, withdrawing or graduating.\",\"Returned funds are charged no interest or fees.\"],\"deadlines\":[\"Cancel/decrease: within 120 days of disbursement or by the end of the semester, whichever comes first.\",\"Increase: before the end of the semester (at least two weeks before is strongly encouraged).\"],\"costs\":[\"No interest or fees on returned loan funds; returning a loan may create a balance on the USC student account if a refund was already issued.\"],\"fields\":[\"loan type\",\"current amount and new amount per semester\",\"term(s)\",\"disbursement date\",\"whether a refund was already received\"],\"sources\":[{\"url\":\"https://ask.usc.edu/s/article/000001493\",\"title\":\"askUSC: How do I change or cancel my loans?\"},{\"url\":\"https://financialaid.usc.edu/undergraduate-financial-aid/admitted-and-continuing-students/special-circumstances-and-appeals-undergaduate-continuing/\",\"title\":\"Special Circumstances and Appeals (Continuing Undergraduates) - Financial Aid\"}]},{\"id\":\"submit-sap-appeal\",\"topic\":\"04\",\"name\":\"Submit a Satisfactory Academic Progress (SAP) appeal\",\"desc\":\"Student lost aid eligibility for not meeting SAP (GPA, pace, or maximum time frame) and wants it reinstated.\",\"system\":\"FAST: Satisfactory Academic Progress (SAP) Appeal form (Document Library) plus uploaded letter and documentation\",\"steps\":[\"Meet with your academic advisor to complete the SAP Appeal form, including the Academic Plan (page 2), which the advisor signs.\",\"Write a typed letter (no more than two pages) explaining what caused the deficiency, how it has been resolved, and how you will succeed (or, for maximum time frame, why you need more time).\",\"Gather third-party documentation supporting your circumstances.\",\"Upload the form, letter and documentation in FAST.\",\"Wait for the decision; if approved, meet the enrollment and GPA goals set for each semester.\"],\"req\":[\"Undergraduates first get a one-time, one-semester SAP Warning Period (no appeal needed during it).\",\"Graduate appeals are not considered until academic disqualification or activity restrictions are resolved.\",\"If denied, private loans and/or the USC Payment Plan may be options.\"],\"deadlines\":[\"Before the end of the semester for which aid is sought; aid cannot be reinstated retroactively for a past semester.\"],\"costs\":[\"none stated\"],\"fields\":[\"which SAP criterion was missed (GPA, pace of progression, maximum time frame)\",\"term aid is needed for\",\"academic advisor who will sign\",\"documentation available\"],\"sources\":[{\"url\":\"https://ask.usc.edu/s/article/000002226\",\"title\":\"askUSC: How do I submit a Satisfactory Academic Progress (SAP) Appeal?\"},{\"url\":\"https://financialaid.usc.edu/undergraduate-financial-aid/admitted-and-continuing-students/maintaining-your-eligibility/\",\"title\":\"Maintaining Your Eligibility (Undergraduate) - Financial Aid\"},{\"url\":\"https://financialaid.usc.edu/graduate-professional-financial-aid/admitted-and-continuing-students/maintaining-your-eligibility/\",\"title\":\"Maintaining Your Eligibility (Graduate & Professional) - Financial Aid\"},{\"url\":\"https://ask.usc.edu/s/article/000002193\",\"title\":\"askUSC: What is a Satisfactory Academic Progress Warning Period for financial aid?\"}]},{\"id\":\"update-enrollment-or-housing-financial-aid-supplement\",\"topic\":\"04\",\"name\":\"Update enrollment units or housing plans (Financial Aid Supplement)\",\"desc\":\"Student is changing their number of units, going on leave, studying abroad, or changing where they live and needs their aid adjusted.\",\"system\":\"FAST Document Library: \\\"Financial Aid Supplement\\\"\",\"steps\":[\"Log in to FAST.\",\"Select the academic year, then the Document Library.\",\"Select \\\"Financial Aid Supplement,\\\" enter your actual units per semester and/or housing status, and submit.\",\"If moving out of a parent's or relative's home, also upload a copy of the lease and a cancelled rent check.\",\"Watch your USC email for confirmation that the award was updated; for housing changes FAST notifies you within three business days if more documentation is needed.\"],\"req\":[\"Units entered must match actual enrollment for aid to disburse.\",\"Living with parents or relatives reduces eligibility; moving out may increase it.\",\"Reduced enrollment reduces University Grant, work-study and loans, in that order.\"],\"deadlines\":[\"Processing can take up to 1-2 weeks.\"],\"costs\":[\"none stated\"],\"fields\":[\"academic year and term(s)\",\"units per term\",\"housing status (with parents/relatives, on campus, off campus)\",\"lease/rent documents if moving out\",\"reason for change (reduced load, leave, study abroad)\"],\"sources\":[{\"url\":\"https://ask.usc.edu/s/article/000001137\",\"title\":\"askUSC: How do I update my enrollment plans with the Financial Aid Office?\"},{\"url\":\"https://financialaid.usc.edu/undergraduate-financial-aid/admitted-and-continuing-students/special-circumstances-and-appeals-undergaduate-continuing/\",\"title\":\"Special Circumstances and Appeals (Continuing Undergraduates) - Financial Aid\"},{\"url\":\"https://ask.usc.edu/s/article/000002497\",\"title\":\"askUSC: How do I notify the Financial Aid Office of a change in my housing plans?\"},{\"url\":\"https://ask.usc.edu/s/article/000002470\",\"title\":\"askUSC: I am an undergraduate student and have been approved for a reduced course load of less than full-time (12 units). How will this affect my financial aid?\"}]},{\"id\":\"request-cost-of-attendance-budget-increase\",\"topic\":\"04\",\"name\":\"Request a cost of attendance (budget) increase\",\"desc\":\"Student has school-related expenses above the standard budget (computer, rent, childcare, travel, fees) and wants more loan eligibility.\",\"system\":\"FAST Document Library: \\\"Appeal Concerning Increase in Estimated Cost of Attendance\\\"\",\"steps\":[\"Review your current federal loan debt at studentaid.gov.\",\"Gather documentation for the expense (receipts, lease, childcare contract, department memo, OSAS letter, etc.).\",\"In FAST > Document Library, submit \\\"Appeal Concerning Increase in Estimated Cost of Attendance\\\" with the documentation.\",\"Wait 2-3 weeks; you will get an email when you can apply for the additional loan funds.\",\"Apply for the added loan as instructed.\",\"If the semester has already ended, federal loans can no longer be adjusted; to use a private loan for the increase, email the Financial Aid Office through askUSC.\"],\"req\":[\"Considered case by case; typically funded with Federal Direct Loans or private financing.\",\"Prior indebtedness may be considered.\",\"Computer must be purchased no earlier than June 1 before the academic year; rent must exceed the standard budget ($1,431/month for undergraduates).\",\"If the aggregate federal maximum is reached, only tuition and fees can be considered.\"],\"deadlines\":[\"Submit the appeal and all documents at least 30 days before the end of the term.\",\"After the semester ends, federal loan adjustments are not possible; a private loan may be.\"],\"costs\":[\"Funded with loans that must be repaid with interest (rates and fees depend on loan type).\"],\"fields\":[\"expense type and amount\",\"term\",\"documentation available\",\"preferred loan type\",\"awareness of current total debt\"],\"sources\":[{\"url\":\"https://ask.usc.edu/s/article/000001133\",\"title\":\"askUSC: How can I increase the amounts of federal loans I have borrowed to cover additional expenses?\"},{\"url\":\"https://financialaid.usc.edu/undergraduate-financial-aid/admitted-and-continuing-students/special-circumstances-and-appeals-undergaduate-continuing/\",\"title\":\"Special Circumstances and Appeals (Continuing Undergraduates) - Financial Aid\"},{\"url\":\"https://ask.usc.edu/s/article/000002578\",\"title\":\"askUSC: What are my options if I need to submit a budget appeal for more financial aid after the semester has ended?\"}]},{\"id\":\"set-up-financial-aid-refund-direct-deposit\",\"topic\":\"04\",\"name\":\"Set up direct deposit (eRefund) for a financial aid refund\",\"desc\":\"Student whose aid exceeds their charges wants the credit balance refunded to their bank account.\",\"system\":\"USCe.pay (Student Financial Services): My Account > eRefund / direct deposit\",\"steps\":[\"Log in to USCe.pay.\",\"Under My Account, sign up for eRefund/direct deposit with your bank account.\",\"Allow 3-5 business days for the initial setup.\",\"Once aid exceeding your charges posts, the refund is deposited within 2-3 business days.\"],\"req\":[\"A credit balance on the student account.\",\"With an active payment plan, a budget change is required before a refund can be made.\",\"Parent PLUS refunds go automatically to the person designated on the loan application (typically the parent).\"],\"deadlines\":[\"Spring 2027 refunds begin January 6, 2027 (fall 2026 began August 19, 2026).\"],\"costs\":[\"none stated\"],\"fields\":[\"that the student will enter bank details directly in USCe.pay (the assistant should not collect them)\",\"expected refund term\",\"whether a payment plan is active\",\"whether the refund comes from a Parent PLUS loan\"],\"sources\":[{\"url\":\"https://ask.usc.edu/s/article/000001376\",\"title\":\"askUSC: How do I receive my refund once my financial aid has been disbursed?\"},{\"url\":\"https://sfs.usc.edu/refunds/\",\"title\":\"Refunds - Student Financial Services\"},{\"url\":\"https://sfs.usc.edu/deadlines/\",\"title\":\"Dates and Deadlines - Student Financial Services\"}]},{\"id\":\"request-late-fee-reversal-pending-aid\",\"topic\":\"04\",\"name\":\"Request reversal of late fees caused by pending aid\",\"desc\":\"Student was charged late settlement fees or finance charges because their financial aid had not disbursed by the deadline.\",\"system\":\"askUSC \\\"Email Us\\\" contact form to the Financial Aid Office (topic: \\\"Late Charges Waived\\\"); balances checked in USCe.pay\",\"steps\":[\"Confirm the late fees/finance charges are from the semester your pending aid was meant for.\",\"Pay your account in full, minus the late and finance charges (check the balance in USCe.pay).\",\"Go to askUSC, select \\\"Email Us,\\\" and request the reversal using the topic \\\"Late Charges Waived.\\\"\"],\"req\":[\"Late fees and charges are not reversed automatically.\",\"Only charges from the semester the pending aid was intended for can be reversed.\",\"If the pending aid, loan or appeal is denied, the account must be settled within two weeks of the denial.\"],\"deadlines\":[\"Settle the account within two weeks of any denial to stay eligible for a reversal.\"],\"costs\":[\"Spring 2027 late settlement fees: $100 each on January 8, 15 and 22, 2027; monthly finance charge at a 12 percent annual rate on unpaid balances.\"],\"fields\":[\"term\",\"amount of late fees/finance charges\",\"which aid was pending and when it disbursed\",\"that the account is paid in full except those charges\"],\"sources\":[{\"url\":\"https://ask.usc.edu/s/article/000001436\",\"title\":\"askUSC: What happens if I have late/finance charges or my financial aid isn't disbursed to my account before my bill is due?\"},{\"url\":\"https://sfs.usc.edu/deadlines/\",\"title\":\"Dates and Deadlines - Student Financial Services\"}]},{\"id\":\"apply-parent-plus-loan\",\"topic\":\"04\",\"name\":\"Apply for a Parent PLUS Loan\",\"desc\":\"Parent of a dependent undergraduate wants to borrow a Federal Direct Parent PLUS Loan to cover the remaining balance.\",\"system\":\"studentaid.gov PLUS Loan application and PLUS Master Promissory Note; status tracked in the student's FAST portal\",\"steps\":[\"Student submits the FAFSA.\",\"Check the academic year and loan period on the student's Financial Aid Summary in FAST.\",\"Parent logs in to studentaid.gov, selects \\\"PLUS Loans: Graduate PLUS and Parent PLUS\\\" under Grants and Loans, and applies, choosing the maximum or a specific amount (do not leave \\\"loan amount requested\\\" blank).\",\"If approved, the parent signs the PLUS MPN when notified (not required if a qualifying Parent PLUS MPN for the student exists).\",\"If denied: the parent may appeal or reapply with an endorser (then complete PLUS Counseling), or the student may request an additional Direct Unsubsidized Loan in FAST.\",\"Track status in FAST; the Financial Aid Office emails confirmation once the loan is processed.\"],\"req\":[\"Student is dependent, enrolled at least half-time (6 units) as an undergraduate, in the units on the aid summary, and maintaining SAP.\",\"Parent is the biological or adoptive parent or stepparent; parent and student are U.S. citizens or eligible non-citizens.\",\"Credit check: no adverse credit history (or approved endorser/appeal).\",\"New borrowers (first Parent PLUS disbursed on or after July 1, 2026): $20,000 per year and $65,000 aggregate per dependent student.\"],\"deadlines\":[\"USC encourages applying no sooner than 45 days before the start of a semester.\",\"Complete loan steps no later than 30 days before the start of the first semester.\"],\"costs\":[\"Fixed 9.07 percent interest for loans first disbursed July 1, 2026 - June 30, 2027.\",\"Federal origination fee deducted from each disbursement (the USC page lists 4.228 percent for loans made October 1, 2020 - before October 1, 2025; the current fee is not stated).\"],\"fields\":[\"parent borrower\",\"academic year and loan period\",\"amount requested (maximum or specific amount)\",\"student is dependent and enrolled at least half-time\",\"new vs. existing Parent PLUS borrower (OBBBA limits)\"],\"sources\":[{\"url\":\"https://ask.usc.edu/s/article/000001452\",\"title\":\"askUSC: How do I apply for loans?\"},{\"url\":\"https://ask.usc.edu/s/article/000002731\",\"title\":\"askUSC: When should I apply for a PLUS loan?\"},{\"url\":\"https://ask.usc.edu/s/article/000002966\",\"title\":\"askUSC: When I apply for a PLUS loan, what should I select for \\\"loan amount requested\\\"?\"},{\"url\":\"https://financialaid.usc.edu/loans/\",\"title\":\"Loans - Financial Aid\"}]},{\"id\":\"submit-housing-application\",\"topic\":\"05\",\"name\":\"Apply for USC Housing and confirm the contract\",\"desc\":\"A newly admitted student (or a current student not living in USC Housing) wants to submit a housing application and then accept the assignment they are offered.\",\"system\":\"USC Housing Application Portal (housing.usc.edu/portal); paper application option mailed to USC Housing Services, 620 McCarthy Way, PSX 137\",\"steps\":[\"Be admitted and have a 10-digit USC ID. New graduate students first register on the Housing portal and create a USC Housing account; newly admitted undergraduates do not need to register.\",\"Log in to the Housing portal (new students: user name is the email used when applying to USC; returning/continuing students: USC email) and open the Housing Application.\",\"Select the term (Academic Year 2026\u20132027, Spring 2027, Graduate Academic Year, Graduate Full Year, or Law Housing).\",\"Complete Personal and Contact Details, any Specific Accommodation Request (requires OSAS registration), and the Profile (check \\\"Include in Roommate Search\\\" and create a screen name to use roommate matching).\",\"Choose the application category: \\\"New to USC\\\" or \\\"Continuing Non-resident Student.\\\"\",\"List five housing preferences in order (four for graduate housing); optionally choose a Living Learning Community or Graduate Housing Program and list its building first; complete any supplemental application.\",\"Pay the $65 non-refundable application fee (Visa, MasterCard, American Express, Discover). The application is then complete and eligible for assignment.\",\"Optionally create a roommate group with mutual requests (screen names or USC IDs).\",\"When emailed an assignment, log back in, review it, pay the $800 confirmation payment, read the Living Agreement and click \\\"I Agree\\\" by the due date; print the confirmation page.\"],\"req\":[\"Must be admitted with a 10-digit USC ID; you may apply before sending the Enrollment Commitment Deposit, but only certified students (deposit form + $300 enrollment deposit or approved waiver) can be assigned.\",\"Fall first-year students whose application is received by May 1 are guaranteed a space (not a specific building); May 1 is also the deadline for Living Learning Communities and freshman roommate matching.\",\"Transfers, new graduate students and continuing non-residents are not guaranteed housing; assignments go by application date and availability.\",\"Roommate requests must be mutual, within the same class standing category, with identical housing preferences; they are not guaranteed and are only for online applicants.\",\"If the contract is not confirmed and the confirmation payment made by the due date, the assignment is cancelled.\"],\"deadlines\":[\"2026\u201327 cycle: application opened February 2, 2026; May 1, 2026 deadline for guaranteed freshman housing, LLCs and freshman roommate matching.\",\"Spring 2027: application opened July 1, 2026; spring assignments emailed starting late November 2026.\",\"2027\u201328 new-student dates: not yet posted on USC sites (as of November 9, 2026).\",\"Contract confirmation: by the due date shown with the assignment.\"],\"costs\":[\"$65 non-refundable application processing fee (cannot be waived).\",\"$800 confirmation payment when confirming an academic-year contract ($400 credited to fall rent and $400 to spring rent); $400 for spring and summer contracts.\",\"Cal Grant or Pell Grant recipients may qualify for a deferral of the confirmation fee (billed in July).\",\"Rent varies by building and room type (2026\u201327 rates are on each building page).\"],\"fields\":[\"admission status and 10-digit USC ID\",\"term being applied for\",\"application category (New to USC vs. Continuing Non-resident)\",\"ranked housing preferences (5, or 4 for graduate housing)\",\"Living Learning Community or graduate program choice\",\"roommate requests (screen names/USC IDs)\",\"accommodation needs and OSAS registration\",\"payment of the $65 fee\",\"for confirmation: assignment details, $800 payment and agreement to the Living Agreement\"],\"sources\":[{\"url\":\"https://housing.usc.edu/index.php/application-4/\",\"title\":\"Application | USC Housing\"},{\"url\":\"https://housing.usc.edu/index.php/assignments/\",\"title\":\"Assignments and Contracts | USC Housing\"},{\"url\":\"https://ask.usc.edu/s/article/000002745\",\"title\":\"Can I have the $800 housing confirmation fee waived? - askUSC\"},{\"url\":\"https://housing.usc.edu/index.php/registration-and-profile-4/\",\"title\":\"Registration and Contact Information | USC Housing\"}]},{\"id\":\"request-room-change\",\"topic\":\"05\",\"name\":\"Request a room change (reassignment)\",\"desc\":\"A resident wants to move to a different building, room type or roommate group, or swap spaces with another resident.\",\"system\":\"Before move-in: reassignment request on the USC Housing Portal. During the academic year: over-the-counter reassignment form at a Housing Customer Service Center (or the Housing Services Office in the McCarthy Way Parking Structure, PSX)\",\"steps\":[\"Confirm you have a current, active, confirmed assignment (new students must already have paid the $800 confirmation payment).\",\"Before move-in (new students mid-May to early July; returning residents early March to mid-July): log in to the Housing portal and submit a reassignment request listing up to three building/room-type preferences; for a group, every member submits an identical request.\",\"Wait for USC Housing: if a listed preference opens you are reassigned without being consulted and notified by email; your previous assignment is given to another student.\",\"During the academic year (fall from mid-September until reassignment closes in early November; spring from mid-January through early April): go to a Housing CSC (during the first week of each period only building CSCs do reassignments) and ask what spaces are open.\",\"If a suitable space is open, complete the reassignment form on the spot; roommate groups and students swapping spaces must come in together.\",\"Show your copy of the form to the CSC of your current assignment when checking out and to the CSC of your new assignment when checking in; complete the move within 24 hours.\"],\"req\":[\"Must have a current, active housing assignment; everyone in a group request must too, or the whole request is cancelled.\",\"Only one open request of any type at a time; up to three preferences; specific room/apartment numbers cannot be requested.\",\"Reassignment is not guaranteed and is not a roommate-matching process; there is no waiting list during the academic year.\",\"Students assigned for spring cannot reassign before move-in; they may request over-the-counter reassignment in mid-January.\",\"Once reassigned you give up all claim to your previous building and room type.\"],\"deadlines\":[\"New students (pre-move-in): Reassignment Request available mid-May through early July; all unfulfilled requests cancelled July 8, 2026.\",\"Fall 2026 over-the-counter reassignment: began Wednesday, September 9, 2026; deadline Friday, November 6, 2026, 4:00 pm (Fall 2026 Reassignment Procedures PDF) \u2014 now closed.\",\"Reassignments are halted from early November to mid-January; spring over-the-counter reassignment reopens in mid-January 2027 (after Spring Move-In on January 7) and runs through early April (exact Spring 2027 dates not yet posted).\"],\"costs\":[\"$75 non-refundable fee for each reassignment granted after your contract term has begun, even if you later ask to undo it (2026\u201327 Living Agreement); no fee is stated for pre-move-in requests.\"],\"fields\":[\"current building and room type\",\"desired building(s) and room type(s) (up to three)\",\"group members and whether all have active assignments\",\"whether this is a swap with a specific resident\",\"acknowledgment that the old assignment is forfeited\",\"move-out/move-in timing (within 24 hours)\",\"$75 reassignment fee acknowledged (if the contract term has begun)\"],\"sources\":[{\"url\":\"https://housing.usc.edu/index.php/reassignments-and-cancellations-2/\",\"title\":\"Reassignments and Cancellations | USC Housing\"},{\"url\":\"https://housing.usc.edu/index.php/section/after-move-in/\",\"title\":\"After Move-in (All Residents) | Sections | USC Housing\"},{\"url\":\"https://housing.usc.edu/index.php/section/pre-move-in-new-students/\",\"title\":\"Pre-Move In (New Students) | Sections | USC Housing\"},{\"url\":\"https://housing.usc.edu/wp-content/uploads/2026/09/Reassignment-2026_Remediated.pdf\",\"title\":\"Fall 2026 Reassignment Procedures (PDF) | USC Housing\"}]},{\"id\":\"submit-maintenance-request\",\"topic\":\"05\",\"name\":\"Submit a maintenance request (work order)\",\"desc\":\"A resident needs something repaired in their room, apartment or building (plumbing, A/C, appliances, internet, pests, etc.).\",\"system\":\"USC Housing Maintenance work orders: \\\"Work Orders\\\" link on housing.usc.edu (Housing Maintenance website), the building Customer Service Center, or the Housing Maintenance Office at (213) 740-4646 (24/7)\",\"steps\":[\"If it is an emergency affecting health or safety (gas leak, exposed live wires, someone stuck in an elevator, power outage, backed-up drains/toilets, inoperative fire alarm, door that will not lock/unlock, major water leak), call Housing Maintenance at (213) 740-4646 immediately.\",\"Otherwise, submit a work order online through the Work Orders link on housing.usc.edu, in person or by phone at your CSC, or by phone to (213) 740-4646.\",\"Describe the problem and exact location (for laundry machines, include the location and machine number).\",\"Keep the work order number (or a copy of the work order) to reference if the repair is not completed within five working days.\",\"Pests: submit a work order through your CSC and also call (213) 740-4646; report suspected bedbugs to your CSC right away.\",\"Internet (ResNet) problems: call Housing Maintenance at (213) 740-4646; cable TV with no reception after the setup steps: notify your CSC.\"],\"req\":[\"Must be a current USC Housing resident.\",\"Emergencies should be phoned in, not just submitted online.\",\"Use (213) 740-4646 when your CSC is closed.\"],\"deadlines\":[\"none stated (Housing Maintenance is available 24/7)\"],\"costs\":[\"none stated for routine repairs; damage caused by residents is billed using the Room Inventory & Damage List estimates\"],\"fields\":[\"building and room/apartment number\",\"description and location of the problem\",\"whether it is an emergency or safety issue\",\"resident contact information\"],\"sources\":[{\"url\":\"https://housing.usc.edu/index.php/section/additional-services/\",\"title\":\"Additional Services | Sections | USC Housing\"},{\"url\":\"https://housing.usc.edu/index.php/csc/\",\"title\":\"CSC (Customer Service Centers) | USC Housing\"},{\"url\":\"https://housing.usc.edu/index.php/integrated-pest-management-program/\",\"title\":\"Integrated Pest Management Program | USC Housing\"},{\"url\":\"https://housing.usc.edu/index.php/resnet/\",\"title\":\"ResNet | USC Housing\"}]},{\"id\":\"request-winter-break-housing\",\"topic\":\"05\",\"name\":\"Stay in housing over Winter Break\",\"desc\":\"A residence-hall or suite resident wants to remain on campus between the fall and spring semesters (Dec 16, 2026 \u2013 Jan 7, 2027).\",\"system\":\"USC Housing Services Office ((213) 740-2546) / building Customer Service Center \u2014 USC Housing's website describes no online winter-break housing request; the Living Agreement requires prior written authorization\",\"steps\":[\"Check your building type: apartment residents may stay through Winter Break with no request needed.\",\"Residence hall and suite residents must leave by 5:00 pm on December 16, 2026 (belongings may stay and keys need not be returned).\",\"If you need to stay, contact the Housing Services Office or your CSC well before December 16 to ask for prior express written authorization from the Director of USC Housing or a designee; if granted, pay the daily occupancy fee in advance.\",\"Return for Spring Move-In Day on January 7, 2027.\"],\"req\":[\"Residence halls (including suite-style buildings) are closed for Winter Break; residents may not occupy or access their rooms without written authorization.\",\"Apartment residents may occupy their units during Thanksgiving, Winter Break and Spring Break; rent covers those periods.\",\"Unauthorized occupancy during a break is a breach of the contract.\"],\"deadlines\":[\"Residence halls and suites close at 5:00 pm December 16, 2026.\",\"Spring Move-In Day: January 7, 2027.\",\"Residents released from Spring 2027 contracts: halls/suites vacate by 5:00 pm December 16, 2026; apartments by 5:00 pm December 18, 2026.\"],\"costs\":[\"Authorized occupancy outside contract dates: a daily fee established by USC Housing, paid in advance (amount not stated on USC sites)\",\"Unauthorized occupancy: $200 per day (2026\u201327 Living Agreement)\"],\"fields\":[\"building and room type (residence hall/suite vs. apartment)\",\"exact nights needed\",\"reason for staying\",\"written authorization from USC Housing\",\"daily fee amount\"],\"sources\":[{\"url\":\"https://housing.usc.edu/index.php/section/general-information/\",\"title\":\"General Information | Sections | USC Housing\"},{\"url\":\"https://housing.usc.edu/index.php/application-4/\",\"title\":\"Application | USC Housing\"},{\"url\":\"https://housing.usc.edu/index.php/csc/\",\"title\":\"CSC (Customer Service Centers) | USC Housing\"},{\"url\":\"https://housing.usc.edu/index.php/announcements/housing-cancellation-for-spring-2027/\",\"title\":\"Housing Cancellation for Spring 2027 | USC Housing\"}]},{\"id\":\"cancel-housing-contract\",\"topic\":\"05\",\"name\":\"Cancel a housing application or contract (or request release)\",\"desc\":\"A student wants to cancel a housing application, decline an assignment, cancel a confirmed contract, or be released from the spring semester of a contract.\",\"system\":\"Cancellation Request Form delivered to USC Housing Services (new students); USC Housing Portal \\\"I want to cancel my housing application\\\" (UHR/continuing residents); request for release through the Housing portal (current residents, e.g., Spring 2027)\",\"steps\":[\"Identify your situation: new student (not yet assigned / assigned but not confirmed / confirmed, before move-in), returning UHR resident, or current resident seeking release from a contract already in effect.\",\"New students (before the term starts): print and complete the 2026\u20132027 Cancellation Request Form and deliver it to USC Housing Services, 620 McCarthy Way, McCarthy Way Parking Structure (PSX) 137, Los Angeles, CA 90089-1332.\",\"UHR/returning residents (before the term starts): log in to the USC Housing Portal and click \\\"I want to cancel my housing application.\\\"\",\"Current residents leaving after fall: the Spring 2027 process was a request for release through the Housing portal with the reason and documentation (semester-away verification, proof of December graduation, or dropping all spring classes for withdrawal/leave), due by November 6, 2026.\",\"Any other release from a current contract: make the request in writing to a USC Housing Customer Service Representative in the Housing Services Office (the release form is available at the USC Housing central office); release is at USC's discretion.\",\"If approved, follow the emailed instructions, move out by the stated date and return your keys.\"],\"req\":[\"The $65 application fee is never refunded.\",\"After confirming, you are bound by the contract unless a cancellation or release is granted; requests that are not granted leave the contract in force.\",\"Withdrawal or non-enrollment does not automatically cancel a contract; written documentation is required (Living Agreement).\",\"Cancelling lowers future priority: if you reapply you are placed in the last category to be offered housing (Cancellation Request Form).\"],\"deadlines\":[\"New students 2026\u201327: cancellation granted by June 5, 2026 = full refund of the $800; after June 5 = no refund.\",\"UHR 2026\u201327: by 5:00 pm March 6, 2026 = no charge; by 5:00 pm May 1, 2026 = cancelled but $800 forfeited.\",\"Spring 2027 release: requests had to be received by Friday, November 6, 2026 (passed); vacate by 5:00 pm December 16, 2026 (halls/suites) or December 18, 2026 (apartments).\",\"2027\u201328 cancellation deadlines: not yet posted.\"],\"costs\":[\"$65 application fee: non-refundable.\",\"$800 confirmation payment: refunded only if cancellation is granted by the deadline for your category; otherwise forfeited.\",\"Release from a full academic-year contract: rent is prorated through the end of the month the request is approved or the month you fully vacate and check out, whichever is later; per USC Housing, your refund would be the remaining balance of rent paid, less $400. No credit of fall rent for an end-of-fall release (Living Agreement).\"],\"fields\":[\"student category (new student, UHR participant, current resident)\",\"term being cancelled\",\"contract status (assigned, confirmed, moved in)\",\"reason and supporting documentation\",\"refund or forfeiture of the $800 acknowledged\",\"move-out date\"],\"sources\":[{\"url\":\"https://housing.usc.edu/index.php/reassignments-and-cancellations-2/\",\"title\":\"Reassignments and Cancellations | USC Housing\"},{\"url\":\"https://housing.usc.edu/index.php/section/usc-housing-renewal-uhr/\",\"title\":\"USC Housing Renewal (UHR) | Sections | USC Housing\"},{\"url\":\"https://housing.usc.edu/index.php/announcements/housing-cancellation-for-spring-2027/\",\"title\":\"Housing Cancellation for Spring 2027 | USC Housing\"},{\"url\":\"https://housing.usc.edu/index.php/publication/housing-cancellation-request-2026-2027/\",\"title\":\"Housing Cancellation Request 2026-2027 (PDF) | USC Housing\"}]},{\"id\":\"report-lockout\",\"topic\":\"05\",\"name\":\"Get help when locked out / temporary key\",\"desc\":\"A resident is locked out of their room or building, or has lost a key, key fob or access card.\",\"system\":\"Building Customer Service Center (business hours); RA on ER \u2014 Resident Assistant on Emergency Response (after hours); USC DPS non-emergency 213-740-6000 if the RA cannot be reached; USCard Services for a lost USCard\",\"steps\":[\"During CSC business hours, go to your building's CSC with ID; you may borrow a key for up to 30 minutes and must return it.\",\"After CSC hours, call your area's RA on ER (number given at move-in and posted at your building's main entrance).\",\"If you cannot reach the RA on ER, call DPS at 213-740-6000.\",\"Be ready to show positive identification and proof that you live in the unit.\",\"If the key, fob or card is actually lost, tell your CSC (replacement/lock-change charges apply); report a lost USCard to USCard Services, McCarthy Way Parking Structure, (213) 740-8709.\"],\"req\":[\"Must be the assigned resident (ID and proof of occupancy).\",\"A borrowed key not returned within 30 minutes is presumed lost and the lock is changed at the resident's expense.\",\"All lockouts are recorded; after the fifth recorded lockout the resident may be referred for disciplinary action.\",\"Keys may not be duplicated except by the University.\"],\"deadlines\":[\"Borrowed key must be returned within 30 minutes.\"],\"costs\":[\"1st and 2nd recorded lockouts: free; 3rd: $25; each later lockout increases by $25 (2026\u201327 Living Agreement and Resident Information guide).\",\"Lost or stolen keys due to negligence: charged for a lock change plus replacement keys; the 2026\u201327 Resident Information guide says the minimum is $75 per lock change.\",\"Room Inventory & Damage List estimates (last updated 06/2025): lock change $115; room/stairwell/elevator/gate key $100; key fob $75; lost temporary access card $25; mailbox lock change $50.\"],\"fields\":[\"building and room/apartment\",\"whether the CSC is open\",\"number of prior lockouts this contract\",\"whether the key is lost or just left inside\",\"ID and proof of occupancy\"],\"sources\":[{\"url\":\"https://resed.usc.edu/resources/safety/\",\"title\":\"Safety - USC Residential Education\"},{\"url\":\"https://housing.usc.edu/index.php/room-inventory-damage-list/\",\"title\":\"Room Inventory & Damage List | USC Housing\"},{\"url\":\"https://dps.usc.edu/contact/\",\"title\":\"Contact - Department of Public Safety\"},{\"url\":\"https://mycard.usc.edu/contact/\",\"title\":\"Contact Us - USCard Services\"}]},{\"id\":\"apply-summer-housing\",\"topic\":\"05\",\"name\":\"Apply for summer housing\",\"desc\":\"A student (or eligible non-student) wants USC Housing for the summer, including Maymester participants.\",\"system\":\"USC Housing Application Portal (separate Summer Housing application)\",\"steps\":[\"Check the Summer Housing page; information for the upcoming summer is generally posted in mid-March.\",\"When the summer application opens, apply on the online Housing portal (non-USC applicants register on the portal to create a password).\",\"Choose one of the four summer contract periods (each has a fixed start and end date).\",\"When assigned, confirm the summer contract and pay the $400 confirmation payment.\",\"If you will stay straight from your spring contract into summer, expect the $50/night live-through fee for nights between contracts.\",\"Maymester participants: follow the Maymester information USC Housing provides in the spring.\"],\"req\":[\"Separate application and assignment process from the academic year; not all buildings are available in summer.\",\"Current USC students, and non-students who meet specific requirements, may be assigned.\",\"Summer residents are not released from the contract because they are not registered as students (Living Agreement).\"],\"deadlines\":[\"Summer 2027 application dates: not yet posted (information generally available mid-March).\",\"No Summer Housing in 2028 (USC Housing fully reserved for the LA28 Olympic Games).\"],\"costs\":[\"$400 confirmation payment for summer contracts.\",\"Summer rents are listed in the Summer Housing brochure and can differ from academic-year rents (2027 rates not yet posted).\",\"$50 per night live-through fee between contracts.\",\"Summer rent must be prepaid to the Cashier's Office or Housing Services Office before you move in (2026\u201327 Living Agreement).\"],\"fields\":[\"summer contract period\",\"building/room preferences\",\"USC student or non-student status\",\"Maymester participation\",\"whether continuing directly from a spring contract\"],\"sources\":[{\"url\":\"https://housing.usc.edu/index.php/summer-housing/\",\"title\":\"Summer Housing | USC Housing\"},{\"url\":\"https://housing.usc.edu/index.php/housing-fees/\",\"title\":\"Housing Fees | USC Housing\"},{\"url\":\"https://housing.usc.edu/index.php/section/application-and-assignments/\",\"title\":\"Application and Assignments | Sections | USC Housing\"},{\"url\":\"https://housing.usc.edu/index.php/section/rents-and-billing/\",\"title\":\"Rents and Billing | Sections | USC Housing\"}]},{\"id\":\"request-early-arrival\",\"topic\":\"05\",\"name\":\"Request early arrival\",\"desc\":\"A resident needs to move in before their contract start date for a USC program or personal reason.\",\"system\":\"Online Early Arrival Request on the USC Housing Portal; final approval by the building Customer Service Center\",\"steps\":[\"Submit an online Early Arrival Request through the Housing portal.\",\"Request no more than five days before your contract start date.\",\"Wait for your CSC's decision and call your CSC to verify approval before leaving home.\",\"Arrive on the approved date; $75 per approved night is charged.\"],\"req\":[\"University-affiliated program or personal need.\",\"Not available for spring semester housing.\",\"Individual requests may not be honored; approval depends on time to clean and prepare the room after summer occupants leave.\"],\"deadlines\":[\"Fall 2026 contract start dates were August 19 (undergraduates) and August 10 (graduates); requests may not be for more than five days before your start date.\"],\"costs\":[\"$75 per night if approved.\",\"$200 per night if you arrive without approval and can be accommodated (you may be turned away).\"],\"fields\":[\"requested arrival date\",\"number of early nights\",\"program or reason\",\"CSC approval\",\"total fee\"],\"sources\":[{\"url\":\"https://housing.usc.edu/index.php/requests-for-early-arrival/\",\"title\":\"Requests for Early Arrival | USC Housing\"},{\"url\":\"https://housing.usc.edu/index.php/section/general-information/\",\"title\":\"General Information | Sections | USC Housing\"}]},{\"id\":\"uhr-wait-list-signup\",\"topic\":\"05\",\"name\":\"Sign up for the UHR Wait List\",\"desc\":\"A current resident who did not get (or did not confirm) a space during USC Housing Renewal wants to be offered housing as spaces open.\",\"system\":\"USC Housing Portal (online application \u2192 \\\"Wait List Sign Up\\\")\",\"steps\":[\"Confirm you are a UHR participant with an active application and no confirmed UHR contract.\",\"Open your online application and click \\\"Wait List Sign Up\\\" before the sign-up deadline.\",\"Watch your USC email from late March through mid-August for an offer of one specific space.\",\"Accept within 24 hours by confirming the space in the Housing portal, or decline.\"],\"req\":[\"Only UHR participants with an active application who were not assigned or did not confirm during UHR.\",\"Wait List order is based on your February UHR selection time.\",\"Offers are for one specific space; roommates cannot be placed together from the Wait List.\",\"You are removed from the list once offered a space, whether or not you accept.\"],\"deadlines\":[\"2026 sign-up period: March 2\u201311, 2026 (2027 dates not yet posted).\",\"Offers: late March until mid-August or until the list is exhausted.\",\"24 hours to accept or decline an offer.\"],\"costs\":[\"none stated for signing up; a confirmed contract carries the standard $800 confirmation payment, charged to the student account for renewal participants\"],\"fields\":[\"UHR application status\",\"willingness to accept a single offered space\",\"checking USC email for offers\",\"response within 24 hours\"],\"sources\":[{\"url\":\"https://housing.usc.edu/index.php/section/uhr-waitlist-info/\",\"title\":\"Wait List | Sections | USC Housing\"},{\"url\":\"https://housing.usc.edu/index.php/renewal-procedures/\",\"title\":\"Renewal Procedures | USC Housing\"},{\"url\":\"https://housing.usc.edu/index.php/housing-fees/\",\"title\":\"Housing Fees | USC Housing\"}]},{\"id\":\"register-overnight-guest\",\"topic\":\"05\",\"name\":\"Register an overnight guest\",\"desc\":\"A resident wants to host a friend or family member overnight in their room or apartment.\",\"system\":\"Building Customer Service Center (or its designated agent), per the 2026\u201327 Living Agreement\",\"steps\":[\"Check that the visit fits the limits (no more than 3 consecutive nights, no more than twice a month; residence halls/suites max 2 guests at a time; apartments max 4 guests with no more than 2 overnight).\",\"Register the overnight guest with your Customer Service Center or its designated agent.\",\"Make sure the guest carries the guest pass issued at registration while in the building, and stays with you at all times.\",\"For a minor guest, provide parent/guardian approval for the overnight stay to the CSC.\"],\"req\":[\"Guest must be accompanied by the host; host is responsible for the guest's conduct.\",\"Guests are never issued keys or access cards.\",\"Additional limits may apply on home football game days and other special occasions; guests cannot arrive before or stay after contract dates.\"],\"deadlines\":[\"none stated beyond the night limits above\"],\"costs\":[\"none stated\"],\"fields\":[\"guest name and whether a minor\",\"dates/nights of stay\",\"building type (hall/suite vs. apartment) and number of guests\",\"guest pass issued\"],\"sources\":[{\"url\":\"https://resed.usc.edu/resources/residential-review-process-policies/\",\"title\":\"Residential Education Review Process & Policies - USC Residential Education\"},{\"url\":\"https://resed.usc.edu/resources/move-in/\",\"title\":\"Move-In - USC Residential Education\"},{\"url\":\"https://housing.usc.edu/index.php/publication/2026-2027-living-agreement/\",\"title\":\"2026-2027 Living Agreement (PDF) | USC Housing\"}]},{\"id\":\"change-meal-plan\",\"topic\":\"06\",\"name\":\"Change or upgrade a meal plan\",\"desc\":\"Student wants to switch to a different meal plan (e.g., Cardinal to Trojan, or Flex120 to Cardinal/Trojan) for the current or next semester.\",\"system\":\"USCard Services website (mycard.usc.edu \u2192 Meal Plans \u2192 \\\"Change or Purchase a Meal Plan\\\" \u2192 Meal Plan Application); meal plans are provided by USC Hospitality and administered by USCard Services; the change posts to the USC Student Billing Account\",\"steps\":[\"Go to mycard.usc.edu and click \\\"Change Your Plan\\\" (opens the Meal Plans page).\",\"Click \\\"Change or Purchase a Meal Plan\\\" to open the Meal Plan Application and choose the semester. As of November 9, 2026 the page lists only \\\"Purchase My Meal Plan \u2013 Fall 2026\\\" and \\\"Cancel My Meal Plan \u2013 Fall 2026\\\" forms; no Spring 2027 form is posted yet.\",\"Submit the form for the new plan; the choice is applied to the USC Student Billing Account.\",\"Alternatively, log in to the USCard account (Students \u2192 USC NetID), where students can manage meal plans.\",\"Check the student account in USCe.pay for the resulting debit or credit.\",\"Questions, including meal plan billing: uscard@usc.edu or (213) 740-8709, Mon\u2013Fri 9am\u20135pm.\"],\"req\":[\"First-year students in University Housing are assigned the Cardinal Plan and may upgrade to the Trojan Plan.\",\"Sophomores, juniors and seniors in USC Housing apartments are assigned Flex120 and must keep at least Flex120; they may upgrade (FAQ names Cardinal or Trojan).\",\"Upperclassmen in residence halls/suites are assigned the Cardinal Plan (full).\",\"Mandatory meal plans may not be canceled.\",\"Changes may result in a debit or credit to the student account.\",\"Graduate students and students whose housing does not require a plan may choose any plan on an optional basis.\"],\"deadlines\":[\"Fall 2026: September 2, 2026 (passed)\",\"Spring 2027: January 21, 2027\"],\"costs\":[\"Cardinal Plan $4,219/semester\",\"Trojan Plan $4,840/semester\",\"Flex120 Plan $2,074/semester\",\"Community 25 $500\",\"Community 50 $960\",\"Exact proration or price difference for a mid-semester change: not stated on USC sites\"],\"fields\":[\"student class standing and housing assignment (sets the required minimum plan)\",\"current plan\",\"new plan\",\"effective term (Fall 2026 or Spring 2027)\",\"price difference / expected debit or credit to the student account\",\"confirmation that the change deadline (January 21, 2027 for Spring) has not passed\"],\"sources\":[{\"url\":\"https://mycard.usc.edu/meal-plans/\",\"title\":\"Meal Plans \u2013 USCard Services\"},{\"url\":\"https://mycard.usc.edu/\",\"title\":\"USCard Services\"},{\"url\":\"https://mycard.usc.edu/meal-plan-application/\",\"title\":\"Meal Plan Application \u2013 USCard Services\"},{\"url\":\"https://hospitality.usc.edu/meal-plan-options/\",\"title\":\"Meal Plan Options \u2013 USC Hospitality\"}]},{\"id\":\"purchase-or-cancel-optional-meal-plan\",\"topic\":\"06\",\"name\":\"Purchase (or cancel) an optional meal plan\",\"desc\":\"Student who is not required to have a meal plan (off-campus, graduate, or in a building without a requirement) wants to buy a plan, or cancel an optional plan they bought.\",\"system\":\"USCard Services Meal Plan Application (mycard.usc.edu/meal-plan-application): \\\"PURCHASE MY MEAL PLAN \u2013 FALL 2026\\\" and \\\"CANCEL MY MEAL PLAN \u2013 FALL 2026\\\" forms\",\"steps\":[\"Go to mycard.usc.edu \u2192 Meal Plans \u2192 \\\"purchase one\\\" / \\\"Change or Purchase a Meal Plan\\\".\",\"Choose the semester on the Meal Plan Application page.\",\"Select \\\"Purchase My Meal Plan \u2013 Fall 2026\\\" (or \\\"Cancel My Meal Plan \u2013 Fall 2026\\\") and complete the form.\",\"The selection is applied to the USC Student Billing Account.\"],\"req\":[\"Available to students not required to have a meal plan (any plan, or a $250/$500 Dining Dollar Block).\",\"Mandatory meal plans may not be canceled.\",\"An optional plan is effective from the date of purchase until the end of the term; Community 25/50 end on the last day of the school year.\",\"Remaining funds cannot be refunded, transferred or sold.\",\"Only Fall 2026 purchase/cancel forms are currently posted; Spring 2027 forms not yet shown.\"],\"deadlines\":[\"Spring 2027 change deadline: January 21, 2027\",\"Fall 2026 deadline (September 2, 2026) has passed\"],\"costs\":[\"Community 25 $500\",\"Community 50 $960\",\"Flex120 $2,074/semester\",\"Cardinal $4,219/semester\",\"Trojan $4,840/semester\",\"Refund amount when canceling an optional plan: not stated on USC sites\"],\"fields\":[\"confirm the student is not on a mandatory plan\",\"plan to purchase (or plan to cancel)\",\"semester\",\"price charged to the student account\",\"start date (date of purchase)\"],\"sources\":[{\"url\":\"https://mycard.usc.edu/meal-plan-application/\",\"title\":\"Meal Plan Application \u2013 USCard Services\"},{\"url\":\"https://mycard.usc.edu/meal-plans/\",\"title\":\"Meal Plans \u2013 USCard Services\"},{\"url\":\"https://hospitality.usc.edu/frequently-asked-questions/\",\"title\":\"Frequently Asked Questions \u2013 USC Hospitality\"},{\"url\":\"https://hospitality.usc.edu/meal-plan-options/\",\"title\":\"Meal Plan Options \u2013 USC Hospitality\"}]},{\"id\":\"add-dining-dollars\",\"topic\":\"06\",\"name\":\"Add Dining Dollars (buy a Dining Dollar Block)\",\"desc\":\"Student wants more Dining Dollars mid-semester, with or without an existing meal plan.\",\"system\":\"USCard Services (mycard.usc.edu) \u2013 Dining Dollar Blocks are purchased \\\"via USCard\\\"; the exact purchase screen is not described on USC sites\",\"steps\":[\"Go to USCard Services at mycard.usc.edu (USC Hospitality's \\\"Change or Purchase a Plan\\\" button on the Meal Plan Options page links there); the exact block purchase screen is not described on USC pages.\",\"Choose a $250 or $500 Dining Dollar Block (10% discount applied at purchase).\",\"Complete the purchase; the Dining Dollars are used with the USCard at USC Hospitality dining halls and on-campus cafes.\"],\"req\":[\"Any student may purchase, at any time during the semester.\",\"Block Dining Dollars are forfeited on the last day of the semester and do not roll over; they are not refunded.\",\"Dining Dollars are only used at USC Hospitality venues that do not serve alcohol.\"],\"deadlines\":[\"Any time during the semester; unused block funds are forfeited on the last day of the semester\"],\"costs\":[\"$250 or $500 block, offered at a 10% discount (exact amount charged after the discount is not stated)\"],\"fields\":[\"block size ($250 or $500)\",\"semester the funds apply to\",\"acknowledgment that block funds expire at semester end and are non-refundable\",\"how the purchase will be paid/billed\"],\"sources\":[{\"url\":\"https://hospitality.usc.edu/frequently-asked-questions/\",\"title\":\"Frequently Asked Questions \u2013 USC Hospitality\"},{\"url\":\"https://hospitality.usc.edu/meal-plan-options/\",\"title\":\"Meal Plan Options \u2013 USC Hospitality\"},{\"url\":\"https://mycard.usc.edu/meal-plans/\",\"title\":\"Meal Plans \u2013 USCard Services\"}]},{\"id\":\"add-uscard-discretionary-funds\",\"topic\":\"06\",\"name\":\"Add USCard discretionary funds\",\"desc\":\"Student (or the student on their own account) wants to load money onto the USCard for purchases around campus.\",\"system\":\"USCard account at mycard.usc.edu (Log In \u2192 Students, USC NetID) or the USCard mobile app (iOS/Android); in person at USCard Customer Service Centers\",\"steps\":[\"Log in to the USCard account at mycard.usc.edu (Students \u2192 USC NetID) or open the USCard app.\",\"Choose to load/deposit funds and pay with a Visa, Mastercard or Discover credit/debit card.\",\"Or deposit in person at the UPC Customer Service Center (620 McCarthy Way) or One Stop at HSC (Seaver Residence Hall), Mon\u2013Fri 9am\u20135pm.\"],\"req\":[\"Discretionary funds are a prepaid declining balance separate from Dining Dollars.\",\"Balance rolls over to the next term.\",\"Not refundable until the student graduates or withdraws (then refunded via the student account).\",\"Accepted anywhere on campus and at select USC Village locations.\"],\"deadlines\":[\"none stated (online deposits available 24/7)\"],\"costs\":[\"none stated (no deposit fee mentioned); minimum/maximum deposit amounts not stated\"],\"fields\":[\"deposit amount\",\"payment method (Visa, Mastercard or Discover)\",\"USCard account/NetID being credited\",\"understanding that funds are non-refundable until graduation or withdrawal\"],\"sources\":[{\"url\":\"https://mycard.usc.edu/deposit-funds/\",\"title\":\"Deposit Funds \u2013 USCard Services\"},{\"url\":\"https://mycard.usc.edu/\",\"title\":\"USCard Services\"},{\"url\":\"https://mycard.usc.edu/contact/\",\"title\":\"Contact Us \u2013 USCard Services\"},{\"url\":\"https://mycard.usc.edu/login/\",\"title\":\"Log In to Your USCard Account \u2013 USCard Services\"}]},{\"id\":\"report-lost-uscard-freeze-replace\",\"topic\":\"06\",\"name\":\"Report a lost/stolen USCard, freeze it, and order a replacement\",\"desc\":\"Student lost their USCard (or it was stolen or damaged) and needs to protect funds/door access and get a new card.\",\"system\":\"USCard account (mycard.usc.edu) or USCard app to freeze; USCard Services (213) 740-8709 / DPS (213) 740-6000 after hours; Replacement ID online forms at mycard.usc.edu/replacement-id\",\"steps\":[\"Freeze the card immediately in the USCard account or USCard app.\",\"If you cannot get online: call USCard (213) 740-8709 (Mon\u2013Fri 9am\u20135pm) or the Department of Public Safety after hours at (213) 740-6000.\",\"If the card turns up, unfreeze/reactivate it in the account \u2014 do not order a replacement.\",\"If not found: go to mycard.usc.edu \u2192 Get Your USCard \u2192 Replacement ID and choose \\\"Use my photo on file\\\" or \\\"I want to upload a new photo\\\".\",\"If stolen, provide a police report so the $25 fee is waived; if worn/damaged, bring the card to a customer service center for a free replacement instead.\",\"Wait for the notification, then pick up the replacement at the customer service center and surrender the old card if you have it.\",\"In the meantime: get a temporary access card from your USC Housing Customer Service Center, ask a dining hall cashier/manager to log you in for meals, or ask DPS for building entry/temporary ID.\"],\"req\":[\"While frozen, funds and door access are unavailable until USCard is notified the card is found or replaced.\",\"The cardholder is responsible for all charges until the card is reported missing.\",\"Requesting a replacement immediately terminates services on the old card and transfers them to the new one; old IDs cannot be reactivated once a replacement is processed.\",\"A student may not possess more than one ID; replacement refunds will not be issued.\"],\"deadlines\":[\"Report immediately (no specific deadline stated)\"],\"costs\":[\"$25 replacement fee (one-time, charged at the time of the replacement request)\",\"$25 fee waived for stolen cards with a police report\",\"Free replacement for cards worn/damaged by normal wear and tear (in person, bring the card)\",\"USC Housing lists $25 for a lost temporary access card\"],\"fields\":[\"lost vs. stolen vs. damaged\",\"whether the card might still be found (freeze vs. replace \u2014 a replacement cannot be undone)\",\"police report available (for fee waiver)\",\"photo on file or new photo\",\"pickup location\",\"acknowledgment of the $25 fee\"],\"sources\":[{\"url\":\"https://mycard.usc.edu/2020/10/01/lost-card-2/\",\"title\":\"Lost or Stolen Cards \u2013 USCard Services\"},{\"url\":\"https://mycard.usc.edu/manage/\",\"title\":\"Manage Your Card \u2013 USCard Services\"},{\"url\":\"https://mycard.usc.edu/replacement-id/\",\"title\":\"Replacement ID \u2013 USCard Services\"},{\"url\":\"https://mycard.usc.edu/after-hours-help/\",\"title\":\"After Hours Help \u2013 USCard Services\"}]},{\"id\":\"request-dietary-accommodation\",\"topic\":\"06\",\"name\":\"Request a dietary accommodation or special meal arrangement\",\"desc\":\"Student with a food allergy, celiac disease, medical diet or religious dietary need (e.g., kosher) wants accommodations in campus dining, or an exception to a required meal plan.\",\"system\":\"USC Hospitality Registered Dietitian (Ask the Dietitian form, hospitality.usc.edu/ask-the-dietitian/); Office of Student Accessibility Services (MyOSAS online application) for exceptions to required meal plans\",\"steps\":[\"Submit the Ask the Dietitian form (name, email, class standing, question) well before the semester begins.\",\"Work with the Dietitian to choose the best dining venue and register for accommodations: Allergen Awareness Zone (Parkside), Gluten Awareness Zone (EVK), or the order-ahead protocol (all 3 dining halls).\",\"For kosher needs, ask the Dietitian about the Kosher A (first-year) or Kosher B (upperclass apartment) meal plans.\",\"If campus dining still cannot meet your needs, contact OSAS and start registration: complete the online student application and upload documentation of the dietary restriction.\",\"Meet with your OSAS Specialist; OSAS and the Nutritionist first exhaust campus dining options before an exception to a required meal plan is considered; your Specialist contacts you (typically by email) with the outcome.\"],\"req\":[\"Allergen Awareness Zone, Gluten Awareness Zone and order-ahead protocol require registration through the Registered Dietitian.\",\"OSAS meal plan exceptions require supporting documentation related to the dietary restrictions.\",\"USC cannot guarantee items are 100% free of trace allergens; dining venues do not carry EpiPens or other medication.\"],\"deadlines\":[\"Contact the Dietitian well before the semester begins / as soon as possible\",\"OSAS: enrolled students may register at any time\"],\"costs\":[\"none stated\"],\"fields\":[\"type of need (allergy, celiac/gluten, other medical, kosher, halal, vegan)\",\"dining hall(s) the student uses\",\"accommodation sought (awareness zone, order-ahead, kosher plan, meal plan exception)\",\"student class standing / housing / current meal plan\",\"whether supporting documentation is available (for OSAS)\"],\"sources\":[{\"url\":\"https://hospitality.usc.edu/frequently-asked-questions/\",\"title\":\"Frequently Asked Questions \u2013 USC Hospitality\"},{\"url\":\"https://hospitality.usc.edu/ask-the-dietitian/\",\"title\":\"Ask the Dietitian \u2013 USC Hospitality\"},{\"url\":\"https://osas.usc.edu/current-students/accommodation-information/residential-dining/\",\"title\":\"Residential & Dining - Office of Student Accessibility Services\"},{\"url\":\"https://osas.usc.edu/new-students/when-how-to-register/\",\"title\":\"When & How to Register - Office of Student Accessibility Services\"}]},{\"id\":\"request-emergency-meal-swipes\",\"topic\":\"06\",\"name\":\"Request emergency meal swipes\",\"desc\":\"Student facing an urgent, unforeseen food emergency wants short-term meal swipes loaded to their USCard.\",\"system\":\"USC Student Basic Needs (contact form at studentbasicneeds.usc.edu/contact \u2014 topic \\\"Emergency Meal Swipe Program\\\"; basicneeds@usc.edu); approved swipes loaded to the USCard via USC Auxiliary Services\",\"steps\":[\"Contact Student Basic Needs through the contact form (select \\\"Emergency Meal Swipe Program\\\") or email basicneeds@usc.edu.\",\"Provide name, USC email, phone, 10-digit USC ID, enrollment status, campus, class standing and school (contact form fields).\",\"Complete a brief intake consultation with SBN staff about your situation.\",\"SBN reviews requests on a rolling basis and notifies you of the outcome.\",\"If approved, SBN coordinates with USC Auxiliary Services to load a limited number of swipes onto your USCard; use them at EVK, Parkside or USC Village during the current semester.\"],\"req\":[\"Currently enrolled USC undergraduate or graduate student.\",\"Experiencing short-term food insecurity due to an unforeseen circumstance.\",\"No reliable or immediate access to meals.\",\"Able to participate in a brief intake consultation.\",\"Limited capacity: intake does not guarantee enrollment; priority to the most urgent need and fewest alternatives.\"],\"deadlines\":[\"Requests reviewed on a rolling basis\",\"Swipes are redeemable during the current semester\"],\"costs\":[\"none stated (no cost mentioned)\"],\"fields\":[\"current enrollment (undergrad/grad)\",\"nature of the unforeseen food emergency\",\"current meal access (any meal plan or other food resources)\",\"contact details (USC email, phone, 10-digit USC ID)\",\"availability for an intake consultation\"],\"sources\":[{\"url\":\"https://studentbasicneeds.usc.edu/programs-and-services/food-support/emergency-meal-swipe/\",\"title\":\"Emergency Meal Swipe - Student Basic Needs\"},{\"url\":\"https://studentbasicneeds.usc.edu/programs-and-services/food-support/\",\"title\":\"Food Support - Student Basic Needs\"},{\"url\":\"https://studentbasicneeds.usc.edu/contact/\",\"title\":\"Contact - Student Basic Needs\"},{\"url\":\"https://hospitality.usc.edu/frequently-asked-questions/\",\"title\":\"Frequently Asked Questions \u2013 USC Hospitality\"}]},{\"id\":\"check-balances\",\"topic\":\"06\",\"name\":\"Check meal swipe, Dining Dollar and USCard balances\",\"desc\":\"Student wants to see remaining meal swipes, Dining Dollars or discretionary funds, or review transactions.\",\"system\":\"USCard account (mycard.usc.edu \u2192 Log In \u2192 Students, USC NetID) or the USCard mobile app (iOS/Android)\",\"steps\":[\"Go to mycard.usc.edu \u2192 Log In \u2192 Students and sign in with your USC NetID, or open the USCard app.\",\"View balance and transaction history; manage meal plans from the same account.\"],\"req\":[\"Student logs in with their own USC NetID.\"],\"deadlines\":[\"none (online access 24/7)\"],\"costs\":[\"none stated\"],\"fields\":[\"which balance (meal swipes, Dining Dollars, discretionary funds)\",\"student is logged in with their own NetID\"],\"sources\":[{\"url\":\"https://mycard.usc.edu/manage/\",\"title\":\"Manage Your Card \u2013 USCard Services\"},{\"url\":\"https://mycard.usc.edu/\",\"title\":\"USCard Services\"},{\"url\":\"https://mycard.usc.edu/login/\",\"title\":\"Log In to Your USCard Account \u2013 USCard Services\"}]},{\"id\":\"request-brats-meal\",\"topic\":\"06\",\"name\":\"Request a B.R.A.T.S. sick meal delivery\",\"desc\":\"Sick student on a meal plan in USC Housing wants a bland meal (banana, rice, applesauce, toast, soup) delivered to their building.\",\"system\":\"USC Hospitality \u2013 email diningbratmeal@usc.edu; meal delivered to the customer service desk in the student's building\",\"steps\":[\"Email diningbratmeal@usc.edu with: first and last name, USC ID#, email address, telephone, building and room number, and delivery time.\",\"Allow at least two hours before the requested delivery time and order before the 7pm cut-off.\",\"Pick up the packaged meal at your building's customer service desk.\"],\"req\":[\"Must be on a USC Hospitality meal plan AND live in USC Housing.\",\"For students unable to leave their room for health reasons.\"],\"deadlines\":[\"Monday\u2013Friday 7:30am\u20139pm; Saturday & Sunday 11am\u20139pm\",\"Order cut-off 7pm\",\"Allow at least two hours before delivery\"],\"costs\":[\"none stated\"],\"fields\":[\"name and USC ID#\",\"email and phone\",\"building and room number\",\"requested delivery time (at least two hours out, before 7pm cut-off)\",\"confirmation the student has a meal plan and lives in USC Housing\"],\"sources\":[{\"url\":\"https://hospitality.usc.edu/request-a-brats-meal/\",\"title\":\"Request a B.R.A.T.S. Meal \u2013 USC Hospitality\"}]},{\"id\":\"get-first-uscard\",\"topic\":\"06\",\"name\":\"Get a first USCard\",\"desc\":\"New student needs their first USC ID card.\",\"system\":\"USCard Services online ID application (mycard.usc.edu \u2192 Get Your USCard \u2192 \\\"FIRST ID \u2013 UPLOAD YOUR PHOTO\\\"); activation in the USCard account\",\"steps\":[\"Go to mycard.usc.edu \u2192 Get Your USCard \u2192 \\\"First ID \u2013 Upload Your Photo\\\".\",\"Fill out the USC ID Application.\",\"Securely upload a photo meeting the requirements and a government- or state-issued photo ID.\",\"Select your university affiliation (student).\",\"Watch for the email with the status of your submission.\",\"After receiving the card, activate it: log in to the USCard account with your USC NetID \u2192 Activate Card (under Card Services).\"],\"req\":[\"Must be registered for the current academic semester.\",\"Photo: recent, front-view, color, unedited (no filters), space above head, no hats or sunglasses, max 10MB.\",\"Only one ID may be held at a time.\",\"Where to collect a first card is not stated on current USCard pages; USCard customer service centers (UPC: 620 McCarthy Way; HSC: One Stop, Seaver Residence Hall) are open Mon\u2013Fri 9am\u20135pm.\"],\"deadlines\":[\"none stated\"],\"costs\":[\"First USC ID is free\"],\"fields\":[\"student is registered for the current semester\",\"photo meets requirements\",\"government/state photo ID ready to upload\",\"affiliation (student)\",\"how/where the student will collect the card (not stated online; confirm with USCard Services)\"],\"sources\":[{\"url\":\"https://mycard.usc.edu/get-your-uscard/\",\"title\":\"Get Your USCard \u2013 USCard Services\"},{\"url\":\"https://mycard.usc.edu/activate/\",\"title\":\"Activate your USCard in 5 easy steps \u2013 USCard Services\"},{\"url\":\"https://mycard.usc.edu/contact/\",\"title\":\"Contact Us \u2013 USCard Services\"}]},{\"id\":\"donate-dining-dollars\",\"topic\":\"06\",\"name\":\"Donate unused Dining Dollars\",\"desc\":\"Student with leftover Dining Dollars at the end of the semester wants to donate them to students facing food insecurity.\",\"system\":\"USC Campus Dining mobile ordering app (\\\"Dining Dollar Donation\\\"); donations support Student Basic Needs programs\",\"steps\":[\"Open the USC Campus Dining mobile ordering app.\",\"Scroll to the bottom of the homepage.\",\"Select \\\"Dining Dollar Donation\\\".\",\"Schedule the donation before the semester deadline.\"],\"req\":[\"Available about 2 weeks before the end of the Fall and Spring semesters.\",\"Donated Dining Dollars are converted into meal swipes distributed by Student Basic Needs.\"],\"deadlines\":[\"About 2 weeks prior to the end of the Fall and Spring semesters; exact Fall 2026 deadline not stated\",\"Fall 2026 meal plans end December 16, 2026; Spring 2027 meal plans end May 12, 2027\"],\"costs\":[\"none\"],\"fields\":[\"donation amount\",\"semester the donation applies to\",\"that the donation is scheduled before the semester deadline\"],\"sources\":[{\"url\":\"https://studentbasicneeds.usc.edu/programs-and-services/food-support/emergency-meal-swipe/\",\"title\":\"Emergency Meal Swipe - Student Basic Needs\"},{\"url\":\"https://hospitality.usc.edu/frequently-asked-questions/\",\"title\":\"Frequently Asked Questions \u2013 USC Hospitality\"},{\"url\":\"https://hospitality.usc.edu/community-partnerships/\",\"title\":\"Community Partnerships \u2013 USC Hospitality\"},{\"url\":\"https://mycard.usc.edu/meal-plans/\",\"title\":\"Meal Plans \u2013 USCard Services\"}]},{\"id\":\"use-trojan-food-pantry\",\"topic\":\"06\",\"name\":\"Get groceries from the Trojan Food Pantry\",\"desc\":\"Student experiencing food insecurity wants free supplemental groceries.\",\"system\":\"Student Basic Needs \u2013 Trojan Food Pantry (King Hall KOH Suite 103) with a once-per-semester intake form (Qualtrics, linked from the pantry page)\",\"steps\":[\"Complete the Trojan Food Pantry intake form (once per semester).\",\"Take a screenshot of the completed form to show at your first visit of the term.\",\"Go during posted hours with your physical USCard (swiped every visit) and a reusable bag.\"],\"req\":[\"Enrolled at USC during the term.\",\"No active dining hall meal plan (students with 20 or fewer remaining meals may be considered).\",\"Experiencing food insecurity.\",\"No pickups on behalf of friends.\"],\"deadlines\":[\"Fall/Spring: Tuesdays, Wednesdays & Thursdays 10:00am\u20132:00pm, about 15 weeks (first week of classes through Classes End week)\",\"Summer: Wednesdays 11:00am\u20132:00pm, first week of June through last week of July\"],\"costs\":[\"Free (no cost stated)\"],\"fields\":[\"current enrollment\",\"meal plan status / remaining meals\",\"intake form completed this semester\",\"has physical USCard\"],\"sources\":[{\"url\":\"https://studentbasicneeds.usc.edu/programs-and-services/food-support/trojan-food-pantry/\",\"title\":\"Trojan Food Pantry - Student Basic Needs\"}]},{\"id\":\"request-discretionary-refund\",\"topic\":\"06\",\"name\":\"Request a refund of USCard discretionary funds\",\"desc\":\"Graduating or withdrawing student wants remaining discretionary funds refunded.\",\"system\":\"Email USCard Services at uscard@usc.edu; refund credited to the USC student account, then refunded by the university cashier\",\"steps\":[\"Email uscard@usc.edu: if graduating, request that the account be closed and refunded; if withdrawing, request a refund of remaining discretionary funds.\",\"The remaining balance is credited to your student account.\",\"Any credit balance is refunded by the university cashier to your specified bank account.\"],\"req\":[\"Discretionary deposits are not refundable until you graduate or withdraw.\",\"Dining Dollars on the Trojan and Flex120 plans and Dining Dollar Blocks are not refundable.\",\"For registered students, accounts with no transactions for 12 months are refunded automatically to the student billing account.\"],\"deadlines\":[\"At graduation or withdrawal (no specific deadline stated)\"],\"costs\":[\"none stated\"],\"fields\":[\"reason (graduating or withdrawing)\",\"USC ID / account\",\"confirmation the refund goes to the student account (then to the bank account on file)\"],\"sources\":[{\"url\":\"https://mycard.usc.edu/deposit-funds/\",\"title\":\"Deposit Funds \u2013 USCard Services\"},{\"url\":\"https://mycard.usc.edu/uscard-terms-and-conditions/\",\"title\":\"USCARD TERMS AND CONDITIONS \u2013 USCard Services\"},{\"url\":\"https://mycard.usc.edu/2020/07/01/graduating-credit-balances/\",\"title\":\"Graduating \u2013 Credit Balances \u2013 USCard Services\"},{\"url\":\"https://hospitality.usc.edu/frequently-asked-questions/\",\"title\":\"Frequently Asked Questions \u2013 USC Hospitality\"}]},{\"id\":\"book-student-health-appointment\",\"topic\":\"07\",\"name\":\"Book a Student Health appointment\",\"desc\":\"Student wants a medical visit (illness/injury, physical, sexual health, immunization, lab) at Engemann (UPC), Eric Cohen (HSC) or via telehealth.\",\"system\":\"MySHR patient portal (usc.edu/myshr) or USC Student Health phone line 213-740-9355 (WELL)\",\"steps\":[\"Make sure your USC NetID is active (MySHR access is available within 48 hours of NetID activation).\",\"Log in to MySHR at usc.edu/myshr with your NetID.\",\"If prompted, complete Consent to Treatment (and Health History) and Financial Responsibility forms; students under 18 need a third-party minor consent or self-sufficient minor form.\",\"Go to \\\"Appointments\\\" (from the Home screen, \\\"Schedule an Appointment\\\") and choose the visit type: provider consultation, illness/injury (same-day/next-day), immunizations, or lab.\",\"Choose in-person (Engemann UPC or Eric Cohen HSC) or telehealth and select an available time.\",\"If no availability is shown for an urgent illness/injury, call 213-740-9355 (WELL).\",\"Arrive on time: arriving 10 or more minutes late cancels the appointment.\"],\"req\":[\"Student must be participating in the Student Health Fee (automatic for 6+ units, international and HSC students; online students may opt in if in California).\",\"Clinical care (medical, individual counseling, group therapy) is limited to patients currently in California; telehealth requires current California residence.\",\"Specialist visits (allergy, dermatology, nutrition, orthopedics) require a referral from a USC Student Health provider.\",\"Life-threatening emergencies: call 911 instead of booking.\"],\"deadlines\":[\"No booking deadline; same-day and next-day illness/injury slots are set aside each operating day.\",\"Typical fall/spring hours: Engemann closes 7 PM Mon-Thu, 5 PM Fri, 1 PM Sat; Eric Cohen opens 7 AM Mon/Tue, closes 7 PM Thu, 9-5 Wed/Fri.\"],\"costs\":[\"Visits with Student Health providers: covered by the Student Health Fee (no copays, no insurance billing).\",\"Labs, radiology, immunizations and equipment (crutches, boots) are billed to insurance. You have five business days to choose a payment method (in person, MySHR or phone); otherwise charges go to your USC student financial account.\",\"Summer 2026 pay-as-you-go option (past term; for students not in summer classes): $20 medical visit, $10 mental health visit.\"],\"fields\":[\"visit type / reason (illness-injury, physical, immunization, lab, sexual health)\",\"urgency (emergency -> 911; urgent -> same-day/next-day or call 213-740-9355)\",\"location (Engemann UPC, Eric Cohen HSC, or telehealth)\",\"whether the student is currently in California\",\"preferred date and time\",\"consent forms completed (and under-18 consent if applicable)\",\"possible extra charges (labs/radiology/immunizations)\"],\"sources\":[{\"url\":\"https://studenthealth.usc.edu/myshr/\",\"title\":\"MySHR Quickstart Guide - USC Student Health\"},{\"url\":\"https://studenthealth.usc.edu/fall-immunization-fair/\",\"title\":\"Fall Immunization Fair! - USC Student Health\"},{\"url\":\"https://sites.usc.edu/new-student-health-requirements/planning-your-care/things-to-know/\",\"title\":\"Top tips to know as a new student - Health Requirements for Students\"},{\"url\":\"https://studenthealth.usc.edu/fees-deadlines/\",\"title\":\"Fees and Deadlines List - USC Student Health\"}]},{\"id\":\"start-counseling-or-lets-talk\",\"topic\":\"07\",\"name\":\"Start counseling / attend Let's Talk\",\"desc\":\"Student wants to talk to a counselor: a 30-minute Let's Talk drop-in, a first-time counseling (initial assessment) appointment, an embedded counselor, a group, or UWill teletherapy.\",\"system\":\"MySHR patient portal (usc.edu/myshr) - Appointments / workshops tab / Messages; or email studenthealth@usc.edu (subject \\\"CMH Appointment\\\"); or call 213-740-9355 (WELL)\",\"steps\":[\"Let's Talk: log in to MySHR, open the \\\"workshops\\\" tab, pick a Let's Talk session (general or community-specific) and get the Zoom link.\",\"First-time counseling: in MySHR go to Appointments > Counseling and Mental Health (Telemedicine Consult) > \\\"Initial Appointment \u2013 First time clients\\\" and choose the academic or cultural-center embedded therapist site you prefer.\",\"Alternative: email studenthealth@usc.edu with subject \\\"CMH Appointment\\\" (name, student ID, date of birth, optional provider/embedded-site preference); you get a call back within 1 business day.\",\"To request a specific therapist, call 213-740-9355 (WELL) or email the CMH scheduling desk at studenthealth@usc.edu.\",\"Group therapy: submit a Counseling Group Interest Form in MySHR (New Appointment section / Messages).\",\"UWill teletherapy: request UWill under \\\"Appointments\\\" in MySHR; eligibility is confirmed within 2 business days, then follow the email invitation to schedule.\",\"Crisis: do not wait for an appointment - call 213-740-9355 (24/7), 988, or 911.\"],\"req\":[\"Let's Talk: open to currently enrolled students under the Student Health Fee regardless of location; it is not psychotherapy treatment.\",\"Initial assessment, individual counseling and formal group therapy: student must currently be in California.\",\"UWill: only for students currently in California participating in the Student Health Fee and not currently being seen as CMH clients.\",\"Long-term ongoing individual therapy is not covered by the fee; it is referred out (insurance-based).\"],\"deadlines\":[\"No deadline; Let's Talk schedule is posted in the MySHR workshops tab and is subject to change.\",\"Email requests: follow-up call within 1 business day.\"],\"costs\":[\"Let's Talk, intake/assessment, crisis sessions, workshops, group counseling and psychiatric medication management: covered by the Student Health Fee.\",\"Late cancellation (<12 hours notice) or no-show: $20.\",\"Insurance-based care (PBHS, community providers): SHIP/Aetna mental health copay $10 at Tier 1/2.\"],\"fields\":[\"service type (Let's Talk, initial assessment, group, UWill, embedded counselor)\",\"whether this is a crisis (route to 213-740-9355 / 988 / 911)\",\"whether the student is currently in California\",\"provider or identity preferences / embedded location\",\"preferred times\",\"cancellation policy ($20 late cancel/no-show)\"],\"sources\":[{\"url\":\"https://sites.usc.edu/counselingandmentalhealth/services/lets-talk/\",\"title\":\"let's talk - USC Counseling & Mental Health Services\"},{\"url\":\"https://sites.usc.edu/counselingandmentalhealth/myshr-screenshot-guide/\",\"title\":\"MySHR Step-by-step guide - USC Counseling & Mental Health Services\"},{\"url\":\"https://sites.usc.edu/counselingandmentalhealth/make-an-appointment/\",\"title\":\"Make an Appointment - USC Counseling & Mental Health Services\"},{\"url\":\"https://sites.usc.edu/counselingandmentalhealth/services/group-therapy-3/\",\"title\":\"Group Therapy - USC Counseling & Mental Health Services\"}]},{\"id\":\"refill-prescription\",\"topic\":\"07\",\"name\":\"Refill (or transfer) a prescription\",\"desc\":\"Student wants to refill a prescription at a USC Pharmacy or move a prescription from a home pharmacy to USC.\",\"system\":\"USC Pharmacies (pharmacies.usc.edu): online refill service (\\\"Prescription Refill\\\" link), 24-hour automated refill line, or in person at USC Pharmacy (King Hall, UPC) / USC Medical Plaza Pharmacy (HSC) / USC Pharmacy and Wellness Center\",\"steps\":[\"Online: use the USC Pharmacies online refill service (\\\"Prescription Refill\\\" link on pharmacies.usc.edu).\",\"Phone: call the 24-hour automated refill line using the pharmacy numbers on the Prescriptions page (USC Pharmacy (213) 821-6100; USC Medical Plaza Pharmacy (323) 442-5770; USC Pharmacy and Wellness Center (213) 740-2444).\",\"In person: come to the pharmacy and request the refill.\",\"Ask the pharmacy to call or text you when it is ready, or check status with the online refill service; refills are typically ready about 30 minutes after the request.\",\"To transfer from another pharmacy: give the USC pharmacy the current pharmacy name and phone number, the prescription number (if available), and your name, date of birth and medication name (USC Pharmacy and Wellness Center also offers a callback within two business days).\",\"Pay with insurance copay or full cost by cash, credit card, check, or USCard Discretionary Account.\"],\"req\":[\"The prescription must have refills remaining to be transferred; otherwise the pharmacy must contact your provider for a new prescription.\",\"Only prescriptions from California-licensed prescribers can be filled; out-of-state prescriptions require establishing care with a California-licensed physician.\",\"Some medications cannot be transferred due to state law (transfers are permitted for certain non-controlled prescriptions).\",\"Kaiser does not cover prescriptions outside Kaiser facilities (private pay).\",\"Mailing of prescriptions is discouraged.\"],\"deadlines\":[\"No deadline; USC Pharmacy (KOH) fall hours M-F 9 AM-6 PM (closed weekends); USC Medical Plaza Pharmacy M-F 8:30 AM-6 PM, Sat 9 AM-3 PM.\"],\"costs\":[\"Insurance copay or the full cost of the prescription (amount depends on medication and plan; not stated).\"],\"fields\":[\"medication name and strength\",\"prescription number (if known)\",\"pharmacy location for pickup\",\"insurance on file (SHIP/Aetna or other)\",\"whether refills remain / prescriber is California-licensed\",\"for transfers: current pharmacy name and phone\",\"pickup time and contact preference (call/text)\"],\"sources\":[{\"url\":\"https://pharmacies.usc.edu/prescriptions/\",\"title\":\"Prescriptions - USC Pharmacies\"},{\"url\":\"https://pharmacies.usc.edu/frequently-asked-questions/\",\"title\":\"Frequently Asked Questions - USC Pharmacies\"},{\"url\":\"https://pharmacies.usc.edu/transfer-your-prescriptions-to-usc-pharmacy-and-wellness-center/\",\"title\":\"Transfer Your Prescriptions to USC Pharmacy and Wellness Center\"},{\"url\":\"https://pharmacies.usc.edu/locations/\",\"title\":\"Locations - USC Pharmacies\"}]},{\"id\":\"enroll-in-student-health-insurance\",\"topic\":\"07\",\"name\":\"Enroll in the Student Health Insurance Plan (SHIP)\",\"desc\":\"Student wants SHIP/Aetna coverage: confirm automatic enrollment, keep the plan, get the ID card, or (part-time online students) ask about enrolling.\",\"system\":\"Automatic enrollment on registration (premium billed to the USC student account); Aetna Student Health website/app for the ID card; Student Health Insurance Office (213-821-1550) for enrollment questions\",\"steps\":[\"If you are a domestic student in 6+ units, in a health profession program, a PhD student, or an international student: you are automatically enrolled when you register - no action needed to keep SHIP.\",\"Do not submit a waiver (enrollment stays in place and the premium appears on your semester bill).\",\"After registration, get your ID card from the Aetna Student Health website (download PDF) or the Aetna app; cards are available at the start of the plan year (mid-August).\",\"Online degree students: with 6+ units you are automatically enrolled at the \\\"off-campus\\\" premium rate; with fewer than 6 units you may opt to enroll by contacting the Student Health Insurance Office (the enrollment steps are not described on USC sites).\",\"While enrolled: get a Student Health referral before seeing outside providers during fall/spring (not needed in emergencies or during official breaks).\"],\"req\":[\"Auto-enrolled groups: domestic 6+ units; health profession programs; PhD students; international students (regardless of units).\",\"Online degree students taking 6+ units are auto-enrolled (off-campus rate); part-time online students under 6 units may opt to enroll by contacting the Student Health Insurance Office. (USC's graduate-students page instead describes online students as opting in.)\",\"Students on USC-sponsored overseas programs without SHIP are automatically charged the overseas student plan.\"],\"deadlines\":[\"Plan year starts shortly before fall classes each August and runs 365 days.\",\"Enrollment is automatic at registration; enrollment deadline for part-time online students: not stated on USC sites.\"],\"costs\":[\"2026-27 on-campus premium: $1,313 (fall) and $2,474 (spring/summer) per USC 2026-27 cost pages ($3,787 total); online (off-campus) rate per the Price School fee table: $2,464 fall, $4,776 spring.\",\"Copays: $20 medical, $10 mental health (Tier 1/2), $50 urgent care.\",\"In-network deductible $450; in-network out-of-pocket maximum $6,000.\"],\"fields\":[\"enrollment group (units, program, international/PhD, online degree)\",\"term(s) of coverage and premium amount (on-campus vs. off-campus rate)\",\"that no waiver has been submitted\",\"for part-time online students: request to enroll via the Student Health Insurance Office\",\"ID card access (Aetna site/app)\"],\"sources\":[{\"url\":\"https://sites.usc.edu/ship/\",\"title\":\"Student Health Insurance Plan (SHIP)\"},{\"url\":\"https://sites.usc.edu/new-student-health-requirements/costs/health-insurance-requirement/\",\"title\":\"Health Insurance Requirement - Health Requirements for Students\"},{\"url\":\"https://studenthealth.usc.edu/graduate-students/\",\"title\":\"Graduate Students - USC Student Health\"},{\"url\":\"https://studenthealth.usc.edu/health-care-and-health-insurance/usc-student-health-insurance-through-aetna-at-a-glance/\",\"title\":\"USC Student Health Insurance At-A-Glance - USC Student Health\"}]},{\"id\":\"upload-immunization-records\",\"topic\":\"07\",\"name\":\"Upload immunization records\",\"desc\":\"New in-person student needs to submit proof of MMR, varicella and meningococcal ACWY (and TB screening if international from a high-burden country) to clear the immunization requirement/hold.\",\"system\":\"MySHR patient portal (usc.edu/myshr) - Medical Records / Immunization Requirements and History form\",\"steps\":[\"Gather records showing your name and date of birth, with an official signature or stamp (or have your provider complete the USC Immunizations Checklist); get English translations if needed; lab reports must include numeric values and reference ranges.\",\"Combine documents into a single file if possible (PDF, PNG, JPG or GIF).\",\"Log in to MySHR and complete the Immunization Requirements and History form.\",\"Navigate to \\\"Medical Records\\\" and upload your vaccination records/lab reports.\",\"Fill out the immunization date fields shown on the MySHR immunizations page - documentation is not reviewed unless the date fields are filled out.\",\"Check your immunization status in MySHR.\",\"If anything is missing, book the Immunization Fair (first week of classes) or an immunization appointment in MySHR.\"],\"req\":[\"Required for all new undergraduate and graduate students in any in-person class; online-only students are exempt.\",\"MMR: 2 doses or titers; Varicella: 2 doses or positive titer; MenACWY: dose on/after 16th birthday (students 21 and under).\",\"TB: international students from high-TB-burden countries - QuantiFERON/T-SPOT blood test from a U.S. lab within 6 months of the start of classes.\",\"Exemptions: Student Health's Medical Policies and Forms page lists a Medical Exemption and a Religious Exemption for Immunization form; a medical exemption is completed by your provider and uploaded to MySHR.\"],\"deadlines\":[\"Spring 2027: complete immunizations by the first day of classes, Jan. 11, 2027.\",\"Spring 2027: records incomplete by Jan. 29, 2027 -> registration hold.\",\"Fall 2026 deadline was Sept. 11, 2026.\",\"If a hold is placed, complete the missing immunizations/TB screening with USC Student Health to reverse it.\"],\"costs\":[\"No fee to upload (none stated).\",\"Immunizations given at Student Health are billed to insurance.\"],\"fields\":[\"which requirements are still missing (MMR, varicella, MenACWY, TB)\",\"document type (records vs. provider checklist vs. lab titer)\",\"name and DOB visible, signature/stamp, English translation\",\"date fields entered in MySHR\",\"applicable deadline (Jan. 11 / Jan. 29, 2027)\",\"whether an exemption is being requested\"],\"sources\":[{\"url\":\"https://studenthealth.usc.edu/myshr/\",\"title\":\"MySHR Quickstart Guide - USC Student Health\"},{\"url\":\"https://sites.usc.edu/new-student-health-requirements/immunizations/faq-multi-lingual/\",\"title\":\"FAQ (Multi-lingual) - Health Requirements for Students\"},{\"url\":\"https://sites.usc.edu/new-student-health-requirements/immunizations/uploading-vaccination-records/\",\"title\":\"Uploading Vaccination Records - Health Requirements for Students\"},{\"url\":\"https://sites.usc.edu/new-student-health-requirements/immunizations/\",\"title\":\"Required Immunizations - Health Requirements for Students\"}]},{\"id\":\"register-osas-request-accommodation-letters\",\"topic\":\"07\",\"name\":\"Register with OSAS and request accommodation letters\",\"desc\":\"Student with a disability (or temporary condition) wants academic accommodations and needs Accommodation Letters for their professors.\",\"system\":\"MyOSAS portal (Online Student Application and My Dashboard) - Office of Student Accessibility Services, GFS 120, (213) 740-0776\",\"steps\":[\"Complete the OSAS Online Student Application in MyOSAS, answering every field as thoroughly as possible.\",\"On the next screen, upload disability-related documentation (or later: re-access the upload page, email your OSAS Specialist, or bring it to the front desk at GFS 120).\",\"Meet with your assigned OSAS Specialist (in person, phone or video).\",\"Wait for the OSAS Documentation Review decision; your Specialist emails the outcome and MyOSAS is updated with approved accommodations.\",\"Each semester: log in to MyOSAS > My Dashboard, select your classes, click \\\"Continue to Customize Your Accommodations,\\\" choose accommodations per class, and click \\\"Submit Your Accommodation Requests\\\" (look for \\\"System Update Is Successful\\\").\",\"If a class shows \\\"Processing,\\\" your Specialist must approve manually (you can email them); when \\\"Approved,\\\" download the PDF letter.\",\"Deliver each letter to your professor (in person or email) and confirm receipt; some graduate programs use a specific contact for letters.\",\"For additional accommodations later, use \\\"Additional Accommodation request\\\" in MyOSAS.\"],\"req\":[\"Documentation from a qualified evaluator (licensed health care professional; family members not accepted), in English or professionally translated.\",\"Documentation should address functional impacts, frequency/duration/severity, and treatment; provider recommendations are not binding.\",\"Students lead the process and communications; support persons attend only as an approved accommodation.\",\"Accommodations are not retroactive and letters must be generated and sent every semester (MyOSAS does not send them).\"],\"deadlines\":[\"Fall 2026: new or additional accommodation requests by Wed. Nov. 11, 2026, 11:59 PM PT (non-Gould).\",\"Fall 2026: accommodation letters to faculty by Wed. Nov. 25, 2026, 11:59 PM PT (non-Gould).\",\"Gould Law: approved letters to Gould Student Life by Mon. Nov. 16, 2026, 5 PM PT.\",\"Reviews may take three weeks or longer; registration is open any time.\"],\"costs\":[\"None stated (no OSAS fee mentioned on USC sites).\"],\"fields\":[\"condition and documentation available (provider, date, functional impacts)\",\"accommodations being requested\",\"courses this semester for letters\",\"which approved accommodations to apply to each course\",\"program-specific letter contact (grad/Gould)\",\"relevant deadline (Nov. 11 / Nov. 25, 2026)\"],\"sources\":[{\"url\":\"https://osas.usc.edu/new-students/when-how-to-register/\",\"title\":\"When & How to Register - Office of Student Accessibility Services\"},{\"url\":\"https://osas.usc.edu/current-students/accommodation-information/\",\"title\":\"Accommodation Information - Office of Student Accessibility Services\"},{\"url\":\"https://osas.usc.edu/new-students/documentation-guidelines-forms/\",\"title\":\"Documentation Guidelines & Forms - Office of Student Accessibility Services\"},{\"url\":\"https://osas.usc.edu/\",\"title\":\"USC Office of Student Accessibility Services\"}]},{\"id\":\"schedule-osas-testing-center-exam\",\"topic\":\"07\",\"name\":\"Schedule an exam at the OSAS Testing Center\",\"desc\":\"Student approved for testing accommodations wants to book a midterm, quiz, final, make-up or Incomplete exam at the OSAS Testing Center (SSL 301).\",\"system\":\"MyOSAS portal > Accommodated Testing > Schedule Exam (OSAS Testing Center, SSL 301, (213) 821-9620, OSASTestingServices@usc.edu)\",\"steps\":[\"Generate your Accommodation Letter for the course in MyOSAS and provide it to your professor (required before an exam request).\",\"Log in to MyOSAS; from \\\"My Dashboard\\\" click \\\"Accommodated Testing.\\\"\",\"Select the course from the drop-down menu and click the \\\"Schedule Exam\\\" tab.\",\"On the Exam Request page, complete \\\"Exam Detail\\\" (enter the standard exam length in minutes) and \\\"Terms and Conditions,\\\" then click \\\"Add Exam Request.\\\"\",\"Confirm the \\\"System Update is Successful\\\" notice and the confirmation email; the request is pending until your instructor approves it and submits exam details.\",\"On exam day, check in at SSL 301 15 minutes early; store belongings in the provided locker.\",\"For Incomplete-course or foreign language placement exams, email OSASTestingServices@usc.edu with the required details instead.\"],\"req\":[\"Approved testing accommodations; eligible program (Testing Center does not proctor HSC/Alhambra programs, online programs, or Gould Law).\",\"Schedule at the same time as the class unless accommodations create an overlap with another class or the class falls outside proctoring hours (Mon-Fri 9 AM-5 PM; 8 AM-6 PM during finals).\",\"Alternative times must be approved by the instructor; personal/work/travel schedules are not disability-related reasons.\",\"One capped drink and one small snack allowed; AI/smart glasses not permitted.\"],\"deadlines\":[\"Submit at least one week before the exam date (later requests only as time and space allow).\",\"Fall 2026 finals: by 11:59 PM PT Wed. Dec. 2, 2026 (also the deadline for make-up and Incomplete exams).\",\"Spring 2027 finals: by 11:59 PM PT Wed. Apr. 28, 2027.\",\"Foreign language placement exams: contact the Testing Center at least two weeks ahead.\"],\"costs\":[\"None stated.\"],\"fields\":[\"course and section\",\"exam date and class start time\",\"standard exam length (minutes)\",\"approved testing accommodations (e.g., 1.5x, reduced distraction)\",\"letter already sent to professor\",\"any overlap with other classes/finals or time outside Testing Center hours\",\"instructor approval for any alternate time\"],\"sources\":[{\"url\":\"https://osas.usc.edu/current-students/accommodated-testing/\",\"title\":\"Accommodated Testing - Office of Student Accessibility Services\"},{\"url\":\"https://osas.usc.edu/\",\"title\":\"USC Office of Student Accessibility Services\"}]},{\"id\":\"submit-tc4t-report\",\"topic\":\"07\",\"name\":\"Submit a Trojans Care 4 Trojans (TC4T) report\",\"desc\":\"Student (or parent/faculty) is worried about another Trojan and wants Campus Support & Intervention to reach out.\",\"system\":\"TC4T online form (linked from campussupport.usc.edu/tc4t) or Campus Support & Intervention phone 213-740-0411 / uscsupport@usc.edu\",\"steps\":[\"If anyone is in immediate danger, call DPS (213-740-4321) or 911; for mental health crisis call 213-740-9355 (24/7) instead of TC4T.\",\"Go to campussupport.usc.edu/tc4t and open the TC4T form (\\\"Submit a concern\\\").\",\"Describe the person of concern and what you have observed (the form can be private and anonymous).\",\"Submit; a Campus Support & Intervention staff member reviews each submission and reaches out to the person of concern.\",\"Or call 213-740-0411 during business hours to speak with a team member.\",\"If the concern involves sexual or gender-based harm, contact CARE-SC (213-740-9355) for confidential help or OCRC (213-740-5086) to report.\"],\"req\":[\"Concern about a USC student, colleague or staff member experiencing personal difficulties.\",\"CSI is not an emergency resource and is not available 24/7.\",\"Faculty/staff reporting about a student should first review the Faculty & Staff Report a Concern page.\"],\"deadlines\":[\"No deadline; phone line during business hours; email replies within one business day.\"],\"costs\":[\"None stated.\"],\"fields\":[\"name/identifying details of the person of concern (if known)\",\"what was observed and when\",\"immediate safety risk (route to DPS/911/213-740-9355)\",\"whether the reporter wants to remain anonymous or be contacted\",\"whether sexual/gender-based harm is involved (CARE-SC/OCRC)\"],\"sources\":[{\"url\":\"https://campussupport.usc.edu/tc4t/\",\"title\":\"TC4T - Campus Support & Intervention\"},{\"url\":\"https://campussupport.usc.edu/\",\"title\":\"Campus Support and Intervention\"},{\"url\":\"https://studenthealth.usc.edu/emergencies/\",\"title\":\"Urgent Matters - USC Student Health\"}]},{\"id\":\"get-trojan-food-pantry-access\",\"topic\":\"07\",\"name\":\"Get Trojan Food Pantry access\",\"desc\":\"Student experiencing food insecurity wants free supplemental groceries from the Trojan Food Pantry.\",\"system\":\"Student Basic Needs - Trojan Food Pantry intake form (Qualtrics, linked on studentbasicneeds.usc.edu) and USCard card-swipe check-in at King Hall (KOH) Suite 103\",\"steps\":[\"Confirm eligibility: enrolled this term, no active dining hall meal plan (or 20 or fewer meals remaining), and experiencing food insecurity.\",\"Complete the Trojan Food Pantry intake form (once per semester) from the Trojan Food Pantry page.\",\"Take a screenshot of the completed intake form.\",\"Visit KOH Suite 103 during posted hours (fall/spring: Tue, Wed, Thu 10 AM-2 PM) with your physical USCard and a reusable bag.\",\"Show the intake-form screenshot on your first visit each term; swipe your USCard at every visit.\"],\"req\":[\"Must be enrolled at USC during the term of support.\",\"No active dining hall meal plan (students with 20 or fewer remaining meals may be considered).\",\"Must be experiencing food insecurity.\",\"Physical USCard required every visit; no picking up groceries for friends.\",\"Limited amount of groceries per week (supplemental, not a primary food source).\"],\"deadlines\":[\"Intake form: once per semester.\",\"Fall/Spring: about 15 weeks from the first week of classes through Classes End week; Summer: first week of June through last week of July (Wednesdays 11 AM-2 PM).\"],\"costs\":[\"Free (no cost stated).\"],\"fields\":[\"current enrollment term\",\"meal plan status / remaining meals\",\"intake form completed this semester\",\"visit day/time within posted hours\",\"has physical USCard\"],\"sources\":[{\"url\":\"https://studentbasicneeds.usc.edu/programs-and-services/food-support/trojan-food-pantry/\",\"title\":\"Trojan Food Pantry - Student Basic Needs\"}]},{\"id\":\"request-health-leave-of-absence\",\"topic\":\"07\",\"name\":\"Request a health leave of absence\",\"desc\":\"Student needs to step away from classes for medical or mental health treatment and wants a formal Health Leave (or Health Deferral in the first semester).\",\"system\":\"Campus Support & Intervention Health Leave Team (Voluntary Health Leave of Absence Request Form, Provider Health Leave of Absence Form, Calendly appointment); vhla@usc.edu, 213-740-0411\",\"steps\":[\"Complete the Voluntary Health Leave of Absence Request Form.\",\"Have your healthcare provider complete the Provider Health Leave of Absence Form and submit it.\",\"Schedule an appointment with a member of the Health Leave Team (separate scheduling links for undergrad/master's/professional doctorate vs. PhD).\",\"Undergraduates: also complete the Undergraduate Leave of Absence Form.\",\"PhD students: your academic program/unit creates an Academic Plan with you.\",\"Schedule a Health Leave Confirmation Appointment with your assigned Health Leave Coordinator to review forms and create your individualized plan.\",\"International students: work with OIS on the International Student Medical Leave of Absence process in parallel.\",\"Check in with academic advisor, Financial Aid, Housing, Registrar/TRI and the Student Health Insurance Office about impacts.\"],\"req\":[\"Available to undergraduate, master's, professional doctorate and PhD students. First-semester students request a Health Deferral through the Health Leave Team; first-semester graduate students leaving before week 12 use the regular process and also request an OSAS Health Deferral accommodation.\",\"Health leaves cannot be granted retroactively.\",\"International students must meet with OIS before finalizing plans.\"],\"deadlines\":[\"May apply up to the last day of classes (per Schedule of Classes).\",\"Return windows: Spring Oct. 1-31; Summer Mar. 1-31; Fall May 18-Jun. 30 (firm deadlines).\"],\"costs\":[\"No Health Leave fee stated.\",\"Tuition: full refund if withdrawn during add/drop; weeks 3-7 refund only via Tuition Refund Insurance; W marks after week 7 (no GPA impact).\",\"May be eligible for one semester of Leave of Absence Health Insurance (cost not stated).\"],\"fields\":[\"student level (undergrad/master's/PhD) and first-semester status\",\"international status (OIS)\",\"current week of semester (refund/W implications)\",\"provider form status\",\"housing, financial aid and insurance impacts\",\"intended return term and its deadline\"],\"sources\":[{\"url\":\"https://campussupport.usc.edu/health-leave/\",\"title\":\"Health Leave - Campus Support & Intervention\"},{\"url\":\"https://campussupport.usc.edu/health-leave/frequently-asked-questions/\",\"title\":\"Health Leave Frequently Asked Questions - Campus Support & Intervention\"}]},{\"id\":\"request-medical-records\",\"topic\":\"07\",\"name\":\"Request Student Health medical records\",\"desc\":\"Student wants copies of their USC Student Health records (e.g., immunization history, visit notes) for themselves or another provider.\",\"system\":\"USC Student Health Health Information Management (HIM): eshchim@usc.edu, fax 213-740-4961, or in person at 1031 W. 34th St., Suite LL-106\",\"steps\":[\"Complete the Authorization for Disclosure of Medical Information (Release of Information) form.\",\"Attach a copy of a government-issued ID.\",\"Submit by email to eshchim@usc.edu (clear photos or scans), by fax to 213-740-4961, or in person at 1031 West 34th Street, Suite LL-106.\",\"If delivered by secure email, open and download the records within 14 days before the link expires.\",\"For routine items (e.g., lab results), check MySHR > Medical Records first.\"],\"req\":[\"Written authorization with government-issued ID required.\",\"Email delivery carries stated privacy risks; choose another method if concerned.\"],\"deadlines\":[\"Secure email with records expires within 14 days; processing time not stated on USC sites.\"],\"costs\":[\"Copies: \\\"a reasonable fee for copies\\\" plus postage if mailed, per the privacy notice (exact amount not stated).\"],\"fields\":[\"which records and date range\",\"recipient (self or another provider) and delivery method\",\"government ID attached\",\"signed authorization form\"],\"sources\":[{\"url\":\"https://studenthealth.usc.edu/requesting-medical-records/\",\"title\":\"Requesting Medical Records - USC Student Health\"},{\"url\":\"https://studenthealth.usc.edu/patient-privacy-and-confidentiality/\",\"title\":\"Patient Privacy and Confidentiality - USC Student Health\"}]},{\"id\":\"book-sti-testing\",\"topic\":\"07\",\"name\":\"Book self-directed STI testing\",\"desc\":\"Student without symptoms wants STI/HIV testing without a full medical visit.\",\"system\":\"MySHR patient portal - appointment category \\\"STI Testing\\\", then USC Student Health lab services\",\"steps\":[\"If you have symptoms, book a clinician visit instead; if related to sexual assault, ask for a Confidential Advocate (213-740-9355).\",\"Log in to MySHR and select \\\"STI Testing\\\" under the appointment category.\",\"Choose tests as recommended (chlamydia and gonorrhea by urine; syphilis and HIV by blood draw).\",\"Go to lab services at your appointment time.\",\"View results in MySHR (secure portal); your provider can prescribe treatment and expedited partner therapy if positive.\"],\"req\":[\"Must be participating in the Student Health Fee.\",\"Self-directed testing is for students without symptoms.\"],\"deadlines\":[\"None (book any time).\",\"The USG/GSG no-out-of-pocket-cost campaign for non-SHIP students ran Feb. 9-Apr. 4, 2026; future dates not stated on USC sites.\"],\"costs\":[\"SHIP/Aetna: STI testing covered 100% at Tier 1/2 with no deductible (USC Student Health is Tier 1).\",\"HIV testing: no out-of-pocket cost for all students.\",\"Out-of-pocket option (to keep tests off a family plan): $30.62 chlamydia/gonorrhea panel, $9.12 HIV, $3.05 syphilis.\"],\"fields\":[\"whether the student has symptoms\",\"tests requested\",\"insurance (SHIP vs. family plan) and whether to pay out of pocket for privacy\",\"campus/lab and appointment time\"],\"sources\":[{\"url\":\"https://sites.usc.edu/sexandhealth/sti-testing-campaign-no-out-of-pocket-cost/\",\"title\":\"STI Testing Campaign: No \\\"Out of Pocket\\\" Cost! - Sex and Health\"},{\"url\":\"https://sites.usc.edu/sexandhealth/services/sti-testing/\",\"title\":\"STI Testing - Sex and Health: Info for Students\"},{\"url\":\"https://sites.usc.edu/sexandhealth/services/confidentiality/\",\"title\":\"Confidentiality - Sex and Health: Info for Students\"}]},{\"id\":\"contact-confidential-advocate\",\"topic\":\"07\",\"name\":\"Connect with a CARE-SC confidential advocate\",\"desc\":\"Student affected by sexual assault, relationship violence, stalking or other gender/power-based harm wants confidential support, medical/forensic options, or transportation to a SART center.\",\"system\":\"CARE-SC (Confidential Advocates, Resources, and Education Support Center) via 213-740-9355 (WELL) 24/7, or MySHR secure message / appointment\",\"steps\":[\"If in immediate danger, call 911; if injured, go to the nearest hospital.\",\"Call 213-740-9355 (24/7) and say \\\"I need an advocate.\\\"\",\"Or, for non-emergencies, send a Secure Message to an advocate in MySHR (\\\"Messages\\\") or book an advocate appointment in MySHR.\",\"Discuss medical care, SART/forensic exam options (within 120 hours), reporting options, and aftercare (counseling, academic accommodations).\",\"If you choose a forensic exam, the advocate can arrange free Lyft transportation and accompany you.\"],\"req\":[\"Available to all USC students of all genders, 24/7.\",\"Advocates are confidential resources (no report to campus authorities or police required).\"],\"deadlines\":[\"SART/forensic exam must be done within 120 hours (5 days) of the assault.\"],\"costs\":[\"Advocate services: no cost (covered through the Student Health Fee).\",\"Forensic exams: free, no billing to insurance.\"],\"fields\":[\"immediate safety\",\"whether medical care or a forensic exam is wanted and time since incident\",\"preferred contact method (call vs. secure message)\",\"transportation/accompaniment needs\"],\"sources\":[{\"url\":\"https://sites.usc.edu/clientservices/\",\"title\":\"Building a Culture of Consent: CARE-SC\"},{\"url\":\"https://sites.usc.edu/clientservices/contact/\",\"title\":\"Contact - CARE-SC\"},{\"url\":\"https://sites.usc.edu/clientservices/seek-care/sart-forensic-exams/\",\"title\":\"SART/Forensic Exams - CARE-SC\"},{\"url\":\"https://sites.usc.edu/clientservices/talk-to-an-advocate/what-are-advocates/\",\"title\":\"What are Confidential Advocates? - CARE-SC\"}]},{\"id\":\"request-assistance-animal\",\"topic\":\"07\",\"name\":\"Request an assistance (emotional support) animal in USC housing\",\"desc\":\"Student living (or planning to live) in USC Housing wants approval for an emotional support/assistance animal.\",\"system\":\"Office of Student Accessibility Services (MyOSAS application + documentation), with Residential Education and USC Housing\",\"steps\":[\"Register with OSAS (Online Student Application) if not already registered.\",\"Submit an assistance animal request with supporting documentation to OSAS before bringing the animal to campus - ideally well before housing placement.\",\"If approved, meet in person with your OSAS Specialist to review and sign the Assistance Animal Agreement.\",\"Meet with Residential Education staff and your roommate(s) to complete a Roommate Agreement before the animal arrives.\",\"Give Residential Education a copy of your Letter of Accommodation showing OSAS approval.\"],\"req\":[\"Must live (or plan to live) in University Housing; animal allowed only in the residential setting.\",\"Animal must meet health/behavior standards (vaccinations, spay/neuter); animals too young to be vaccinated or spayed/neutered generally are not eligible.\",\"Student is responsible for care, control, damages and any removal/boarding costs.\"],\"deadlines\":[\"Before bringing the animal to campus; no specific date stated.\"],\"costs\":[\"No OSAS fee stated; student pays for damages and any removal/boarding costs.\"],\"fields\":[\"housing assignment/term\",\"documentation of the disability-related need\",\"animal type, age, vaccination and spay/neuter status\",\"roommate agreement status\"],\"sources\":[{\"url\":\"https://osas.usc.edu/current-students/accommodation-information/animals-on-campus/\",\"title\":\"Animals on Campus - Office of Student Accessibility Services\"},{\"url\":\"https://osas.usc.edu/new-students/when-how-to-register/\",\"title\":\"When & How to Register - Office of Student Accessibility Services\"}]},{\"id\":\"purchase-parking-permit\",\"topic\":\"08\",\"name\":\"Purchase a parking permit\",\"desc\":\"Buy or renew a semester student parking permit (e.g., for Spring 2027) for a UPC or HSC structure or lot.\",\"system\":\"USC Transportation AIMS parking portal (usc.aimsparking.com); USC Transportation customer service centers (UPC McCarthy Structure, HSC KAM-120)\",\"steps\":[\"Check FY27 prices and pick a location/permit type on the Parking Rates page (Gold, Cardinal, Off-Campus Student Housing, Evening, Motorcycle).\",\"Go to https://usc.aimsparking.com, click 'Login', and sign in with your USC (Shibboleth) credentials.\",\"Click the 'Order Permits' box at the bottom of the home screen.\",\"Choose from the permits offered (options are based on your academic unit; to buy at the other campus, call UPC 213-740-3575 or HSC 323-442-1201).\",\"Link a vehicle (only one vehicle per permit). No car yet: enter your ten-digit USCID as the plate, choose 'Pending' as the state, fill any year/make/model/color, and make a permanent vehicle change in AIMS once you have the car.\",\"Add the permit to your cart, confirm your email, and check out. Student purchases default to the USC fee bill; for another payment method visit a customer service center (UPC McCarthy Structure, HSC KAM-120).\",\"If your location is full, join its waiting list if one is offered, and consider buying at another location with space while you wait.\",\"Fall 2026 permit holders: act on the renewal email sent mid- to late November (permits do not renew automatically).\"],\"req\":[\"Must be registered for classes or admitted for Spring 2027 so your USCID/student account imports from SIS into AIMS.\",\"Student permits are not available to guest accounts.\",\"Only one vehicle may be linked to a permit; the license plate is the permit (paperless since July 2025) and enforcement uses license plate recognition.\",\"Locations are sold first come, first served; waiting lists are not guaranteed to clear.\",\"Any motor-powered vehicle parked on campus needs a permit; university-owned housing lots need a permit for that lot.\"],\"deadlines\":[\"Spring 2027 student permits go on sale online Monday, January 4 (2027) at noon.\",\"Fall 2026 permit holders receive renewal invitations by email mid- to late November 2026; contact auxtrans@usc.edu after December 1 if none arrives.\",\"Cancellations: online cancellation form, processed within about one business day; no prorated refunds in the final month of a semester.\"],\"costs\":[\"FY27 per semester (students): UPC Gold $612; UPC Cardinal $477; UPC Off-Campus Student Housing $432; HSC Gold $612; HSC Cardinal $477; Evening (5:00pm-7:00am) $306; Motorcycle $108; Carpool Gold $477 (separate application).\",\"Online orders add a $5 transaction fee; rates include the 10% City of Los Angeles Parking Occupancy Tax; rates subject to change.\",\"EV discount of $30/month available on Gold-tier permits via the EV discount form (applied after the semester).\"],\"fields\":[\"campus (UPC or HSC)\",\"permit type and location\",\"term (e.g., Spring 2027)\",\"total price including $5 online fee\",\"license plate to link (or USCID placeholder)\",\"payment method (USC fee bill by default)\",\"waitlist preference if location is full\"],\"sources\":[{\"url\":\"https://transnet.usc.edu/index.php/how-to-purchase-a-permit-2/\",\"title\":\"How to Purchase a Permit - USC Transportation\"},{\"url\":\"https://transnet.usc.edu/wp-content/uploads/2026/10/SPRING-2027-STUDENT-PARKING-PERMIT-REGISTRATION-GUIDE.pdf\",\"title\":\"Spring 2027 Student Parking Permit Registration Guide (PDF)\"},{\"url\":\"https://transnet.usc.edu/index.php/parking-rates/\",\"title\":\"Parking Rates - USC Transportation\"},{\"url\":\"https://transnet.usc.edu/index.php/faqs/?faq_category=22\",\"title\":\"Permits FAQs - USC Transportation\"}]},{\"id\":\"request-lyft-ride-or-safety-escort\",\"topic\":\"08\",\"name\":\"Request a free USC Lyft ride or a safety escort\",\"desc\":\"Get a free late-night ride home inside the campus boundary, or an escort when Lyft isn't running.\",\"system\":\"USC Lyft Rides Program in the Lyft app (managed by USC Transportation); USC Department of Public Safety for escorts (blue light emergency phones; DPS UPC non-emergency 213-740-6000)\",\"steps\":[\"Open the Lyft app and confirm the 'USC Lyft Rides' pass ('HSC USC Rides' at HSC) appears in the Payment section; if not, complete the Lyft Invite form on USC Transportation's Lyft page.\",\"During program hours (UPC 7:00pm-2:00am daily; HSC 5:00pm-2:00am Mon-Fri), enter a pickup and drop-off that are both inside the USC geofence.\",\"Choose a Shared ride (not scheduled, priority, or LUX); if you also have Lyft Business, switch to PERSONAL mode.\",\"Confirm the fare quote says FREE before requesting.\",\"Verify the driver's photo, name, license plate and car before getting in; don't add stops, and get in and out inside the geofence.\",\"After the ride, check for a $0.00 receipt; send program feedback to auxtrans@usc.edu (disputes and claims are resolved directly with Lyft).\",\"Need an escort (e.g., 2:00am-6:00am when Lyft is unavailable)? Use a blue light emergency phone (they can be used to request an escort) or call DPS; DPS may be able to provide an escort within the designated boundaries.\"],\"req\":[\"Current USC students, faculty and staff only.\",\"UPC rides must stay within the area east of Normandie Ave, south of Washington Blvd, west of Main St, and north of Martin Luther King Jr. Blvd; HSC rides within the HSC boundary (including to/from Union Station).\",\"Rides between campuses, rides beginning or ending outside the geofence, scheduled rides, priority pickups, LUX rides and added stops are not covered.\",\"Program runs on monthly credits; maximum monthly benefit is $1,000.\",\"Invites are unique and must not be shared.\"],\"deadlines\":[\"UPC: 7:00pm-2:00am, seven days a week; HSC: 5:00pm-2:00am, Monday-Friday.\",\"Fall home football game days: UPC program begins 5 hours after scheduled kickoff or normal program hours, whichever is later.\",\"Hours may change for holidays, home football games and special periods such as finals week.\"],\"costs\":[\"Free when the ride qualifies (fare quote shows FREE; $0.00 receipt).\",\"Not covered by USC: tips, PrimeTime upcharges, cancellation fees, scheduled rides, added stops.\",\"Lyft cancellation fee of $5 (Lyft has agreed to waive it if you cancel because you did not feel safe and request it through Lyft's in-app support).\"],\"fields\":[\"campus (UPC or HSC)\",\"pickup location (inside geofence)\",\"drop-off location (inside geofence)\",\"current time vs. program hours\",\"ride type = Shared / Personal mode\",\"USC Lyft pass visible in Payment\",\"for escorts: current location and a phone number DPS can reach\"],\"sources\":[{\"url\":\"https://transnet.usc.edu/index.php/how-to-use-lyft/\",\"title\":\"USC Lyft Rides Program - USC Transportation\"},{\"url\":\"https://dps.usc.edu/services/lyft-rides-program/\",\"title\":\"Lyft Rides Program - Department of Public Safety\"},{\"url\":\"https://dps.usc.edu/services/blue-light-phones/\",\"title\":\"Emergency Blue Light Phones - Department of Public Safety\"},{\"url\":\"https://dps.usc.edu/contact/\",\"title\":\"Contact - Department of Public Safety\"}]},{\"id\":\"sign-up-trojansalert\",\"topic\":\"08\",\"name\":\"Sign up for TrojansAlert\",\"desc\":\"Make sure you (or your family) receive USC emergency text and email alerts.\",\"system\":\"TrojansAlert emergency notification system (DPS); text sign-up via Nixle (888777) for non-affiliates; Experience USC for student contact information; Workday for faculty/staff\",\"steps\":[\"Current students: no sign-up needed - you are automatically enrolled.\",\"Keep your contact information current; USC guidance says students update contact information in Experience USC.\",\"Parents, family, alumni and community members: text the word 'TrojansAlert' to 888777.\",\"Non-affiliates must re-subscribe every year starting Aug. 15, when the list is reset.\",\"Faculty/staff: add your cell in Workday under the 'USC Emergency/Safety Alerts' phone type (Personal Information > Change Contact Information).\"],\"req\":[\"Students, faculty and staff are automatically enrolled; everyone else must sign up annually.\",\"Faculty and staff receive texts only if their cell is saved as the USC Emergency/Safety Alerts phone type in Workday.\"],\"deadlines\":[\"Non-affiliate subscriber list resets each Aug. 15; resubscribe starting Aug. 15.\"],\"costs\":[\"askUSC describes TrojansAlert as free; no fees stated.\"],\"fields\":[\"are you a current student, employee, or parent/other\",\"phone number to receive texts\",\"email address on file\",\"whether contact info in Experience USC is current\"],\"sources\":[{\"url\":\"https://dps.usc.edu/services/trojans-alerts/\",\"title\":\"TrojansAlert - Department of Public Safety\"},{\"url\":\"https://safety.usc.edu/storms/\",\"title\":\"Preparing for Winter Storms and Potential Flooding - ONE USC Safety\"},{\"url\":\"https://ask.usc.edu/s/article/000002171\",\"title\":\"What do I need to know about campus safety? (askUSC)\"}]},{\"id\":\"report-lost-item-lost-and-found\",\"topic\":\"08\",\"name\":\"Report a lost item / check lost and found\",\"desc\":\"Find out whether DPS has an item you lost on campus, or turn in something you found.\",\"system\":\"USC Department of Public Safety centralized Lost and Found\",\"steps\":[\"UPC: call 213-740-9759 or email lostandfound@dps.usc.edu about the item you lost.\",\"HSC: call 323-442-1200.\",\"To turn in a found item, drop it off at DPS: 3667 McClintock Ave (UPC) or 2001 Soto Street (HSC).\",\"If the item was stolen rather than lost, report the crime to DPS (UPC 213-740-4321, HSC 323-442-1000).\"],\"req\":[\"DPS keeps found items for 90 days from the date DPS receives them.\"],\"deadlines\":[\"Found items held 90 days from receipt by DPS.\"],\"costs\":[\"none stated\"],\"fields\":[\"item description (brand, color, identifying marks)\",\"where and when it was lost\",\"campus (UPC or HSC)\",\"student's contact phone/email\"],\"sources\":[{\"url\":\"https://dps.usc.edu/services/lost-and-found/\",\"title\":\"Lost and Found - Department of Public Safety\"},{\"url\":\"https://dps.usc.edu/contact/report/\",\"title\":\"Report a Crime - Department of Public Safety\"}]},{\"id\":\"register-bicycle\",\"topic\":\"08\",\"name\":\"Register a bicycle (or scooter/skateboard) with DPS\",\"desc\":\"Register a bike, scooter or skateboard so DPS can identify it if it's lost, stolen, recovered or impounded.\",\"system\":\"DPS online Bicycle, Scooter, and Skateboard Registration form (dpswebapp.usc.edu/bikeRegistration) and DPS office at Parking Structure A (PSA) for decals\",\"steps\":[\"Find the serial number (the majority are under the bottom bracket where the pedal cranks meet; otherwise check the front headset or rear stays).\",\"Complete DPS's online registration form before visiting DPS (new submissions can take up to 30 minutes to process).\",\"Print the automated email receipt (keep a second copy for your records).\",\"Bring the receipt to the DPS office at Parking Structure A (PSA) to pick up your registration decal.\",\"Apply the decal to the frame where it is visible.\",\"No serial number? Bring the bike to the DPS station in PSA; DPS can provide tools to engrave your driver's license number on the frame.\"],\"req\":[\"DPS's registration page says that per USC policy, faculty, staff and students who ride or park a bike on campus need to register it with DPS (the 2026-27 Student Handbook calls registration 'highly recommended').\",\"Students may also register scooters and skateboards.\",\"The serial number recorded must be the actual serial number, not the brand or model.\"],\"deadlines\":[\"none stated (register before riding/parking on campus; allow up to 30 minutes for the online submission to process before picking up the decal)\"],\"costs\":[\"Free - there is no cost for the registration.\"],\"fields\":[\"device type (bike, scooter, skateboard)\",\"serial number\",\"make, model and color\",\"owner's name, USC ID and email\",\"when the student will pick up the decal at PSA\"],\"sources\":[{\"url\":\"https://dps.usc.edu/services/bikes/\",\"title\":\"Bicycle, Scooter, and Skateboard Registration - Department of Public Safety\"},{\"url\":\"https://dps.usc.edu/services/bikeserialnumber/\",\"title\":\"Locating your Bicycle Serial Number - Department of Public Safety\"},{\"url\":\"https://oec.usc.edu/wp-content/uploads/2026/08/Student-Handbook-2026-August-25-002.pdf\",\"title\":\"USC Student Handbook 2026-2027 (PDF), effective July 2026\"}]},{\"id\":\"file-ocrc-report\",\"topic\":\"08\",\"name\":\"File a report with the Office of Civil Rights Compliance (OCRC)\",\"desc\":\"Report discrimination, harassment, sexual misconduct (Title IX) or retaliation, and get supportive measures.\",\"system\":\"USC Report & Response (report.usc.edu; 213-740-2500 or 800-348-7454, 24/7) or OCRC directly (ocrc@usc.edu, 213-740-5086)\",\"steps\":[\"If you are in danger, call DPS first (UPC 213-740-4321, HSC 323-442-1000); off campus you may also dial 911.\",\"Optional first step: talk to a confidential resource (e.g., CARE-SC/Student Health, 213-740-9355, 24/7) if you're unsure about reporting.\",\"Submit a report online through USC Report & Response (you may report anonymously) or call 213-740-2500 / 800-348-7454; or contact OCRC directly (ocrc@usc.edu, 213-740-5086) in person, by mail, phone or email.\",\"Your report is reviewed and, if it falls under the Policy on Prohibited Discrimination, Harassment, and Retaliation, triaged to OCRC.\",\"OCRC emails you to offer a meeting with a care manager or deputy coordinator about resources, supportive measures and options.\",\"Decide whether to use supportive measures only, file a Formal Complaint (formal resolution), or request alternative resolution if eligible.\"],\"req\":[\"No time limit to report; but if the respondent is no longer affiliated with USC when a Formal Complaint is filed, OCRC cannot investigate under the formal process.\",\"OCRC keeps information private (need-to-know) but is not a confidential resource.\",\"Retaliation against any party or witness is prohibited; both parties may have an advisor of choice.\",\"Making a report is not the same as filing a Formal Complaint and does not necessarily lead to an investigation.\"],\"deadlines\":[\"No deadline to make a report (reports accepted at any time).\"],\"costs\":[\"Supportive measures are free of charge.\",\"University-provided hearing advisor at a sexual misconduct live hearing is free if a party has no advisor.\"],\"fields\":[\"immediate safety/emergency status\",\"whether the student wants confidential support or to make a report\",\"anonymous vs. named report\",\"type of concern (discrimination, harassment, sexual misconduct, retaliation)\",\"preferred contact method for OCRC follow-up\",\"supportive measures needed\"],\"sources\":[{\"url\":\"https://ocrc.usc.edu/support-reporting-options/\",\"title\":\"Support & Reporting Options - Office of Civil Rights Compliance\"},{\"url\":\"https://ocrc.usc.edu/about-us/frequently-asked-questions/\",\"title\":\"Frequently Asked Questions - Office of Civil Rights Compliance\"},{\"url\":\"https://ocrc.usc.edu/about-us/\",\"title\":\"About Us - Office of Civil Rights Compliance\"},{\"url\":\"https://ocrc.usc.edu/support-reporting-options/supportive-measures/\",\"title\":\"Supportive Measures - Office of Civil Rights Compliance\"}]},{\"id\":\"register-campus-guest\",\"topic\":\"08\",\"name\":\"Register a campus guest/visitor (after hours)\",\"desc\":\"Pre-register a friend or family member so they can enter the University Park Campus after 9 p.m.\",\"system\":\"DPS After Hours Visitor Registration form (visitor.usc.edu/visitorreg/, linked from dps.usc.edu/services/visitor-registration/)\",\"steps\":[\"Fill out the DPS visitor registration form - register guests as far in advance as possible.\",\"Tell your guest to use a designated after-hours entrance: the McCarthy and McClintock gates are open 9 p.m.-6 a.m. (see maps.usc.edu for locations).\",\"When they arrive, the registered guest checks in with security at the entrance.\",\"Guests attending a registered university event must bring ID and their ticket.\",\"If your guest is driving, they'll need to buy daily/hourly parking (Text2Park or Pay-by-Plate).\"],\"req\":[\"After 9 p.m., public access points are restricted and pre-registration of guests is required.\",\"Unregistered guests will not be allowed to enter the campus.\",\"University officials may ask anyone to show a USCard or photo ID at any time.\"],\"deadlines\":[\"Register in advance of the visit; controlled access applies 9 p.m.-6 a.m.\"],\"costs\":[\"None stated for registration. If the guest drives: $20/day (Text2Park adds a one-time $0.50 fee; Pay-by-Plate stations charge no fee).\"],\"fields\":[\"guest's full name\",\"date and arrival time\",\"entrance the guest will use (McCarthy or McClintock)\",\"host's name/USC ID and contact\",\"whether the guest will drive and need parking\"],\"sources\":[{\"url\":\"https://dps.usc.edu/services/visitor-registration/\",\"title\":\"After Hours Visitor Registration - Department of Public Safety\"},{\"url\":\"https://www.usc.edu/visit-usc/\",\"title\":\"Visit USC - USC\"},{\"url\":\"https://www.usc.edu/how-to-access-campus/\",\"title\":\"How to Access Campus - USC\"},{\"url\":\"https://transnet.usc.edu/index.php/contact-us/\",\"title\":\"Contact Us - USC Transportation\"}]},{\"id\":\"appeal-parking-citation\",\"topic\":\"08\",\"name\":\"Appeal a USC parking citation\",\"desc\":\"Contest a USC parking ticket you believe was issued in error.\",\"system\":\"USC Transportation AIMS customer portal (usc.aimsparking.com) - 'Appeal Ticket'; Citation Review Board via parkingcitations@usc.edu\",\"steps\":[\"Go to https://usc.aimsparking.com and click 'APPEAL TICKET'.\",\"Enter your citation number or license plate, then click 'APPEAL CITATION'.\",\"Complete the form once, with specific details and evidence (include the citation number).\",\"Print or save the confirmation page.\",\"A Hearing Officer reviews it within 15 business days; check status in AIMS.\",\"If you disagree with the decision, email parkingcitations@usc.edu to request Citation Review Board (CRB) review (pay the citation in full first).\"],\"req\":[\"Appeal must be submitted within 21 days of the citation issue date.\",\"Unacceptable grounds include parking illegally only briefly, inconvenience, not seeing the sign, or others doing it.\",\"CRB appeals cannot be done online and require full payment; CRB decisions are final.\"],\"deadlines\":[\"Within 21 days of citation issuance.\",\"Hearing Officer review within 15 business days.\",\"CRB review can take up to 90 days.\"],\"costs\":[\"No appeal fee stated; citations don't increase in cost while under appeal.\",\"CRB review requires paying the citation in full first (partial or full refund if the panel rules in your favor).\",\"Minimum fines range from $25 (e.g., permit not registered to vehicle) to $999 (forged permit); common violations such as no valid permit are $65.\"],\"fields\":[\"citation number\",\"license plate\",\"issue date (within 21 days?)\",\"grounds and evidence for appeal\",\"whether to escalate to CRB\"],\"sources\":[{\"url\":\"https://transnet.usc.edu/index.php/appeal-a-citation/\",\"title\":\"Appeal a Citation - USC Transportation\"},{\"url\":\"https://transnet.usc.edu/index.php/parking-violations/\",\"title\":\"Parking Violations - USC Transportation\"}]},{\"id\":\"activate-metro-u-pass\",\"topic\":\"08\",\"name\":\"Get or renew a Metro U-Pass\",\"desc\":\"Activate the free semester Metro U-Pass for unlimited LA Metro rides.\",\"system\":\"USC Transportation online U-Pass form plus LA Metro activation site; USC Transportation offices for physical cards\",\"steps\":[\"Get a USC-issued physical U-Pass card if you don't have one: UPC McCarthy Structure (M-F 8:30-3:00) or HSC KAM-120 (M-F 7:30-4:00).\",\"Complete USC Transportation's online U-Pass form (choose 'RENEWAL' if you already have a USC-issued U-Pass).\",\"Open the confirmation email and click the LA Metro activation link.\",\"Enter your 20-digit card number and the semester activation code (SCFA26 for Fall 2026), check the acknowledgement box, and submit.\",\"Wait 24 hours, then tap the card at any LA Metro station or bus within 14 days to lock in the activation.\"],\"req\":[\"Available to all current USC students (graduate and undergraduate).\",\"Must re-register every semester; you keep the same card.\",\"A physical card issued by USC is required.\",\"Not valid on Metrolink, Amtrak or LAX FlyAway buses.\"],\"deadlines\":[\"Fall 2026 program began August 17, 2026 and runs through the beginning of January.\",\"Tap within 14 days of activation.\"],\"costs\":[\"No additional cost (included in the Transportation Fee charged to registered students).\"],\"fields\":[\"new card vs. renewal\",\"20-digit card number\",\"current semester's activation code (the page lists SCFA26 for Fall 2026; a Spring 2027 code was not yet posted)\",\"campus office for card pickup if needed\"],\"sources\":[{\"url\":\"https://transnet.usc.edu/index.php/student-u-pass/\",\"title\":\"USC Student U-Pass Program - USC Transportation\"}]},{\"id\":\"cancel-parking-permit\",\"topic\":\"08\",\"name\":\"Cancel a parking permit\",\"desc\":\"Cancel a semester parking permit you no longer need and get a prorated refund where eligible.\",\"system\":\"USC Transportation online permit cancellation form (linked from How to Purchase a Permit)\",\"steps\":[\"Decide the date you actually want the permit canceled (future-dated requests aren't accepted).\",\"On that date, complete USC Transportation's online permit cancellation form.\",\"Allow about one business day for processing; any prorated refund is based on the cancellation date.\"],\"req\":[\"The online cancellation form is the only way to cancel.\",\"No prorated refunds during the final month of a semester.\",\"Permits returned after the start date are not eligible for a full refund.\",\"Canceling mid-semester makes you ineligible for that semester's EV discount.\"],\"deadlines\":[\"Processed typically within one business day of submission.\"],\"costs\":[\"Refund is prorated by cancellation date (none in a semester's final month); no cancellation fee stated.\"],\"fields\":[\"permit to cancel\",\"desired cancellation date (today)\",\"refund expectation (prorated / final-month rule)\",\"any EV discount impact\"],\"sources\":[{\"url\":\"https://transnet.usc.edu/index.php/how-to-purchase-a-permit-2/\",\"title\":\"How to Purchase a Permit - USC Transportation\"},{\"url\":\"https://transnet.usc.edu/index.php/ev-program/\",\"title\":\"EV Program - USC Transportation\"}]},{\"id\":\"reserve-space-and-submit-uepa\",\"topic\":\"08\",\"name\":\"Reserve space and submit a UEPA for a demonstration or event\",\"desc\":\"Get approval to hold a demonstration, vigil or other outdoor expressive event on campus.\",\"system\":\"Trojan Event Services (trojanevents.usc.edu, 213-764-4943) for space; University Event Permit Application (UEPA) via DPS's 'USC Events Permit Application' page (dps.usc.edu/services/usc-events-permit-application/), which links to the online Event Permit Application\",\"steps\":[\"Submit a space reservation request to Trojan Event Services (HSC or non-TES venues are referred to the school or building manager).\",\"Wait for written confirmation before advertising.\",\"Submit the University Event Permit Application (UEPA) at least three weeks before the event.\",\"Follow up with each department listed in the UEPA receipt email to secure approvals; print the submitted form as proof of registration.\",\"Plan to follow time, place and manner rules (no tents, no unapproved amplified sound, no postings on USC property, no weaponizable signs).\"],\"req\":[\"Reservations are first come, first served; space isn't guaranteed.\",\"Late UEPAs considered only if the need couldn't be anticipated, it won't interfere with other events, and it's submitted early enough (typically at least 48 hours).\",\"The UEPA is a request for approval, not a space request, and doesn't replace venue reservations.\"],\"deadlines\":[\"Space requests generally 3-6 weeks in advance.\",\"UEPA at least three weeks before the event (exception: typically at least 48 hours for unanticipated events).\"],\"costs\":[\"Fees may apply for some reservations (Planning Your Event mentions payment of fees); amounts not stated.\"],\"fields\":[\"event type and date/time\",\"requested location\",\"expected attendance\",\"amplified sound needs\",\"organizer/RSO contact\",\"whether the 48-hour exception applies\"],\"sources\":[{\"url\":\"https://freeexpression.usc.edu/activism/planning-your-event/\",\"title\":\"Planning Your Event - Freedom of Expression\"},{\"url\":\"https://dps.usc.edu/services/usc-events-permit-application/\",\"title\":\"USC Events Permit Application - Department of Public Safety\"}]},{\"id\":\"reset-netid-password\",\"topic\":\"09\",\"name\":\"Reset a forgotten NetID password\",\"desc\":\"Student forgot their USC NetID password/passphrase (or is locked out) and wants to reset it so they can sign in to email, Brightspace, MyUSC, Wi-Fi, etc.\",\"system\":\"USC NetID Account Services (itservices.usc.edu/uscnetid \u2192 'Reset your NetID password', hosted on netid.usc.edu); fallback: ITS Service Desk (213) 740-5555, option 2\",\"steps\":[\"Go to USC NetID Account Services at itservices.usc.edu/uscnetid.\",\"Under 'Forgot your password,' select 'Reset your NetID password' (student organization accounts use 'Reset your Organization Account password').\",\"Before setting the new passphrase, put your mobile devices in airplane mode to avoid account lockouts.\",\"Complete the reset and choose a new passphrase that meets the requirements (16\u201364 characters, no NetID username, not a previous passphrase).\",\"Wait a few minutes for the new passphrase to take effect (the old one keeps working meanwhile).\",\"Update the passphrase wherever it is saved: email apps, and Wi-Fi (forget USC Secure Wireless and eduroam on each device, then reconnect).\",\"If the self-service reset does not work, call the ITS Service Desk at (213) 740-5555 and choose option 2 (24/7); be ready to verify your identity with a government ID.\",\"Optional: add a secondary email on NetID Account Services ('Update your secondary email') to speed up future resets.\"],\"req\":[\"Passphrase must be 16 to 64 characters\",\"Passphrase may not include your USC NetID username\",\"Previous passphrases may not be reused\",\"Some ITS Service Desk requests require a government ID for user verification\"],\"deadlines\":[\"No deadline stated; ITS Service Desk phone support is available 24 hours a day, 365 days a year\",\"A new passphrase may take a few minutes to become effective\"],\"costs\":[\"none stated\"],\"fields\":[\"Account type (personal NetID vs. student organization account)\",\"Whether the student can complete the online reset or needs phone support\",\"Whether a government ID is available for verification\",\"Devices/apps that store the old passphrase (phone email, Wi-Fi)\",\"Whether a secondary email is on file\"],\"sources\":[{\"url\":\"https://itservices.usc.edu/uscnetid/\",\"title\":\"USC NetID Account Services \u2013 USC Information Technology Services\"},{\"url\":\"https://itservices.usc.edu/how-to-about-your-usc-netid-passphrase/\",\"title\":\"How-to: About Your USC NetID Passphrase \u2013 USC Information Technology Services\"},{\"url\":\"https://itservices.usc.edu/2025/04/30/add-a-secondary-email-to-speed-up-netid-recovery/\",\"title\":\"Add a Secondary Email to Speed Up NetID Recovery \u2013 USC Information Technology Services\"},{\"url\":\"https://itservices.usc.edu/how-to-resetting-your-wireless-settings-usc-secure-wireless-and-eduroam/\",\"title\":\"How-to: Resetting Your Wireless Settings (USC Secure Wireless and eduroam) \u2013 USC Information Technology Services\"}]},{\"id\":\"register-new-duo-device\",\"topic\":\"09\",\"name\":\"Register a new Duo device\",\"desc\":\"Student got a new phone (or lost the old one) and needs to add a new device to Duo two-factor authentication so they can sign in to USC systems.\",\"system\":\"USC NetID Account Services \u2192 'Register a New Duo Device' (identity verification by Persona) or 'Manage your Duo MFA Devices' (itservices.usc.edu/uscnetid)\",\"steps\":[\"If you still have a working enrolled device: go to itservices.usc.edu/uscnetid \u2192 Manage your Duo MFA Devices (or the Managed Devices page after signing in to a USC service) and add the new device.\",\"If you can't approve Duo on an enrolled device (e.g., it was lost or stolen): on USC NetID Account Services select Register a New Duo Device.\",\"Log in with your USC NetID and password and click Validate.\",\"Choose how to receive the verification link: QR code, web link, SMS, or email.\",\"Agree to the USC Privacy Notice, click begin verifying, and select the country your ID is from.\",\"Take a clear picture of the front of your government ID (dark background); Persona processes it.\",\"Select 'get started,' center yourself, take a selfie and rotate your head as prompted.\",\"Navigate back to the page you started on to receive your Duo bypass code.\",\"Once you can sign in again, add or remove devices through Manage your Duo MFA Devices on USC NetID Account Services or the Managed Devices page; ITS strongly recommends enrolling more than one device or method. (The Register a New Duo Device how-to ends once you receive the bypass code.)\"],\"req\":[\"Must know your NetID and password\",\"Government-issued photo ID and ability to take a selfie for identity verification\",\"Duo is required for all current USC NetID owners\",\"Duo Voice authentication is being retired\"],\"deadlines\":[\"none stated\"],\"costs\":[\"Duo is free\"],\"fields\":[\"Whether the student still has a working enrolled device\",\"New device type and method (Duo Mobile push/passcode, Touch ID/Face ID/Windows Hello, security key, SMS)\",\"Country of the government ID to be used\",\"Preferred way to receive the verification link (QR code, web link, SMS, email)\"],\"sources\":[{\"url\":\"https://itservices.usc.edu/how-to-register-a-new-duo-device/\",\"title\":\"How to: Register a New Duo Device \u2013 USC Information Technology Services\"},{\"url\":\"https://itservices.usc.edu/duo/\",\"title\":\"Duo \u2013 USC Information Technology Services\"},{\"url\":\"https://itservices.usc.edu/uscnetid/\",\"title\":\"USC NetID Account Services \u2013 USC Information Technology Services\"}]},{\"id\":\"get-duo-bypass-code\",\"topic\":\"09\",\"name\":\"Get a Duo bypass code (for a day or for travel)\",\"desc\":\"Student can't use their enrolled Duo device today (dead/lost phone, no service) or is about to travel, and needs a temporary bypass code.\",\"system\":\"USC NetID Account Services \u2192 'Get Duo Bypass Code for a Day' (ID verification) or 'Get Duo Bypass Code for Travel' (via normal Duo login)\",\"steps\":[\"For a one-day code: go to itservices.usc.edu/uscnetid and select 'Get a Duo Bypass Code for a Day.'\",\"Log in with your USC NetID and password and click Validate.\",\"Receive the verification link (QR code, web link, SMS, or email), agree to the privacy notice, photograph the front of your government ID, and take a selfie.\",\"Return to the page you started on to receive the bypass code; use it at the Duo prompt (up to 10 times that day).\",\"For travel: on USC NetID Account Services select 'Get Duo Bypass Code for Travel,' complete your usual Duo login on the Shibboleth screen, and receive the code (unlimited uses for 7 days).\",\"Before traveling, register your devices and install Duo Mobile so offline options work.\"],\"req\":[\"Must already be enrolled in Duo\",\"One-day code requires identity verification with a government ID (e.g., driver\u2019s license or passport)\",\"Travel code requires completing a normal Duo login to receive it\",\"Bypass codes are not intended as your only multifactor method\"],\"deadlines\":[\"One-day code: usable up to 10 times on the day it is issued\",\"Travel code: unlimited uses within 7 days of being issued\"],\"costs\":[\"none stated (Duo is free)\"],\"fields\":[\"Which code is needed (one-day vs. travel)\",\"Whether the student can complete a Duo login right now (needed for the travel code)\",\"Government ID on hand (one-day code)\",\"Travel dates (a travel code lasts 7 days)\"],\"sources\":[{\"url\":\"https://itservices.usc.edu/how-to-get-a-duo-bypass-code-for-a-day/\",\"title\":\"How to: Get a Duo Bypass Code for a Day \u2013 USC Information Technology Services\"},{\"url\":\"https://itservices.usc.edu/how-to-get-duo-bypass-code-for-travel/\",\"title\":\"How to: Get Duo Bypass Code for Travel \u2013 USC Information Technology Services\"},{\"url\":\"https://itservices.usc.edu/duo/\",\"title\":\"Duo \u2013 USC Information Technology Services\"}]},{\"id\":\"install-microsoft-365\",\"topic\":\"09\",\"name\":\"Install Microsoft 365 (Office)\",\"desc\":\"Student wants to install Word, Excel, PowerPoint, etc. on a personal computer or phone using their free USC license.\",\"system\":\"Microsoft Office portal (office.com/OLS/MySoftware.aspx) signed in with NetID@usc.edu\",\"steps\":[\"Go to the Microsoft Office portal at office.com/OLS/MySoftware.aspx.\",\"On the Microsoft Sign in screen, enter your full USC NetID@usc.edu and click Next.\",\"Log in on the USC NetID login screen with your NetID and password (and Duo).\",\"On the Apps & devices page, click Install Office and run the installer.\",\"The first time you open an Office app, choose 'Sign-in to an existing Office 365 subscription' and sign in with NetID@usc.edu.\",\"For a phone/tablet: from Apps & devices, under 'Get Office on your phone or tablet,' pick iOS, Android or Windows and follow the emailed/texted download link (no app-store charge).\"],\"req\":[\"Current USC student (active NetID)\",\"Up to 5 personal computers (Mac/Windows) and up to 5 mobile devices\",\"Departmental organizational accounts and iVIP affiliate accounts are not eligible\",\"Access ends when you leave USC\"],\"deadlines\":[\"None stated; access to the downloaded software ends when your USC affiliation ends\"],\"costs\":[\"Free for current students\",\"No fee for the mobile download\"],\"fields\":[\"Device type (Windows, Mac, iOS, Android)\",\"Number of devices already activated (limit 5 computers + 5 mobile)\",\"Signing in with NetID@usc.edu\",\"Whether the student is currently enrolled\"],\"sources\":[{\"url\":\"https://software.usc.edu/microsoft-office/\",\"title\":\"Microsoft Office \u2013 Software Available to Campus\"},{\"url\":\"https://itservices.usc.edu/how-to-microsoft-office/\",\"title\":\"How-to: Microsoft Office \u2013 USC Information Technology Services\"},{\"url\":\"https://software.usc.edu/free-to-campus/\",\"title\":\"Free Campus-Wide Software \u2013 Software Available to Campus\"}]},{\"id\":\"use-adobe-creative-cloud\",\"topic\":\"09\",\"name\":\"Get access to Adobe Creative Cloud\",\"desc\":\"Student wants to use Photoshop, Premiere Pro, Illustrator or other Adobe apps for coursework.\",\"system\":\"ITS computing centers (Leavey lower level, KOH 206, WPH B34) and USC CloudApps (cloudapps.usc.edu, VMware Horizon); school/unit local IT for any downloads\",\"steps\":[\"On campus: go to an ITS computing center \u2014 Ahmanson Information Commons (Leavey Library lower level), King Hall KOH 206, or Waite Phillips Hall WPH B34 \u2014 during open hours.\",\"Use a lab computer (or an ITS loaner laptop); Adobe apps there require signing in with your Adobe account.\",\"Remotely: log in at cloudapps.usc.edu (VMware Horizon in your browser, or install the VMware client) and complete USC two-factor authentication.\",\"For a personal download, ask your school or unit\u2019s local IT support whether they provide Adobe Creative Cloud downloads.\"],\"req\":[\"Students get Adobe at no cost through ITS computing centers and USC CloudApps\",\"CloudApps: active students/faculty only, for instruction, assignments and research; requires USC two-factor authentication\"],\"deadlines\":[\"Computing center hours (KOH/WPH labs): Mon\u2013Fri 9 am\u20139 pm, Sat 9 am\u20135 pm, Sun 12 pm\u20138 pm\"],\"costs\":[\"No cost to students in computing centers and CloudApps\"],\"fields\":[\"On-campus lab vs. remote CloudApps\",\"Which Adobe app is needed\",\"Whether the student has an Adobe account to sign in on lab machines\",\"Student's school (to check local IT for downloads)\"],\"sources\":[{\"url\":\"https://software.usc.edu/adobecc/\",\"title\":\"Adobe Creative Cloud \u2013 Software Available to Campus\"},{\"url\":\"https://itservices.usc.edu/its-computing-centers/\",\"title\":\"Computing Centers \u2013 USC Information Technology Services\"},{\"url\":\"https://software.usc.edu/cloudapps-usc-edu/\",\"title\":\"Cloudapps.usc.edu \u2013 Software Available to Campus\"}]},{\"id\":\"reserve-library-study-room\",\"topic\":\"09\",\"name\":\"Reserve a library study room or study pod\",\"desc\":\"Student wants to book a group study room (or a Leavey study pod) in a USC library for a specific date and time.\",\"system\":\"LibCal room booking at libcal.usc.edu (e.g., libcal.usc.edu/reserve/dml, /reserve/lvl-pods, /reserve/SEL); Norris Medical Library group room reservation system\",\"steps\":[\"Go to libcal.usc.edu and pick the space (e.g., libcal.usc.edu/reserve/dml for Doheny collaborative workrooms, /reserve/lvl-pods for Leavey study pods, /reserve/SEL for Science & Engineering), or start from libraries.usc.edu/spaces-overview \u2192 Reserve Now.\",\"Available rooms are highlighted in green; choose a day, then click 'Room and Time' (select several boxes for more than one block, up to 2 hours total per day).\",\"Log in with your USC NetID.\",\"Open the confirmation email and click the link within 30 minutes to confirm the reservation.\",\"Save the confirmation email and forward it to group members.\",\"Arrive within the 10-minute grace period; if you will not use the room, cancel using the link in the confirmation email.\"],\"req\":[\"Group study rooms are for current USC students\u2019 academic use; a valid USC email/NetID is required\",\"Reservations up to 7 days in advance; maximum 2 hours per calendar day across all reservations\",\"Groups of two or more have priority (SEL: groups of four or more)\",\"Study pods: 2 hours per person per day\",\"Leavey lower-level ITS collaborative rooms are reserved in person at the desk only\",\"Norris Medical Library rooms: students only, 1 day in advance, held 15 minutes, 2 hours per day\"],\"deadlines\":[\"Book up to 7 days ahead\",\"Confirm within 30 minutes of booking\",\"10-minute grace period after the start time\"],\"costs\":[\"none stated\"],\"fields\":[\"Library and space (group room, study pod, Norris room)\",\"Date and start/end time (2-hour daily limit)\",\"Group size\",\"USC email/NetID for the confirmation\",\"Other bookings already made that day\"],\"sources\":[{\"url\":\"https://libraries.usc.edu/locations/doheny-memorial-library/rooms/dml-collaborative-work-rooms\",\"title\":\"DML - Collaborative Work Rooms | USC Libraries\"},{\"url\":\"https://libraries.usc.edu/access-borrowing-policies\",\"title\":\"Access and Borrowing Policies | USC Libraries\"},{\"url\":\"https://libraries.usc.edu/space/lvl-2nd-floor-study-pods\",\"title\":\"LVL - 2nd Floor Study Pods | USC Libraries\"},{\"url\":\"https://libraries.usc.edu/spaces-overview\",\"title\":\"Spaces | USC Libraries\"}]},{\"id\":\"renew-library-items\",\"topic\":\"09\",\"name\":\"Renew library books\",\"desc\":\"Student wants to extend the due date of books or other items borrowed from USC Libraries (or interlibrary loan).\",\"system\":\"USC Libraries account (My Account in the library catalog via the 'Renew Books' link on libraries.usc.edu); any library service desk or phone; IDD account (ILLiad) for interlibrary loan items\",\"steps\":[\"Online: on libraries.usc.edu select 'Renew Books' (My Account in the catalog) and sign in with your USC NetID.\",\"Review your loans and due dates and renew the eligible items.\",\"Or renew in person at any library service desk, or by phone with any USC library (have your USC ID).\",\"For interlibrary loan items: sign in to your IDD account \u2192 Checked Out Items \u2192 click the Transaction Number \u2192 Renew Request; watch for the approval/denial email (contact IDD if none within 3 days).\"],\"req\":[\"All three renewal methods require the borrower's USC ID\",\"Reserve, short-term (3-hour, 1-day, 3-day) and recalled items cannot be renewed\",\"Leavey laptops and accessories cannot be renewed\",\"ILL items cannot be renewed once overdue, and only if the lending library allows it\",\"E-books do not need renewal\"],\"deadlines\":[\"Standard loans: 30-day grace period after the due date; on the 31st day a $150 per-item replacement fee is assessed\",\"An approved ILL renewal adds five days to the current due date\"],\"costs\":[\"Renewal itself: none stated\",\"Overdue standard items: $150 replacement fee per item on day 31\",\"Short-term loans: $1.00/hour (3-hour) or $5.00/day (1-, 3-, 7-day), $50 max\"],\"fields\":[\"Which items to renew (title/barcode)\",\"Item type (standard, reserve/short-term, recalled, ILL)\",\"Current due date and whether it is already overdue\",\"Renewal method (online, desk, phone)\"],\"sources\":[{\"url\":\"https://libraries.usc.edu/access-borrowing-policies\",\"title\":\"Access and Borrowing Policies | USC Libraries\"},{\"url\":\"https://libraries.usc.edu/\",\"title\":\"Home | USC Libraries\"},{\"url\":\"https://libraries.usc.edu/renewal-requests\",\"title\":\"Renewal Requests | USC Libraries\"},{\"url\":\"https://libanswers.usc.edu/faq/109387\",\"title\":\"How do I renew an ebook? - LibAnswers\"}]},{\"id\":\"request-interlibrary-loan\",\"topic\":\"09\",\"name\":\"Request an interlibrary loan (ILL) or Scan & Deliver\",\"desc\":\"Student needs a book, article or chapter that USC Libraries doesn't own (or a scan of something USC owns) and wants to request it.\",\"system\":\"USC Libraries Interlibrary Loan & Document Delivery (IDD) account \u2014 ILLiad, signed in with USC NetID (link on libraries.usc.edu/interlibrary-loan-and-document-services)\",\"steps\":[\"Confirm what you need: ILL is for materials not owned or otherwise unavailable from USC; for PDFs of articles/chapters (including from USC-owned items) use Scan & Deliver.\",\"Go to the IDD page on libraries.usc.edu and sign in with your USC NetID.\",\"First time: register and create your IDD account (keep your address current if you use Home Delivery).\",\"Submit the request form with as much citation detail as possible (author, title, publisher/journal, volume, issue, pages, date).\",\"Track the request status in your IDD account (e.g., 'Request Sent', 'Customer Notified via E-Mail').\",\"Physical items: pick up at Leavey Library when notified by email (Health Sciences users: Norris Medical Library); articles/chapters arrive as an emailed PDF link that is active for 30 days.\",\"Return physical items by the lending library's due date; request renewals in IDD before they're overdue.\"],\"req\":[\"Currently enrolled UPC and HSC undergraduate and graduate students, faculty and staff are eligible\",\"Gould School of Law users must use the Asa V. Call Law Library ILL\",\"Visiting scholars are not eligible\",\"Required course textbooks cannot be requested\",\"Do not contact the libraries that hold the item before submitting\",\"The original requestor is responsible for the condition and timely return of ILL items\"],\"deadlines\":[\"Average ILL article turnaround: 24\u201348 hours\",\"Average ILL physical item turnaround: 3\u20135 days\",\"Scan & Deliver links are active for 30 days\",\"Due dates are set by the lending library\"],\"costs\":[\"Usually no charge; some materials (notably business reports) are available only for a fee\",\"Copyright fees, if required, are paid by the library, not the patron\",\"Lost or unreturned ILL items: $150 replacement fee per item (multi-volume requests: $150 per volume)\"],\"fields\":[\"Full citation of the item\",\"Format needed (physical loan vs. scanned PDF)\",\"Pickup location (Leavey or Norris) or Home Delivery eligibility\",\"Date the item is needed by\",\"Whether it is a required course textbook\"],\"sources\":[{\"url\":\"https://libraries.usc.edu/interlibrary-loan-and-document-services\",\"title\":\"Interlibrary Loan & Document Delivery (IDD) | USC Libraries\"},{\"url\":\"https://libraries.usc.edu/eligibility-idd-services\",\"title\":\"Eligibility for IDD Services | USC Libraries\"},{\"url\":\"https://libraries.usc.edu/interlibrary-loan-0\",\"title\":\"Interlibrary Loan | USC Libraries\"},{\"url\":\"https://libraries.usc.edu/idd-what-can-i-request\",\"title\":\"IDD: What can I request? | USC Libraries\"}]},{\"id\":\"book-research-consultation\",\"topic\":\"09\",\"name\":\"Book a research consultation with a librarian\",\"desc\":\"Student wants one-on-one help from a librarian with a research paper, thesis, literature review or systematic review.\",\"system\":\"Subject Librarians directory (libraries.usc.edu/subject-librarians) \u2014 contact your librarian by email/phone; Ask a Librarian chat/email; health sciences systematic-review consultation form (LibAnswers)\",\"steps\":[\"Find your subject on libraries.usc.edu/subject-librarians and note the librarian\u2019s email, phone and office.\",\"Email or call that librarian with your topic, course/assignment and deadline, and ask to set up an appointment (good for in-depth or longer-term projects).\",\"For quick questions, use Ask a Librarian: chat Monday\u2013Thursday 10 a.m.\u20134 p.m., or email Monday\u2013Friday (Fall 2026 service dates Aug. 24\u2013Dec. 16).\",\"Health sciences systematic reviews: submit the form in the LibAnswers FAQ to schedule a one-hour consultation with a health sciences librarian.\"],\"req\":[\"Subject librarians help with assignments, search strategies and research by appointment, phone or email\",\"Ask a Librarian is unavailable on holidays\"],\"deadlines\":[\"Ask a Librarian Fall 2026 service dates: August 24 \u2013 December 16\",\"Chat hours: Monday\u2013Thursday, 10 a.m.\u20134 p.m.\"],\"costs\":[\"none stated\"],\"fields\":[\"Subject/discipline and course or project\",\"Assignment type and deadline\",\"Preferred meeting format and availability\",\"Student's USC email\"],\"sources\":[{\"url\":\"https://libraries.usc.edu/subject-librarians\",\"title\":\"Subject Librarians | USC Libraries\"},{\"url\":\"https://libanswers.usc.edu/faq/21257\",\"title\":\"Is there a specialist in my field at the library? - LibAnswers\"},{\"url\":\"https://libanswers.usc.edu/faq/21273\",\"title\":\"Who can I talk to to get help with my research? - LibAnswers\"},{\"url\":\"https://libraries.usc.edu/ask-a-librarian\",\"title\":\"Ask A Librarian | USC Libraries\"}]},{\"id\":\"borrow-laptop-or-equipment\",\"topic\":\"09\",\"name\":\"Borrow a laptop or equipment\",\"desc\":\"Student needs a loaner laptop (Windows or Mac) or equipment such as headphones, an HDMI adapter or a tripod.\",\"system\":\"ITS Laptop Loaner Program (ITS Desk, Leavey Library basement / Ahmanson Information Commons); Leavey Library Circulation Desk; Science & Engineering Library circulation desk\",\"steps\":[\"ITS 4-hour loaner: go to the ITS Desk in the Leavey Library basement, present your valid USC Card to be scanned, and sign the Student Laptop Loan Agreement; you are emailed the loan confirmation and return time.\",\"Need more time? Arrange the free 4-hour renewal before the first loan expires.\",\"Mac short-term rental: email spaces@usc.edu.\",\"Library laptop: ask at the Leavey Library Circulation Desk (Windows; due at Leavey closing time the day after checkout, no renewals) or the Science & Engineering Library circulation desk (library use only; sign a borrowing agreement).\",\"Other equipment: ask at Leavey circulation (the Leavey Library page lists (213) 740-4350) for headphones, audio recorders or reserve tripods; HDMI adapters and mice are lent at the ITS computing centers.\",\"Copy your files to another location such as a USB flash drive (files left on ITS loaners are erased) and return the item on time to the same location.\"],\"req\":[\"ITS loaners: currently enrolled USC students with a valid USC Card; present the card and sign the loan agreement\",\"Borrower pays for damage or missing cables/accessories and the full replacement cost if the laptop is stolen\",\"Repeated late returns, damage or loss can lead to exclusion from the ITS loan service\",\"SEL laptops: library use only, first-come, first-served\",\"USC Libraries do not lend digital cameras or camcorders\"],\"deadlines\":[\"ITS loaner: 4 hours, plus an optional 4-hour renewal arranged before the first loan expires\",\"Leavey library laptops: due at Leavey closing time on the day after checkout (LibAnswers: 24 hours, no renewal)\",\"SEL laptops: due the same day at library closing\"],\"costs\":[\"ITS loaner and renewal: no charge\",\"ITS late return: $20 for every 30 minutes late, up to the laptop replacement cost\",\"Leavey library laptop/accessory late fine: $5.00 per day per item, max $50 per item\",\"Leavey lost/damaged laptop, charger and case: $1,200 + $100 processing; keyboard/mouse $10 each\"],\"fields\":[\"Which program (ITS 4-hour loaner, Leavey library laptop, or SEL in-library laptop)\",\"Windows or Mac\",\"How long the student needs it\",\"Return location and time\",\"Student has a valid USC Card\"],\"sources\":[{\"url\":\"https://itservices.usc.edu/usc-computing-center-laptop-loaner-program/\",\"title\":\"USC Computing Center Laptop Loaner Program \u2013 USC Information Technology Services\"},{\"url\":\"https://libanswers.usc.edu/faq/21367\",\"title\":\"Does the Library have laptops to check-out? - LibAnswers\"},{\"url\":\"https://libraries.usc.edu/access-borrowing-policies\",\"title\":\"Access and Borrowing Policies | USC Libraries\"},{\"url\":\"https://libraries.usc.edu/locations/science-engineering-library/science-engineering-library-technology-services\",\"title\":\"Science & Engineering Library Technology | USC Libraries\"}]},{\"id\":\"activate-netid\",\"topic\":\"09\",\"name\":\"Activate a new USC NetID\",\"desc\":\"Newly admitted (or visiting) student wants to activate their USC NetID for the first time and set up Duo.\",\"system\":\"USC NetID Account Services \u2192 'Activate your USC NetID' (itservices.usc.edu/uscnetid); Duo enrollment at account.usc.edu/2fa/enroll\",\"steps\":[\"If you just certified your enrollment, wait at least 24 hours after your certification is confirmed (you should receive a confirmation email).\",\"Visiting students (DEN, international exchange, post-docs): register for courses in Web Registration first.\",\"Go to itservices.usc.edu/uscnetid and select 'Activate your USC NetID' ('New to USC? Log in for the first time').\",\"Immediately enroll in Duo: go to account.usc.edu/2fa/enroll, sign in, click Get Started and enroll a device (ITS recommends more than one).\",\"Add a secondary email on NetID Account Services ('Update your secondary email') for faster password recovery.\",\"If your date of birth is wrong on your record, submit an inquiry to the Verifications Department with a photo of your ID; if problems continue, contact the ITS Service Desk / Customer Support Center ((213) 740-5555, option 2).\"],\"req\":[\"Admitted students who just certified enrollment should wait at least 24 hours after the certification is confirmed\",\"Visiting students must register for courses via Web Registration before activating\",\"Duo enrollment is required immediately after activation\"],\"deadlines\":[\"Wait at least 24 hours after certification is confirmed before requesting your NetID\"],\"costs\":[\"none stated (Duo is free)\"],\"fields\":[\"Student type (admitted new student, visiting/DEN/exchange)\",\"Date enrollment was certified\",\"Whether date of birth on record is correct\",\"Device(s) to enroll in Duo\"],\"sources\":[{\"url\":\"https://itservices.usc.edu/uscnetid/\",\"title\":\"USC NetID Account Services \u2013 USC Information Technology Services\"},{\"url\":\"https://ask.usc.edu/s/article/000001484\",\"title\":\"askUSC: What should I do if I have certified my enrollment but am having problems activating my USC NetID?\"},{\"url\":\"https://ask.usc.edu/s/article/000002973\",\"title\":\"askUSC: What do I do if I\u2019m a visiting student and cannot activate my NetID?\"},{\"url\":\"https://ask.usc.edu/s/article/000002927\",\"title\":\"askUSC: I can\u2019t activate my Net ID because my date of birth is incorrect. How do I fix this?\"}]},{\"id\":\"print-in-library\",\"topic\":\"09\",\"name\":\"Print a document in a USC library from a laptop or phone\",\"desc\":\"Student wants to print a file from their own laptop or phone on a USC Libraries printer.\",\"system\":\"Library Print (libraryprint.usc.edu web upload or the Pharos Print mobile app) and USC Libraries Xerox multifunction printers; payment by USCard or Library Print & Copy Card\",\"steps\":[\"Create a Library Print account once: tap your USCard on any library Xerox printer and enter your NetID and password, or sign in at libraryprint.usc.edu or in the Pharos Print app.\",\"From a laptop: go to libraryprint.usc.edu, sign in, click 'Upload,' select the document, set print options and preview.\",\"From a phone: in the Pharos Print app (server libraryprint.usc.edu, port 443), log on, open the document with Pharos Print, set options and Apply Changes.\",\"At any USC Libraries Xerox printer, tap your USCard (or enter your credentials), select 'Print Release,' choose the document, verify and print (color jobs on a color printer).\",\"Make sure your USCard has funds; the balance displays when you tap the printer.\"],\"req\":[\"A Library Print account is required to print or copy on library Xerox printers\",\"Funds on your USCard or a Library Print & Copy Card\",\"Color jobs must be released from a color printer\"],\"deadlines\":[\"none stated\"],\"costs\":[\"B&W 8.5x11: 12\u00a2 single-sided, 16\u00a2 double-sided per sheet; 11x17: 18\u00a2 single, 30\u00a2 double\",\"Color 8.5x11: 50\u00a2 single-sided, 70\u00a2 double-sided per sheet; 11x17: 60\u00a2 single, $1 double\",\"Library Print & Copy Card: $1.00 (rechargeable, $1.00 minimum add)\"],\"fields\":[\"File to print and number of copies\",\"Color or black & white; single- or double-sided; paper size\",\"Printer location (color-capable?)\",\"Payment method and balance\"],\"sources\":[{\"url\":\"https://libraries.usc.edu/print-scan-or-copy\",\"title\":\"Printing & Copying Overview | USC Libraries\"},{\"url\":\"https://libraries.usc.edu/print-scan-or-copy/create-library-print-account\",\"title\":\"Create a Library Print Account | USC Libraries\"},{\"url\":\"https://libraries.usc.edu/print-scan-or-copy/print-libraryprint.usc.edu\",\"title\":\"Print from Libraryprint.usc.edu | USC Libraries\"},{\"url\":\"https://libraries.usc.edu/print-scan-or-copy/print-mobile-print\",\"title\":\"Print from Mobile Print | USC Libraries\"}]},{\"id\":\"request-spss-license\",\"topic\":\"09\",\"name\":\"Get a free SPSS license\",\"desc\":\"Student needs IBM SPSS for a class or research and wants the free student subscription.\",\"system\":\"ITS ServiceNow request linked from software.usc.edu/spss/spss-orderstudent; downloads at software.usc.edu/spss\",\"steps\":[\"If you are enrolled in a class that uses SPSS, ask your instructor for the SPSS license first.\",\"Dornsife students: contact ts@dornsife.usc.edu for SPSS subscriptions.\",\"Otherwise, submit a ticket through the ServiceNow request linked on ITS's 'Ordering SPSS for Students' page.\",\"After you have a subscription, download the student version for your operating system from software.usc.edu/spss (on campus via USC Secure Wireless, or through the VPN if required).\",\"Renew by submitting the same request each year.\"],\"req\":[\"Available to USC students at no cost (SPSS Premium package)\",\"Annual subscription that must be requested yearly\",\"Some software downloads require a USC secure network connection (USC Secure Wireless or VPN)\"],\"deadlines\":[\"Subscription is annual and must be requested yearly\"],\"costs\":[\"No cost to students\"],\"fields\":[\"Operating system (Windows, Mac, Linux) and SPSS version\",\"Whether the student is in a class with an instructor-provided license\",\"Whether the student is in Dornsife\",\"New request vs. renewal\"],\"sources\":[{\"url\":\"https://software.usc.edu/spss/spss-orderstudent/\",\"title\":\"Ordering SPSS for Students \u2013 Software Available to Campus\"},{\"url\":\"https://software.usc.edu/spss/\",\"title\":\"SPSS \u2013 Software Available to Campus\"},{\"url\":\"https://software.usc.edu/all-software/\",\"title\":\"All Software \u2013 Software Available to Campus\"}]},{\"id\":\"report-phishing\",\"topic\":\"09\",\"name\":\"Report a phishing email or a compromised account\",\"desc\":\"Student received a suspicious email/text, or clicked a link and entered their password, and wants to report it.\",\"system\":\"phishing@usc.edu (forward with full headers); security@usc.edu and the ITS 24\u00d77 line 213-740-5555 for security incidents; USC NetID Account Services to change the password\",\"steps\":[\"In Gmail: open the suspicious message without clicking links, click the three dots next to Reply, choose 'Show original,' and copy everything.\",\"Forward the original message, paste the copied text at the top, and send it to phishing@usc.edu (optionally also use Gmail\u2019s Report phishing).\",\"In Outlook: forward the message as an attachment to phishing@usc.edu.\",\"If you entered your NetID password: change it immediately on USC NetID Account Services.\",\"Report the incident: email security@usc.edu or call the ITS 24\u00d77 line at 213-740-5555.\"],\"req\":[\"Do not reply, click links or open attachments in the suspicious message\",\"Phishing reports must include the original message/headers in the specified formats\"],\"deadlines\":[\"Report compromised accounts immediately (no specific deadline stated)\"],\"costs\":[\"none stated\"],\"fields\":[\"Email program used (Gmail or Outlook)\",\"Whether any link was clicked or credentials/personal info entered\",\"Sender and subject of the message\"],\"sources\":[{\"url\":\"https://itservices.usc.edu/how-to-reporting-phishing/\",\"title\":\"How-to: Reporting Phishing \u2013 USC Information Technology Services\"},{\"url\":\"https://itservices.usc.edu/how-to-frequently-asked-questions-about-phishing/\",\"title\":\"How-to: Frequently Asked Questions about Phishing \u2013 USC Information Technology Services\"},{\"url\":\"https://itservices.usc.edu/how-to-passphrase-tips/\",\"title\":\"How-to: Passphrase Tips \u2013 USC Information Technology Services\"},{\"url\":\"https://itservices.usc.edu/about/contact/\",\"title\":\"Contact Us \u2013 USC Information Technology Services\"}]},{\"id\":\"join-student-organization\",\"topic\":\"10\",\"name\":\"Join a student organization\",\"desc\":\"Student wants to find a club or recognized student organization (RSO) that matches their interests and become a member.\",\"system\":\"EngageSC (engage.usc.edu), run by USC Campus Activities\",\"steps\":[\"Go to EngageSC (engage.usc.edu) and log in.\",\"Search the EngageSC Directory or the \\\"Groups\\\" search bar by keyword; try a few different keywords. EngageSC hosts all currently recognized RSOs.\",\"Open the organization's EngageSC page and join the organization.\",\"Optionally meet groups in person at the Involvement Fair (Spring fair: Week 1 of spring semester on Trousdale Parkway, Alumni Park and McCarthy Quad; register as an attendee on the EngageSC event page).\",\"Use the group's discussion, news posts and group messaging in EngageSC; you can record your activities and memberships to track your involvement.\"],\"req\":[\"RSOs must maintain open membership in accordance with university policies and the organization's mission; voting membership and officer positions are limited to currently enrolled USC students.\",\"Campus Activities says general membership should be free from barriers such as interviews, applications, assessments, or required dues (some programs, e.g., Club Sports, have passes/dues).\",\"Social fraternities and sororities are recognized through Fraternity & Sorority Life and joined through council recruitment/intake.\",\"Questions about RSOs: Campus Activities, stuacts@usc.edu.\"],\"deadlines\":[\"No deadline to join most organizations; Spring Involvement Fair is in Week 1 of the spring semester (spring 2027 classes begin January 11, 2027).\"],\"costs\":[\"none stated for joining through EngageSC (individual groups may have their own costs)\"],\"fields\":[\"organization name (and that it is an active recognized org on EngageSC)\",\"student's USC login/NetID\",\"whether the group has its own application, tryout or dues\",\"preferred contact method for the group\"],\"sources\":[{\"url\":\"https://campusactivities.usc.edu/engagesc/\",\"title\":\"EngageSC - Campus Activities\"},{\"url\":\"https://campusactivities.usc.edu/programs/recognized-student-organizations/faq-rso-recognition-process/\",\"title\":\"FAQ - RSO Recognition Process - Campus Activities\"},{\"url\":\"https://campusactivities.usc.edu/programs/recognized-student-organizations/rso-involvement-fair-tabling-opportunities/\",\"title\":\"RSO Involvement Fair & Tabling Opportunities - Campus Activities\"},{\"url\":\"https://campusactivities.usc.edu/programs/recognized-student-organizations/rso-privileges-responsibilities/\",\"title\":\"RSO Benefits & Responsibilities - Campus Activities\"}]},{\"id\":\"rsvp-campus-event\",\"topic\":\"10\",\"name\":\"RSVP to a campus event\",\"desc\":\"Student wants to register/RSVP for a campus event (university calendar event, student org event, career event, or arts event).\",\"system\":\"USC Events Calendar (calendar.usc.edu); EngageSC event pages; Handshake (career events); Visions and Voices event pages\",\"steps\":[\"University events: find the event on calendar.usc.edu and click Register (where shown) and/or Add to My Plans; optionally subscribe to the Digest emailer.\",\"Student org / Campus Activities events: open the event in EngageSC and register as an attendee on the event page.\",\"Career Center events (Trojan Talks, workshops, fairs): in Handshake go to Events, find the event, and click Attend; some employers also require their own registration.\",\"Visions and Voices events: open the event page on visionsandvoices.usc.edu and use the RSVP link; reservations open about four weeks before and are online only.\",\"Save the confirmation; for virtual career events register at least two days ahead to receive the link.\"],\"req\":[\"Some events are limited to USC students/faculty/staff (current USC ID).\",\"Visions and Voices: one ticket per USC ID for USC students.\",\"Trojan Talks: all students interested in attending must RSVP.\"],\"deadlines\":[\"Visions and Voices reservations open approximately four weeks before each event.\",\"Trojan Talks: register at least two days before the event to receive virtual session URLs.\"],\"costs\":[\"Visions and Voices events are free for USC students; other events vary (see each listing).\"],\"fields\":[\"event name, date and time\",\"which platform hosts the RSVP (calendar.usc.edu, EngageSC, Handshake, or V&V page)\",\"number of tickets/attendees (V&V: one per USC ID)\",\"whether the event is USC-only and requires a USC ID\",\"accessibility accommodations needed\"],\"sources\":[{\"url\":\"https://calendar.usc.edu/\",\"title\":\"Events Calendar - USC Event Calendar\"},{\"url\":\"https://campusactivities.usc.edu/programs/recognized-student-organizations/rso-involvement-fair-tabling-opportunities/\",\"title\":\"RSO Involvement Fair & Tabling Opportunities - Campus Activities\"},{\"url\":\"https://careers.usc.edu/resources/virtual-trojan-talks/\",\"title\":\"Trojan Talks - USC Career Center\"},{\"url\":\"https://visionsandvoices.usc.edu/attendance-policies\",\"title\":\"Attendance Policies | USC Visions & Voices\"}]},{\"id\":\"book-career-advising-appointment\",\"topic\":\"10\",\"name\":\"Book a career advising appointment\",\"desc\":\"Student wants a 30-minute appointment with a USC Career Center advisor (career planning, job/internship search, networking, negotiation, mock interview).\",\"system\":\"Handshake (USC Career Center appointment scheduling)\",\"steps\":[\"Log in to Handshake with USC SSO (activate the account first if needed).\",\"Go to Career Center, then Appointments.\",\"Click \\\"Schedule a New Appointment\\\" and choose USC Career Center \u2013 Current Students; pick an available time that fits the topic.\",\"Choose virtual or in-person; for virtual, state in the request notes whether you want phone (include your number) or Zoom (link emailed to your USC address after approval). In-person appointments are in the Career Center lobby, Student Union Suite 110.\",\"For a tailored mock interview, email the advisor your resume and a job description at least two full business days before the appointment.\",\"For resume critiques, use drop-in advising instead (STU 110, 1:00\u20133:30 pm, Monday\u2013Friday in fall/spring).\"],\"req\":[\"Current students in certificate and degree programs (non-degree students are not eligible).\",\"One advising contact per day (appointment or drop-in).\",\"Graduate students are limited to one appointment with the central Career Center before referral to their school's career services.\",\"Resume critiques are only done in drop-in advising, not appointments.\"],\"deadlines\":[\"Cancel at least 48 hours / two business days before the appointment (email careers@usc.edu or call 213-740-9111), or advising privileges may be revoked.\"],\"costs\":[\"none stated\"],\"fields\":[\"appointment topic\",\"format (phone, Zoom, or in person)\",\"phone number if phone appointment\",\"preferred date/time\",\"student level (undergraduate vs graduate) and prior central Career Center appointments\",\"whether a mock interview job description/resume will be sent\"],\"sources\":[{\"url\":\"https://careers.usc.edu/channels/appointments\",\"title\":\"Appointments - USC Career Center\"}]},{\"id\":\"register-for-career-fair\",\"topic\":\"10\",\"name\":\"Register for a career fair\",\"desc\":\"Student wants to RSVP for the USC Career Center career fair (or the Internship Expo) and see which employers are attending.\",\"system\":\"Handshake (Events > Career fairs at your school)\",\"steps\":[\"Log in to Handshake.\",\"Click the Events tab, then \\\"Career fairs at your school,\\\" and select the fair (e.g., the Spring 2027 Career Fair); the Internship Expo also registers on Handshake.\",\"RSVP to see the list of participating employers; check back regularly because employers register daily.\",\"Build an action plan: research target employers (tables are organized by industry), prepare an elevator pitch, print resume copies, plan professional attire, and bring a refillable water bottle (zero-waste event).\",\"If you need a disability-related accommodation, submit the Career Center accommodation request form before the event.\"],\"req\":[\"Career fairs are open to all class years and majors, including transfer students (career fairs are for all currently enrolled USC students, recent graduates, and alumni).\",\"Employers recruit for full-time, part-time and paid internship roles.\",\"The Engineering Expo is a separate event for engineering students.\"],\"deadlines\":[\"Spring 2027 Career Fair: Thursday, February 4, 2027, 11:00 am\u20133:00 pm PT, outdoors on Trousdale Parkway (employer registration page).\",\"The Internship Expo: Wednesday, February 3, 2027, 1:00\u20133:30 pm PT, outdoors on Trousdale Parkway.\",\"Fall 2026 Career Fair (past): Thursday, September 10, 2026, 11:00 am\u20133:00 pm PT, Trousdale Parkway.\"],\"costs\":[\"none stated for students (employers pay registration fees)\"],\"fields\":[\"which fair (Spring Career Fair vs Internship Expo)\",\"date\",\"student's Handshake account is active\",\"accommodation needs\"],\"sources\":[{\"url\":\"https://careers.usc.edu/fall-career-fair/\",\"title\":\"Fall 2026 Career Fair - USC Career Center\"},{\"url\":\"https://careers.usc.edu/employers-spring-career-fair/\",\"title\":\"Employers: Spring Career Fair - USC Career Center\"},{\"url\":\"https://careers.usc.edu/the-internship-expo/\",\"title\":\"The Internship Expo - USC Career Center\"},{\"url\":\"https://careers.usc.edu/channels/attend-career-event/\",\"title\":\"Attend a Career Event - USC Career Center\"}]},{\"id\":\"sign-up-group-fitness-class\",\"topic\":\"10\",\"name\":\"Sign up for a group fitness class (USC Workout)\",\"desc\":\"Student wants to reserve a spot in a USC Workout group exercise class (e.g., yoga, cycling, F45, boxing).\",\"system\":\"MyRecSports portal (myrecsports.usc.edu)\",\"steps\":[\"Make sure facility access is active: sign in to myrecsports.usc.edu with the USC NetID button and sign the Facility Access waivers (bell icon) if not done.\",\"Buy a USC Workout Pass: MyRecSports > Memberships & Passes > add the pass, review the amount, Checkout, pay, and finish with Continue Checkout to get an order number.\",\"Go to MyRecSports and select USC Workout Group Exercise Registration.\",\"Select the desired class, then select Register in the bottom-right corner; a confirmation email follows.\",\"Arrive 10\u201315 minutes early with proper attire and required equipment (boxing/kickboxing: own gloves and hand wraps); late entry is not permitted.\",\"To cancel: MyRecSports > your username > Program Registration > three dots on the class > Cancel Registration.\"],\"req\":[\"Active Rec Sports access (enrolled students registered in at least one unit get complimentary access).\",\"A USC Workout Pass is required to participate in classes.\",\"Classes with less than 20% enrollment 24 hours before start may be canceled (registrants notified by email).\"],\"deadlines\":[\"Mid-semester pricing for fall passes begins October 1 (fall term Aug 16 \u2013 Dec 31); spring term Jan 1 \u2013 May 15 with mid-semester pricing from March 1.\"],\"costs\":[\"USC Workout Pass (students, per Rec Sports fee table): $140 per semester; $240 Fall & Spring; $98 mid-semester; $15 per day.\"],\"fields\":[\"class name, date, time and facility\",\"whether the student already has an active USC Workout Pass\",\"pass type and price if buying one\",\"required equipment for the class\"],\"sources\":[{\"url\":\"https://recsports.usc.edu/programs-and-classes/usc-workout/\",\"title\":\"USC Workout - Recreational Sports\"},{\"url\":\"https://recsports.usc.edu/membership-information-fees/\",\"title\":\"Membership Information & Fees - Recreational Sports\"},{\"url\":\"https://recsports.usc.edu/myrecsports/getting-started-with-myrecsports/\",\"title\":\"Getting Started with MyRecSports - Recreational Sports\"}]},{\"id\":\"reserve-racquetball-court\",\"topic\":\"10\",\"name\":\"Reserve a court (Lyon Center racquetball)\",\"desc\":\"Student wants to book the Lyon Center racquetball court (other courts are open rec, first-come, first-served).\",\"system\":\"MyRecSports portal (myrecsports.usc.edu) > Rec Reservations\",\"steps\":[\"Log in to myrecsports.usc.edu.\",\"Click Rec Reservations.\",\"Under \\\"New Booking,\\\" click Racquetball Courts.\",\"Click Book Now to be scheduled for the time slot; a confirmation email is sent to your USC account.\",\"On arrival, check in at the Lyon Center Pro Shop (rackets can be checked out and balls purchased there).\",\"To cancel: Rec Reservations > three dots on the upcoming reservation > Cancel Booking > Yes, Cancel.\"],\"req\":[\"Active Rec Sports gym membership/access.\",\"One-hour slots; maximum one slot per member per day; bookable two days in advance.\",\"Court is given to walk-ups after a 10-minute grace period.\",\"Basketball, badminton, pickleball and volleyball courts are first-come, first-served open rec, not reservable this way; group rentals of Rec spaces need a Reservation Request Form submitted at least 5 weeks ahead.\",\"No-shows: after 3 no-shows, late arrivals or arrivals without requirements completed, reservation privileges are revoked for a period of time.\"],\"deadlines\":[\"Reservations can be made two days in advance.\",\"Cancel at least 2 hours before the start time (Rec Sports policy page); the Lyon Center page says reservations can be canceled any time before the start time.\"],\"costs\":[\"none stated for members (racquetball balls can be purchased at the Pro Shop; price not stated)\"],\"fields\":[\"date and one-hour time slot\",\"student has active Rec Sports access\",\"whether equipment rental is needed\",\"no other booking that day\"],\"sources\":[{\"url\":\"https://recsports.usc.edu/rec-facilities/lyon-center/\",\"title\":\"Lyon Center - Recreational Sports\"},{\"url\":\"https://recsports.usc.edu/about-us/forms-and-policies/\",\"title\":\"Forms and Policies - Recreational Sports\"},{\"url\":\"https://recsports.usc.edu/rec-facilities/facility-rentals-and-reservations/\",\"title\":\"Facility Rentals & Reservations - Recreational Sports\"}]},{\"id\":\"join-intramural-team\",\"topic\":\"10\",\"name\":\"Join an intramural team\",\"desc\":\"Student wants to play intramural sports (join or create a team in a league).\",\"system\":\"MyRecSports portal (Intramural Sports Pass) + FusionPlay app (team registration)\",\"steps\":[\"Visit the MyRecSports portal on USC Secure Wireless or cellular (not USC Guest Wireless) and log in with the red USC Net ID button.\",\"Clear all notifications on the bell icon.\",\"Select Memberships & Passes > Intramural Sports Passes; choose the duration and complete the purchase.\",\"Download the FusionPlay app (App Store or Google Play) and sign in with your USC email; complete USC Shibboleth (NetID) login and verification.\",\"In FusionPlay, open the menu (three bars) > My Profile, and set Primary ID to your 10-digit USC ID (remove the word STUDENT if present).\",\"Find a sport and team to join (within the league registration window).\"],\"req\":[\"Open to USC students, faculty and staff.\",\"Intramural Sports Pass required; one pass covers unlimited leagues for that semester/year.\",\"Follow participant guidelines (no glass, no food, arrive near assigned start time).\"],\"deadlines\":[\"Fall 2026: Basketball and Outdoor Soccer registration 8/2/26\u20139/14/26 (leagues 9/20\u201310/25/26); Flag Football and Indoor Volleyball registration 8/2/26\u201310/19/26 (leagues end 11/22/26).\",\"Spring 2027 league dates not yet posted.\"],\"costs\":[\"Intramural Sports Pass: $30 per semester or $50 Fall & Spring.\"],\"fields\":[\"sport and league session\",\"pass duration (semester vs Fall & Spring) and price\",\"team name/captain or free-agent preference\",\"student's 10-digit USC ID set in FusionPlay\",\"registration window still open\"],\"sources\":[{\"url\":\"https://recsports.usc.edu/programs-and-classes/intramural-sports/\",\"title\":\"Intramural Sports - Recreational Sports\"},{\"url\":\"https://recsports.usc.edu/membership-information-fees/\",\"title\":\"Membership Information & Fees - Recreational Sports\"}]},{\"id\":\"get-visions-and-voices-tickets\",\"topic\":\"10\",\"name\":\"Get Visions and Voices tickets\",\"desc\":\"Student wants to reserve a free ticket to a Visions and Voices arts and humanities event.\",\"system\":\"Visions and Voices website (visionsandvoices.usc.edu) event pages, RSVP link\",\"steps\":[\"Find the event on the Visions and Voices Event Calendar or homepage (filter by genre/type).\",\"Open the event page and read the ADMISSION section (e.g., open to everyone vs. USC students/faculty/staff only; reservations required).\",\"Click RSVP on the event page and complete the online reservation.\",\"If the event is full, tickets are available at event check-in on a standby basis; if it is not full, tickets are available at the door.\",\"For accommodations, contact Visions and Voices at (213) 740-0483 at least seven days before the event.\"],\"req\":[\"USC students may reserve one ticket per USC ID.\",\"Some events are open to the USC community only; some Cinematic Arts, Thornton and affiliated events have different ticketing policies.\",\"Reservations are accepted online only.\"],\"deadlines\":[\"Reservations open approximately four weeks before each event.\",\"Accommodation requests at least seven days before the event.\"],\"costs\":[\"Free for USC students (admission prices vary for non-USC attendees; most events are free to the public).\"],\"fields\":[\"event title, date and venue\",\"whether the event is USC-only\",\"number of tickets (one per USC ID)\",\"accessibility needs\"],\"sources\":[{\"url\":\"https://visionsandvoices.usc.edu/attendance-policies\",\"title\":\"Attendance Policies | USC Visions & Voices\"},{\"url\":\"https://visionsandvoices.usc.edu/events/54426797578760\",\"title\":\"Rachel Maddow in Conversation with Pete Carroll | USC Visions & Voices\"},{\"url\":\"https://visionsandvoices.usc.edu/events/54251983576635\",\"title\":\"An Evening with Jhumpa Lahiri | USC Visions & Voices\"}]},{\"id\":\"order-textbooks\",\"topic\":\"10\",\"name\":\"Order textbooks / course materials\",\"desc\":\"Student wants to get required textbooks or course materials for the term (via the Digital Course Materials Program or by buying/renting).\",\"system\":\"USC Bookstore with Follett (uscbookstore.com textbooks; Digital Course Materials Program via Brightspace \\\"My Materials\\\"; Follett opt-out portal)\",\"steps\":[\"Undergraduates: register for classes; you are automatically enrolled in the Digital Course Materials Program and receive @usc.edu emails with access details.\",\"Access required digital materials through My Materials (Course Tools) in Brightspace; access starts one week before classes.\",\"For physical materials, wait for the \\\"Your Order is Ready for Pick-Up\\\" email and pick up at the USC Bookstore (840 Childs Way), or add shipping per the Bookstore demo.\",\"If you prefer to source your own materials, opt out via the Follett opt-out portal link in your USC email before the deadline (contact the Bookstore too if you have physical materials).\",\"Graduate students, opted-out undergrads, or recommended materials: order through the USC Bookstore/Follett textbook site\u2014rent (save up to 50%) or buy\u2014and choose free in-store pickup.\",\"Questions: course materials specialists at 213-740-8398 or mymaterials@usc.edu.\"],\"req\":[\"Digital Course Materials Program applies to students with undergraduate status enrolled in courses (includes grad courses taken by undergrads, e.g., progressive degree); study abroad courses excluded.\",\"Only \\\"required\\\" materials are included; recommended materials are bought separately.\",\"Must opt out each term to be removed; no penalty for opting out.\"],\"deadlines\":[\"Opt-out by 11:59 pm PT on the last day to drop classes (Bookstore example: September 12 for Fall 2025); Registrar lists January 29, 2027 as the last day to drop a session 001 class with a refund.\"],\"costs\":[\"Digital Course Materials Program: $310.00 per semester (fall/spring); $159.50 summer.\",\"Rental/purchase prices vary by title (not stated); rentals can save up to 50% vs buying.\"],\"fields\":[\"student status (undergraduate in DCMP vs graduate)\",\"term\",\"courses and required materials\",\"opt in or opt out of DCMP\",\"pickup vs shipping for physical items\",\"rent vs buy\"],\"sources\":[{\"url\":\"https://www.uscbookstore.com/student-faq\",\"title\":\"Student FAQ (Digital Course Materials) - USC Bookstore\"},{\"url\":\"https://www.uscbookstore.com/digital-course-material\",\"title\":\"Digital Course Material - USC Bookstore\"},{\"url\":\"https://www.uscbookstore.com/textbooks\",\"title\":\"Textbooks - USC Bookstore\"},{\"url\":\"https://arr.usc.edu/registration-calendar/\",\"title\":\"Registration Calendar - Office of Academic Records and Registrar\"}]},{\"id\":\"get-commencement-guest-tickets\",\"topic\":\"10\",\"name\":\"Get commencement guest tickets\",\"desc\":\"Graduating student wants to claim and send commencement tickets to family/friends for ticketed ceremonies.\",\"system\":\"USC Ticket Office My Account (commencement mobile tickets); Additional Ticket Request Form on commencement.usc.edu\",\"steps\":[\"Confirm you are eligible to graduate (Degree Progress) and, if your school requires it, complete school ceremony registration (e.g., Viterbi via Tassel by March 31, 2027).\",\"After tickets populate (2027: by end of day Wednesday, April 21), sign in to your USC Ticket Office My Account with your USC email (password or one-time code).\",\"Open \\\"My Upcoming Events,\\\" download the tickets you need (separate tickets for each ceremony).\",\"Transfer each guest ticket to a named guest by entering their name and email or mobile phone; each guest must accept and create an account.\",\"Make sure everyone downloads mobile tickets before arriving (printed tickets are not accepted).\",\"If you need more than 10 guest tickets, submit the Additional Ticket Request Form when it opens (2026 cycle: from Monday, April 27); if tickets are missing, contact your school.\"],\"req\":[\"Tickets are only required for ceremonies at the Los Angeles Memorial Coliseum and the Shrine Auditorium; on-campus events (incl. USC Village and Galen Center) are not ticketed.\",\"Eligible graduates receive one ticket for themselves plus ten guest tickets.\",\"Tickets may not be transferred to another student; children under 2 do not need a ticket.\",\"Each ticket is individually barcoded; mobile only.\"],\"deadlines\":[\"2027: tickets populate by end of day Wednesday, April 21 (Main Stage Ceremony page).\",\"Main Stage Ceremony: Thursday, May 13, 2027, 6:30 pm, L.A. Memorial Coliseum.\",\"Additional ticket request form: 2027 opening date not yet posted (opened April 27 in the 2026 cycle).\"],\"costs\":[\"Free (tickets are free of charge).\"],\"fields\":[\"ceremony (Main Stage vs. Shrine school ceremony)\",\"number of guests (10 included)\",\"each guest's name and email or mobile number\",\"whether additional tickets are needed\",\"graduate's eligibility/registration status\"],\"sources\":[{\"url\":\"https://commencement.usc.edu/commencement-ticketing-info/\",\"title\":\"Ticketing Information - USC Commencement\"},{\"url\":\"https://commencement.usc.edu/main-stage-ceremony/\",\"title\":\"USC Commencement Main Stage Ceremony\"},{\"url\":\"https://commencement.usc.edu/commencement-ticketing-info/ticketing-support/\",\"title\":\"Ticketing Support - USC Commencement\"},{\"url\":\"https://viterbiundergrad.usc.edu/commencement/\",\"title\":\"Undergrad Commencement - USC Viterbi Current Undergraduate Students\"}]},{\"id\":\"start-new-student-organization\",\"topic\":\"10\",\"name\":\"Start a new student organization\",\"desc\":\"Student wants to create and get recognition for a brand-new RSO.\",\"system\":\"EngageSC recognition application (Campus Activities)\",\"steps\":[\"Search the EngageSC Directory/Groups with several keywords to confirm no existing page; if one exists, submit Campus Activities' form to be added as an officer (re-establishing).\",\"Recruit five officers (president, vice president, secretary, treasurer, programming chair), at least five additional student members, and a full-time USC faculty/staff advisor.\",\"Each of the five officers completes Hazing Prevention 101: Student Edition 2026-2027 and the RSO Officer Learning Path, and DocuSigns the 2026-27 Commitment to Community form; send all to the submitting officer.\",\"Prepare the Constitution and Accountability Document on the required 2026-27 fillable templates (do not flatten or print to PDF).\",\"One officer opens the EngageSC Directory from a laptop/desktop and clicks +Register a new Recognized Student Organization (religious/spiritual groups: +Register a new Office of Religious and Spiritual Life); complete roster, details and uploads, then submit.\",\"Watch email and EngageSC Chat for Campus Activities requests; the advisor submits advisor requirements via the Advisor Requirements Google Form.\"],\"req\":[\"New RSOs can only receive Spring recognition in their first year.\",\"Only an officer listed in one of the five required positions can submit; one application per student; not transferable.\",\"Advisor must be full-time USC faculty/staff not on sabbatical or leave.\",\"Group must be student-led, open to all eligible students, and in good standing.\"],\"deadlines\":[\"Spring 2027 application opened October 27; closes November 22 at 11:59 pm (late applications not accepted).\",\"Advisor requirements due December 1.\",\"Recognition lasts through June 30, 2027.\"],\"costs\":[\"none stated\"],\"fields\":[\"organization name and purpose\",\"confirmation it does not already exist on EngageSC\",\"names/USC emails of the five officers and five+ members\",\"advisor name and full-time status\",\"training/document completion status\",\"whether it is religious/spiritual (ORSL path) or a club sport (RCC)\"],\"sources\":[{\"url\":\"https://campusactivities.usc.edu/programs/recognized-student-organizations/rso-recognition-process/\",\"title\":\"Recognition Process - Campus Activities\"},{\"url\":\"https://campusactivities.usc.edu/programs/recognized-student-organizations/faq-rso-recognition-process/\",\"title\":\"FAQ - RSO Recognition Process - Campus Activities\"}]},{\"id\":\"apply-usg-funding\",\"topic\":\"10\",\"name\":\"Apply for USG funding for an RSO event\",\"desc\":\"RSO officer wants Undergraduate Student Government funding for an event or project.\",\"system\":\"USG Funding Application on EngageSC (USG Funding Department)\",\"steps\":[\"Determine funding needs and review the USG Funding Guidelines (and the Funding Guidelines Modules from RSO recognition).\",\"Choose the fund that fits (Professional & Academic; Philanthropy; Social & Recreation/Startup; Performing & Visual Arts).\",\"Open the USG Funding Application through EngageSC and complete it (a sample application is posted on the USG Funding page).\",\"Submit on a Wednesday by 11:59 PM, at least six academic weeks before the event (approved vendor) or nine academic weeks before the initial payment due date for approved USC vendors, whichever comes first.\",\"USG Funding processes payments on your behalf; email usgfunds@usc.edu with questions.\"],\"req\":[\"Applicant must be a Recognized Student Organization (or USC undergraduate for eligible projects).\",\"Up to 4 funded events per semester per RSO, under $8,000 per year from USG Funding.\",\"Funding is not guaranteed.\"],\"deadlines\":[\"Wednesdays by 11:59 PM, six academic weeks before the event date (approved vendor) / nine academic weeks before initial payment due date (approved USC vendors).\"],\"costs\":[\"none stated (department can allocate up to $356,100 across the year)\"],\"fields\":[\"RSO name and recognition status\",\"event name, date and expected attendance\",\"fund category\",\"amount requested and vendors\",\"number of events already funded this semester and year-to-date total\"],\"sources\":[{\"url\":\"https://usg.usc.edu/branches/funding/\",\"title\":\"Funding - USC Undergraduate Student Government\"}]},{\"id\":\"order-commencement-regalia\",\"topic\":\"10\",\"name\":\"Order (rent or buy) commencement regalia\",\"desc\":\"Graduating student wants to rent or purchase a cap, gown (and hood) for the 2027 ceremonies.\",\"system\":\"USC Bookstore Grad Shop (rentals/purchases fulfilled by Herff Jones); Grad Fest\",\"steps\":[\"Decide rent vs. purchase (rentals include a cap and tassel to keep; gowns/hoods are returned).\",\"Order online through the USC Bookstore graduation pages (choose school, graduation term, degree type, and exact degree for the correct hood color) or at Grad Fest (Feb 10\u201311, 2027, TCC Ballroom).\",\"Order by April 10, 2027 for free home shipping; later orders ship 2nd Day Air with an expedited fee, or pick up on campus starting May 10, 2027 on the Bookstore patio.\",\"Open the package right away to check fit, hood color and accessories.\",\"After your ceremony, return rented gowns/hoods in campus return bins (through Saturday of commencement week) or mail them to Herff Jones with the prepaid label.\"],\"req\":[\"Regalia is required to participate in ceremonies.\",\"Master's and doctoral candidates must specify their degree for the correct hood velvet color.\",\"Purchased regalia takes 6\u20138 weeks to manufacture (Bookstore FAQ).\"],\"deadlines\":[\"Free home shipping deadline: April 10, 2027; expedited fee for orders after April 11.\",\"On-campus pickup begins May 10, 2027.\",\"Current regalia offer ends December 31, 2026 (Viterbi commencement page; Bookstore graduation page lists a purchase deadline of December 31, 2026).\",\"Return rentals within 30 days of the ceremony to avoid a replacement fee.\"],\"costs\":[\"Rental/purchase prices not stated on pages read; expedited shipping fee applies after April 11; unreturned gown = replacement fee equal to full purchase price.\"],\"fields\":[\"degree level and exact degree (hood color)\",\"rent or purchase\",\"ship to home vs on-campus pickup\",\"graduation term and school\",\"note: rentals come with a one-size SureFit cap (cap size not needed)\"],\"sources\":[{\"url\":\"https://commencement.usc.edu/faq/\",\"title\":\"Commencement FAQ\"},{\"url\":\"https://commencement.usc.edu/graduates/caps-and-gowns-regalia/\",\"title\":\"USC Regalia\"},{\"url\":\"https://commencement.usc.edu/graduates/\",\"title\":\"For Graduates - USC Commencement\"},{\"url\":\"https://viterbiundergrad.usc.edu/commencement/\",\"title\":\"Undergrad Commencement - USC Viterbi Current Undergraduate Students\"}]},{\"id\":\"request-religious-accommodation\",\"topic\":\"10\",\"name\":\"Request a religious accommodation for class\",\"desc\":\"Student needs to miss class or reschedule an exam/assignment for a religious observance.\",\"system\":\"ORSL Request for Religious Accommodation Form + direct request to the instructor\",\"steps\":[\"Review your syllabi at the start of the semester for conflicts with observances.\",\"Fill out the Request for Religious Accommodation Form (optional ORSL resource) and share it with the individual or office specified on the form, then reach out to your faculty member as soon as possible.\",\"Contact your professor as early as possible\u2014at least two weeks in advance\u2014to arrange make-up work, a rescheduled exam, or other accommodation.\",\"For observances longer than two days, contact ORSL for advice and support ((213) 740-6110, orsl@usc.edu); ORSL can step in as an alternative exam proctor. If you believe your religious rights were violated, contact the Office of Civil Rights Compliance.\"],\"req\":[\"University policy covers excused absences for holy days lasting up to two days.\",\"No proof of religious belief is required, but you may be asked to describe the belief requiring accommodation.\",\"Requests not made in advance may not be granted; accommodations that impose undue burden may be denied.\"],\"deadlines\":[\"At least two weeks before the observance (ORSL guidance); ideally at the start of the semester.\"],\"costs\":[\"none (USC may not charge for reasonable religious accommodations)\"],\"fields\":[\"course(s) and instructor(s)\",\"date(s) of the observance\",\"type of accommodation requested (absence, exam reschedule, prayer break)\",\"how far in advance the request is\"],\"sources\":[{\"url\":\"https://orsl.usc.edu/faq-frequently-asked-questions/\",\"title\":\"FAQ: Frequently Asked Questions - Office of Religious and Spiritual Life\"},{\"url\":\"https://orsl.usc.edu/policy-on-the-observance-of-holy-days/\",\"title\":\"Policy on the Observance of Holy Days - Office of Religious and Spiritual Life\"},{\"url\":\"https://orsl.usc.edu/\",\"title\":\"Office of Religious and Spiritual Life\"}]},{\"id\":\"join-club-sport\",\"topic\":\"10\",\"name\":\"Join a club sport\",\"desc\":\"Student wants to join an intercollegiate Club Sports team (e.g., club soccer, ultimate, volleyball).\",\"system\":\"Club contact email + MyRecSports (Club Sports Pass) + Fusion Club registration\",\"steps\":[\"Contact the specific club (emails listed on the Rec Sports Club Sports page) for tryout or joining procedures.\",\"Once you have joined the club, log in to MyRecSports with the red USC Net ID button and clear bell notifications.\",\"Select Memberships & Passes > Club Sports Pass; choose duration and complete purchase.\",\"Visit the Fusion Club website, enter your USC email and log in with your USC NetID.\",\"Select your club and complete registration (approval only after the pass is purchased).\",\"Complete any required ImPACT concussion baseline test if your club is on the required list.\"],\"req\":[\"Must have active Rec Sports access/membership.\",\"All club participants must purchase the Club Sports Pass prior to approval on Fusion Club.\",\"Follow Rec Sports facility policies, RCC Constitution and USC Club Sports Bylaws; all travel must be approved by Rec Sports.\"],\"deadlines\":[\"Not stated; depends on each club's tryout/joining schedule.\"],\"costs\":[\"Club Sports Pass: $25 (Fall & Spring); clubs may also charge member dues (amounts not stated).\"],\"fields\":[\"club name\",\"tryout/acceptance status from the club\",\"pass purchase confirmation\",\"ImPACT test requirement for that club\"],\"sources\":[{\"url\":\"https://recsports.usc.edu/programs-and-classes/club-sports/\",\"title\":\"Club Sports - Recreational Sports\"},{\"url\":\"https://recsports.usc.edu/membership-information-fees/\",\"title\":\"Membership Information & Fees - Recreational Sports\"}]},{\"id\":\"volunteer-trojan-food-pantry\",\"topic\":\"10\",\"name\":\"Sign up to volunteer at the Trojan Food Pantry\",\"desc\":\"Student wants to volunteer shifts at the Trojan Food Pantry.\",\"system\":\"Student Basic Needs volunteer interest form, training sign-up and shift sign-up link\",\"steps\":[\"Complete the Trojan Food Pantry volunteer interest form on the Student Basic Needs site.\",\"Sign up for a 30-minute training session (pantry walk-through, program details, food safety guidelines, Q&A).\",\"Use the sign-up link you receive after training to choose volunteer shifts.\"],\"req\":[\"Open to registered USC students only (staff, faculty and groups email basicneeds@usc.edu).\"],\"deadlines\":[\"not stated on USC sites\"],\"costs\":[\"none stated\"],\"fields\":[\"student is currently registered\",\"training session date/time\",\"shift preferences\"],\"sources\":[{\"url\":\"https://studentbasicneeds.usc.edu/get-involved/\",\"title\":\"Get Involved & Volunteer - Student Basic Needs\"}]},{\"id\":\"request-travel-signature\",\"topic\":\"11\",\"name\":\"Request a travel signature on your I-20 or DS-2019\",\"desc\":\"Get an OIS travel endorsement on your I-20/DS-2019 so you can reenter the U.S. after traveling abroad (e.g., over winter break).\",\"system\":\"Trojan International (trojaninternational.ois.usc.edu, USC NetID login) \u2014 F-1: Travel Signature I-20 Request; J-1 students: Student Travel Signature Request; J-1 scholars: Scholar Travel Signature Request\",\"steps\":[\"Check the travel endorsement already on your form (I-20 page 2 or 3; DS-2019 bottom-right of page 1). If your reentry date will be within 12 months of the last signature (six months if on Post-Completion OPT or STEM OPT), you do not need a new one.\",\"Log in to Trojan International with your USC NetID.\",\"F-1 students: submit the Travel Signature I-20 Request. J-1 students: submit the Student Travel Signature Request (J-1 scholars use the Scholar Travel Signature Request).\",\"Dependents: OIS automatically includes travel endorsements for J-2 records with the J-1 request; F-2 dependents need the F-1 student to submit the I-20 Request for them.\",\"Allow seven business days for processing and submit before you leave the U.S. if possible.\",\"OIS signs the I-20/DS-2019 electronically and emails it to your USC email account.\",\"Print it and hand-sign page 1 (electronic signatures are not allowed), then carry it with your other reentry documents (passport valid at least six months beyond reentry, valid visa, financial support documents).\",\"If you reenter without a valid signature, you will likely receive an I-515A (30-day stay); contact OIS immediately after arrival.\"],\"req\":[\"A travel signature is required to reenter the U.S., not to depart.\",\"Validity: 12 months for enrolled students; six months for F-1 students on Post-Completion OPT or STEM OPT; J-1 short-term scholars six months or until program end, whichever is sooner.\",\"Not needed for the first entry on a new USC I-20 or on a Transfer Pending I-20.\",\"Recently issued CPT I-20s and J-1 Academic Training DS-2019s already include a valid travel signature; extended DS-2019s are endorsed for travel as a courtesy.\",\"Only OIS Designated School Officials (F-1) or Alternate Responsible Officers (J-1) may sign.\"],\"deadlines\":[\"Processing time: seven business days.\",\"Request before departing the U.S. if possible.\"],\"costs\":[\"No fee stated on USC sites for enrolled students.\",\"For STEM OPT students, the one-time $200 OIS STEM OPT fee covers services that include I-20 travel endorsements.\"],\"fields\":[\"F-1 or J-1 (student or scholar)\",\"Current status: enrolled, Post-Completion OPT, or STEM OPT\",\"Date of the most recent travel signature on the form\",\"Planned departure and reentry dates\",\"Whether F-2/J-2 dependents also need endorsements\",\"USC email address where the signed form will be sent\"],\"sources\":[{\"url\":\"https://ois.usc.edu/travel/requirements-for-reentry/\",\"title\":\"Requirements for Reentry - USC OIS\"},{\"url\":\"https://ask.usc.edu/s/article/000002953\",\"title\":\"I received my new USC I-20 and it doesn't have a travel signature. Do I need a travel signature to enter the U.S.?\"},{\"url\":\"https://ois.usc.edu/important-travel-reminders-for-winter-recess-2025/\",\"title\":\"International Student Travel Reminders: Winter Recess 2024 | USC OIS\"},{\"url\":\"https://ois.usc.edu/employment/stem-opt-extension/\",\"title\":\"STEM OPT Extension - USC OIS\"}]},{\"id\":\"apply-for-post-completion-opt\",\"topic\":\"11\",\"name\":\"Apply for Post-Completion OPT\",\"desc\":\"Get an OPT recommendation I-20 from OIS and file Form I-765 with USCIS to work in the U.S. for up to 12 months after graduating.\",\"system\":\"Trojan International (OPT I-20 Request) for the OIS recommendation, then the USCIS myUSCIS online account (Form I-765)\",\"steps\":[\"Confirm your graduation eligibility with your academic department. If you are graduating before your I-20 end date, first submit the SEVIS Final Semester Check so OIS shortens the end date.\",\"Within your request window (as early as 90 days before your I-20 program end date, no later than 45 days after completing your degree), submit the OPT I-20 Request in Trojan International.\",\"In the request, pass the five short assessments, enter a preferred OPT start date (1 to 60 days after your program end date) and your academic advisor\u2019s name and email. USC Viterbi graduate students also provide the Graduation Verification Form from myViterbi.\",\"Your advisor confirms your graduation date; OIS then processes the request in 10 business days and emails the OPT I-20 to your USC email (incomplete requests restart the clock).\",\"Print the OPT I-20 and sign and date it by hand in black ink.\",\"File Form I-765 online in your myUSCIS account within 30 days of the OPT I-20 issue date and no later than 60 days after your program end date (by 23:59 UTC), while physically in the U.S. Upload the signed OPT I-20, supporting documents and two passport-style photos, and pay the non-refundable filing fee (Premium Processing optional).\",\"Keep the I-797C receipt notice. If USCIS sends any rejection, RFE, NOID, denial or biometrics/photo notice, submit the Request to Review USCIS Notice in Trojan International before responding.\",\"After approval, wait for the physical EAD card; begin work only on or after the EAD start date.\",\"Report employment (OPT Employment Update) and address changes in Trojan International within 10 days.\"],\"req\":[\"Maintained F-1 status for at least one academic year (two consecutive semesters, not including summer).\",\"Graduation eligibility confirmed with your academic department before starting.\",\"Fewer than 12 months of full-time CPT at the current degree level (part-time CPT does not count).\",\"No prior OPT at the same or a higher degree level.\",\"Must be physically in the U.S. when filing Form I-765.\",\"A job or job offer is not required to apply.\",\"Once on OPT: work directly related to your major, at least 20 hours per week, no more than 90 days of unemployment.\"],\"deadlines\":[\"OPT I-20 request: as early as 90 days before the I-20 program end date; latest 45 days after completing the degree program.\",\"Fall 2026 graduates (program end date Dec. 16, 2026): OPT I-20 request window Sept. 17, 2026 \u2013 Jan. 30, 2027; requested start date Dec. 17, 2026 \u2013 Feb. 14, 2027.\",\"Form I-765: within 30 days of the OPT I-20 issue date and no more than 60 days after the program end date (USCIS deadline is 23:59 UTC).\",\"OIS processing: 10 business days after the academic advisor completes their portion.\",\"USCIS processing: approximately three to four months (Premium Processing: response within 30 business days).\",\"Report employment and address changes within 10 days.\"],\"costs\":[\"Non-refundable USCIS Form I-765 filing fee (amount not stated on OIS pages; paid by credit or debit card).\",\"Optional USCIS Premium Processing for an additional fee (amount not stated on USC sites).\",\"OIS fee for the Post-Completion OPT I-20: none stated on USC sites.\",\"A proposed $70,000 USCIS fee for initial OPT applications is not final; current filing fees remain unchanged.\"],\"fields\":[\"Degree level and I-20 program end date\",\"Graduation confirmed with department; early graduation (SEVIS Final Semester Check submitted?)\",\"Requested OPT start date (1\u201360 days after program end date)\",\"Academic advisor name and email (Viterbi: Graduation Verification Form)\",\"Prior CPT/OPT history at this degree level and all SEVIS IDs\",\"Physically in the U.S. at the time of filing\",\"Reliable U.S. mailing address for the EAD\",\"Whether to request Premium Processing\"],\"sources\":[{\"url\":\"https://ois.usc.edu/employment/post-completion-opt/\",\"title\":\"Post-Completion OPT - USC OIS\"},{\"url\":\"https://ois.usc.edu/update-regarding-proposed-opt-fees/\",\"title\":\"Update Regarding Proposed OPT Fees | USC OIS\"}]},{\"id\":\"request-cpt-authorization\",\"topic\":\"11\",\"name\":\"Request CPT authorization (CPT I-20)\",\"desc\":\"Get Curricular Practical Training authorization from OIS for a required off-campus internship or practicum during your degree.\",\"system\":\"Trojan International \u2014 CPT I-20 Request (USC Viterbi graduate students: CPT I-20 Request for Viterbi Graduate Students), with academic advisor/internship coordinator approval\",\"steps\":[\"Confirm with your department that the internship or practicum is a required part of your degree for all students in the program (OIS authorizes CPT only when practical training is a degree requirement for graduation, effective Aug. 24, 2026).\",\"Secure a specific internship offer directly related to your major from an employer with a U.S. physical presence.\",\"Register in the required internship course, if your program requires one. If D-Clearance is required, your academic advisor or internship coordinator gives it when signing your CPT I-20 Request (OIS\u2019s steps place registration later in the process).\",\"Complete the CPT I-20 Request in Trojan International and attach the internship offer letter and a copy of the cooperative agreement between your school and the sponsoring employer.\",\"Your academic advisor or internship coordinator signs the CPT I-20 Request (and gives D-Clearance if applicable).\",\"OIS emails an electronically signed CPT I-20 within four business days; check the CPT authorization and employer details on page 2 or 3.\",\"If you need an SSN, schedule an appointment at the Social Security Administration office (1122 W. Washington Blvd.) \u2014 no OIS letter is needed on approved CPT.\",\"Do not start work until you have the CPT I-20 and the employment start date has arrived. Apply again each semester and for any new employer; keep every CPT I-20.\"],\"req\":[\"Practical training must be an integral, required part of the established curriculum for all students in the program; optional internships and electives do not qualify.\",\"Properly maintained F-1 status and full-time enrollment in the CPT semester (final-semester exception).\",\"At least one academic year in F-1 status in a degree program (exceptions: SEVIS transfers in; programs requiring first-year internships).\",\"Employer must have a U.S.-based office/operations and a physical address.\",\"Part-time (20 hours/week or fewer) during fall and spring; full-time only in summer, a half-time final semester, or PharmD APPE placements.\",\"Successful completion of all internship courses is required for current and future CPT.\",\"12 or more months of full-time CPT at a degree level eliminates OPT eligibility at that level.\",\"USC International Academy students are not eligible.\"],\"deadlines\":[\"Application deadline: the last add/drop date of the semester, unless the department grants special permission to add the internship course (Spring 2027 session 001: Jan. 29, 2027 is the last day to register/add).\",\"Spring 2027 CPT dates (OIS guidance, not guaranteed): Jan. 11, 2027 \u2013 May 14, 2027.\",\"Summer 2027 CPT dates: May 17 \u2013 Aug. 10, 2027 (final semester) or May 17 \u2013 Aug. 20, 2027 (not final semester).\",\"OIS processing: within four business days.\"],\"costs\":[\"none stated on USC sites\"],\"fields\":[\"Semester and requested CPT start/end dates\",\"Employer name and U.S. worksite address (U.S. physical presence)\",\"Part-time or full-time hours\",\"Required internship course and units; D-Clearance needed?\",\"Confirmation that the internship is required for all students in the program\",\"Academic advisor or internship coordinator name\",\"Final semester or not\",\"One-academic-year eligibility or applicable exception\"],\"sources\":[{\"url\":\"https://ois.usc.edu/employment/curricular-practical-training-cpt/\",\"title\":\"Curricular Practical Training (CPT) - USC OIS\"},{\"url\":\"https://ois.usc.edu/important-update-regarding-curricular-practical-training/\",\"title\":\"Important Update About CPT Requirements | USC OIS\"},{\"url\":\"https://arr.usc.edu/registration-calendar/\",\"title\":\"Registration Calendar - Office of Academic Records and Registrar\"},{\"url\":\"https://ois.usc.edu/employment/social-security-number/\",\"title\":\"Social Security Number - USC OIS\"}]},{\"id\":\"request-i20-program-extension\",\"topic\":\"11\",\"name\":\"Request an I-20 (or DS-2019) program extension\",\"desc\":\"Extend the program end date on your I-20/DS-2019 when you need more time to finish your degree.\",\"system\":\"Trojan International \u2014 Program Extension I-20 Request (USC Viterbi graduate students: Program Extension I-20 Request for Viterbi Graduate Students, after getting an Academic Verification Form in myViterbi); J-1: Program Extension DS-2019 Request\",\"steps\":[\"Check the program end date on page 1 of your I-20/DS-2019. If it has already passed, meet with an OIS advisor immediately (you are out of status).\",\"Confirm a qualifying reason: medical reasons, change of major, change in research topic, unexpected research problems, or other compelling academic reasons specified by your advisor.\",\"USC Viterbi graduate students: request an Academic Verification Form (AVF) in the MyViterbi portal and download the approved PDF.\",\"Submit the Program Extension I-20 Request in Trojan International with your name as on your passport, USC email, and your academic advisor\u2019s name and email; attach supporting documents (medical letter; both advisors\u2019 signatures for double majors; a department letter of support after a second extension; the AVF for Viterbi).\",\"Click \u201cfinish\u201d \u2014 the form routes to your academic (or VGASP) advisor and then to OIS.\",\"OIS processes the request in 10 business days and emails the electronically signed extended I-20.\",\"J-1 students: submit the Program Extension DS-2019 Request with advisor approval and funding documentation; print and hand-sign page 1 of the e-signed DS-2019 (extended DS-2019s are endorsed for travel).\"],\"req\":[\"The I-20/DS-2019 expiration date has not passed.\",\"You have continuously maintained F-1/J-1 status.\",\"Delay due to medical reasons (MD, DO or licensed clinical psychologist documentation), change of major, change in research topic, unexpected research problems, or other compelling academic reasons.\",\"Program extensions are not granted for CPT purposes, and may affect Pre-Completion OPT, CPT or Academic Training eligibility.\",\"J-1 students must provide funding documentation.\"],\"deadlines\":[\"Submit no later than one month before the I-20 expiration date (and always before the program end date).\",\"Viterbi AVF requests are reviewed after the last add/drop date of each semester.\",\"OIS processing: 10 business days.\"],\"costs\":[\"none stated on USC sites\"],\"fields\":[\"Current I-20/DS-2019 program end date\",\"New expected completion term/date\",\"Reason for the extension\",\"Academic advisor name and email (Viterbi: AVF obtained)\",\"Supporting documents (medical letter, double-major signatures, letter of support if past the second extension)\",\"Number of prior extensions\",\"J-1: funding documentation\"],\"sources\":[{\"url\":\"https://ois.usc.edu/maintaining-status/extending-program-students/\",\"title\":\"Extending Your Program (Students) - USC OIS\"},{\"url\":\"https://ois.usc.edu/employment/curricular-practical-training-cpt/\",\"title\":\"Curricular Practical Training (CPT) - USC OIS\"}]},{\"id\":\"request-reduced-course-load\",\"topic\":\"11\",\"name\":\"Request a Reduced Course Load (RCL)\",\"desc\":\"Get OIS authorization to enroll below full time for first-semester academic difficulty or a medical reason (or confirm final-semester under-enrollment).\",\"system\":\"Trojan International \u2014 F-1 Reduced Course Load (RCL) Request for Academic Difficulty/Medical Reasons or the J-1 version; final-semester under-enrollment uses the SEVIS Final Semester Check\",\"steps\":[\"Identify the exception: first-semester academic difficulty, Medical RCL, or final semester (final semester uses the SEVIS Final Semester Check instead of an RCL request).\",\"For a Medical RCL, get a signed letter on official letterhead from a licensed MD, DO or clinical psychologist that recommends a reduced load for the semester and confirms U.S. treatment.\",\"Submit the F-1 or J-1 RCL Request for Academic Difficulty/Medical Reasons in Trojan International by the end of the second week of classes.\",\"The request routes to your academic advisor (or VGASP advisor for Viterbi graduate students) for approval, then automatically to OIS for final review.\",\"Stay enrolled full time until you receive OIS\u2019s approval email; then adjust to the approved load (academic difficulty RCL: at least 6/4/3 units).\",\"For a 0-unit Medical RCL, also complete your department\u2019s Leave of Absence procedures; request a new Medical RCL each semester if needed.\"],\"req\":[\"Academic difficulty RCL: first semester only, once per degree level, for improper course level placement, reading requirements, English language difficulty or unfamiliarity with U.S. teaching methods.\",\"Half-time minimum for academic RCL: 6 units undergraduate, 4 units graduate, 3 units doctoral.\",\"Medical RCL: remain in the U.S. and be treated by a qualified U.S. provider, intend to resume studies, no more than three semesters (12 months) per degree level, approved one semester at a time.\",\"Department approval and OIS approval are both required before dropping below full time; department approval or an LOA01 hold alone does not authorize an RCL.\",\"J-1 students sponsored by outside organizations (e.g., IIE) get RCL authorization from their sponsor.\",\"Thesis/dissertation/qualifying exam courses (594, 794, 800) already count as full time \u2014 no RCL needed.\"],\"deadlines\":[\"Submit by the end of the second week of classes.\",\"OIS approval must be received before dropping below full-time enrollment.\"],\"costs\":[\"none stated on USC sites\"],\"fields\":[\"RCL type (academic difficulty, medical, or final semester)\",\"Semester\",\"Current and intended units\",\"Academic or VGASP advisor\",\"Medical documentation and treatment location (U.S.)\",\"Number of prior Medical RCL semesters at this degree level\",\"Impact on on-campus employment (payroll minimum units)\"],\"sources\":[{\"url\":\"https://ois.usc.edu/maintaining-status/reduced-course-load/\",\"title\":\"Reduced Course Load - USC OIS\"}]},{\"id\":\"meet-ois-advisor-drop-in\",\"topic\":\"11\",\"name\":\"Meet with an OIS advisor (drop-in Zoom advising)\",\"desc\":\"Talk one-on-one with an OIS immigration advisor about an F-1/J-1 question (OIS advising is drop-in; no appointment booking is described).\",\"system\":\"OIS Drop-In Advising on Zoom (\u201cJoin Drop-In Advising\u201d link on ois.usc.edu/contact); askOIS Contact Form for written general/F-1 questions; j1student@usc.edu for J-1 students; Tommy chatbot for general questions\",\"steps\":[\"Decide whether you need F-1 or J-1 advising.\",\"Check hours on the OIS contact page: F-1 advising Monday\u2013Friday 1\u20133 p.m.; J-1 advising Tuesdays and Wednesdays 1\u20133 p.m. Watch for special notices (on Monday, Nov. 9, 2026, advising runs 2\u20134 p.m. in observance of GlobeFeast).\",\"Join the Zoom room through the \u201cJoin Drop-In Advising\u201d link on the contact page before access closes (2:30 p.m. on regular days).\",\"For non-urgent written questions, submit the askOIS Contact Form (general and F-1) or email j1student@usc.edu (J-1 students); J-1 scholars email j1scholar@usc.edu.\",\"For quick general questions, ask Tommy (lower-right corner of the OIS website) and verify important answers with an advisor.\"],\"req\":[\"No appointment is needed \u2014 advisors meet students via Zoom on a drop-in basis.\",\"OIS is closed on university-observed holidays and official closures; drop-in advising resumes the next university business day.\",\"Some processes require meeting an advisor first (e.g., Pre-Completion OPT eligibility, change of status to F-1, STEM OPT based on a prior degree).\"],\"deadlines\":[\"F-1: Monday\u2013Friday 1\u20133 p.m.; J-1: Tuesdays and Wednesdays 1\u20133 p.m.; Zoom room access closes at 2:30 p.m.\",\"Monday, Nov. 9, 2026: advising 2\u20134 p.m. (GlobeFeast).\"],\"costs\":[\"none stated on USC sites\"],\"fields\":[\"F-1 or J-1 (student or scholar)\",\"Topic of the question\",\"Whether the student can join during the drop-in window (Pacific time) on an OIS business day\",\"Whether a written askOIS / j1student@usc.edu question is sufficient instead\"],\"sources\":[{\"url\":\"https://ois.usc.edu/contact/\",\"title\":\"Contact OIS - USC OIS\"},{\"url\":\"https://ois.usc.edu/important-travel-update-for-f-1-and-j-1-international-students-and-scholars/\",\"title\":\"F-1 & J-1 International Students & Scholars Travel Update | USC OIS\"},{\"url\":\"https://ois.usc.edu/meet-tommy-your-virtual-assistant/\",\"title\":\"Meet Tommy: Your Virtual Assistant | USC OIS\"},{\"url\":\"https://ois.usc.edu/maintaining-status/change-of-status-f1/\",\"title\":\"Change of Status to F-1 - USC OIS\"}]},{\"id\":\"update-us-address-sevis\",\"topic\":\"11\",\"name\":\"Update your U.S. address (SEVIS and USC records)\",\"desc\":\"Report a new U.S. address within 10 days of moving so SEVIS and USC have it on file.\",\"system\":\"Trojan International \u2014 SEVIS U.S. Address and Contact Update form (updates SEVIS); Experience USC (updates the registrar\u2019s records)\",\"steps\":[\"Log in to Trojan International and open the SEVIS U.S. Address and Contact Update form (linked from OIS\u2019s Forms page).\",\"Enter the street number and name only in \u201cstreet address\u201d (e.g., 2700 Ellendale), only the unit in \u201capartment, suite, etc.\u201d (blank for a house), the city, and a five-digit ZIP code; verify with Google Maps if unsure.\",\"Submit, then also update your address in Experience USC.\",\"On OPT/STEM OPT: if your work location changes too, submit the OPT or STEM OPT Employment Update separately (an address update does not update employment).\",\"If a USCIS application (e.g., STEM OPT) is pending, also file the online USCIS Change of Address form.\"],\"req\":[\"Applies to all F-1/J-1 students, including those on OPT, STEM OPT or Academic Training.\",\"Graduates on OPT, STEM OPT or Academic Training must keep their address current in Trojan International.\"],\"deadlines\":[\"Within 10 days of moving.\"],\"costs\":[\"none stated on USC sites\"],\"fields\":[\"New street address, unit, city and five-digit ZIP\",\"Move date\",\"Phone number\",\"Whether on OPT/STEM OPT (employment update also needed?)\",\"Whether a USCIS application is pending (USCIS change of address)\"],\"sources\":[{\"url\":\"https://ois.usc.edu/maintaining-status/guidelines-maintaining-status/\",\"title\":\"Guidelines for Maintaining Status - USC OIS\"},{\"url\":\"https://ois.usc.edu/forms/\",\"title\":\"Forms - USC OIS\"},{\"url\":\"https://ois.usc.edu/employment/stem-opt-extension/\",\"title\":\"STEM OPT Extension - USC OIS\"},{\"url\":\"https://ois.usc.edu/employment/post-completion-opt/\",\"title\":\"Post-Completion OPT - USC OIS\"}]},{\"id\":\"submit-sevis-final-semester-check\",\"topic\":\"11\",\"name\":\"Submit the SEVIS Final Semester Check\",\"desc\":\"Tell OIS you are in your final semester and need fewer than full-time units (or are graduating before your I-20/DS-2019 end date).\",\"system\":\"Trojan International \u2014 SEVIS Final Semester Check (F-1) / SEVIS Final Semester Check (For under-enrollment in final term) (J-1)\",\"steps\":[\"Identify all remaining degree requirements for your final semester (the check confirms your final-semester status and the remaining courses needed).\",\"Enroll in all remaining degree requirements for the semester; if only one course remains, it cannot be online (OIS\u2019s RCL page says in person, even in summer; the Guidelines page says in person or hybrid).\",\"Submit the SEVIS Final Semester Check in Trojan International by the end of the second week of classes.\",\"If graduating before your I-20/DS-2019 end date, OIS shortens the end date, which starts your grace period (and must happen before you request an OPT I-20).\",\"If you work on campus below the payroll minimum units, ask your academic advisor to update your STARS report (degree check in SIS) so USC Payroll can process you \u2014 a separate process that can take about 24\u201348 hours to reach Payroll.\"],\"req\":[\"Only for the final semester, when a full course load is not needed to complete the degree.\",\"Must be enrolled in all remaining degree requirements; a single remaining course cannot be online.\",\"Summer-final students who do not need a full load must also submit it.\"],\"deadlines\":[\"By the end of the second week of classes.\"],\"costs\":[\"none stated on USC sites\"],\"fields\":[\"Final term\",\"Remaining required courses and units\",\"Instruction mode if only one course remains\",\"Graduating before the I-20/DS-2019 end date?\",\"On-campus job (STARS report update needed?)\"],\"sources\":[{\"url\":\"https://ois.usc.edu/maintaining-status/reduced-course-load/\",\"title\":\"Reduced Course Load - USC OIS\"},{\"url\":\"https://ois.usc.edu/maintaining-status/program-completion-students/\",\"title\":\"Program Completion (Students) - USC OIS\"},{\"url\":\"https://ois.usc.edu/employment/on-campus-employment/\",\"title\":\"On-Campus Employment - USC OIS\"},{\"url\":\"https://ois.usc.edu/employment/post-completion-opt/\",\"title\":\"Post-Completion OPT - USC OIS\"}]},{\"id\":\"request-ssn-eligibility-letter\",\"topic\":\"11\",\"name\":\"Request an SSN eligibility letter (on-campus job)\",\"desc\":\"Get the OIS letter needed to apply for a Social Security number after receiving an on-campus job offer.\",\"system\":\"Trojan International \u2014 Social Security Number (SSN) Letter Request (J-1 students: SSN Eligibility Letter J-1 Students); then an in-person Social Security Administration appointment\",\"steps\":[\"Get an employment letter from your hiring manager on official letterhead with all required items (date, passport name, employer/department, supervisor name/title/phone, job title, duties, start date, weekly hours, pay rate, EIN \u2014 USC is 95-1642394 \u2014 and a wet ink signature with the signer\u2019s typed name/title).\",\"If you are a new student, wait 10 business days after your U.S. entry date (on your I-94).\",\"Submit the SSN Eligibility Letter Request in Trojan International with complete, accurate information.\",\"OIS processes within up to four business days and emails you when the letter is ready for pickup.\",\"Schedule an in-person SSA appointment no more than 30 days before your job start date (closest to UPC: 1122 W. Washington Blvd., Second Floor; 1-800-772-1213).\",\"Bring originals: OIS letter, employment letter, completed Form SS-5, passport with visa, I-20/DS-2019 and most recent I-94.\"],\"req\":[\"Valid employment authorization (an on-campus job offer) is required to get an SSN.\",\"Not needed for students on approved CPT, applying for or on OPT, or J-1 scholars.\",\"F-2 dependents are not eligible for an SSN.\"],\"deadlines\":[\"New students: wait 10 business days after U.S. entry before requesting the letter.\",\"OIS processing: up to four business days (cannot be expedited).\",\"SSA appointment: no more than 30 days before the employment start date.\"],\"costs\":[\"SSN application is free of charge.\"],\"fields\":[\"Job offer details and that the employment letter meets all requirements\",\"U.S. entry date (I-94)\",\"Employment start date\",\"F-1 or J-1\",\"Preferred SSA office (UPC or HSC)\"],\"sources\":[{\"url\":\"https://ois.usc.edu/employment/social-security-number/\",\"title\":\"Social Security Number - USC OIS\"},{\"url\":\"https://ois.usc.edu/forms/\",\"title\":\"Forms - USC OIS\"}]},{\"id\":\"request-sevis-transfer-out\",\"topic\":\"11\",\"name\":\"Request a SEVIS transfer out to another school\",\"desc\":\"Release your USC SEVIS record to a new U.S. school so it can issue your transfer I-20/DS-2019.\",\"system\":\"Trojan International \u2014 F-1 SEVIS Transfer Out Request / J-1 SEVIS Transfer Out Request\",\"steps\":[\"Get admitted to the new school and discuss your program start date, travel plans and proposed SEVIS release date with its international student office.\",\"If on OPT, report your employment end date through the OPT Employment Update before requesting the transfer; if ending STEM OPT early for a transfer, submit the STEM OPT Extension Final I-983 Self-Evaluation Report.\",\"J-1 students: meet with a J-1 advisor.\",\"Submit the F-1 or J-1 SEVIS Transfer Out Request in Trojan International.\",\"Allow 4 business days (F-1) or 10 business days (J-1); you receive emails at submission and when processed.\",\"Forward OIS\u2019s confirmation email to the new school in place of a transfer verification form.\",\"If traveling abroad before the new program, make sure the record is released before you depart and reenter on the new school\u2019s Transfer-Pending I-20.\"],\"req\":[\"Valid F-1/J-1 status with an active SEVIS record.\",\"New program must start within five months of your last USC enrollment date (on OPT/STEM OPT: within five months of transfer-out or the end of OPT, whichever is earlier).\",\"OPT: all reporting completed and no more than 90 days unemployment; STEM OPT: Form I-983 final self-evaluation submitted and no more than 150 days unemployment.\",\"Do not transfer while an OPT/STEM OPT application is pending; OPT/STEM OPT work authorization ends on the SEVIS release date.\",\"Transfers are final once released.\"],\"deadlines\":[\"Continuing students: after the current semester end date and before the next USC semester starts.\",\"Graduating students: during the 60-day grace period.\",\"Processing: four business days (F-1), 10 business days (J-1).\"],\"costs\":[\"none stated on USC sites\"],\"fields\":[\"New school name and program start date\",\"Requested SEVIS release date\",\"Current status (enrolled, graduated, on OPT/STEM OPT)\",\"Employment end date reported (if on OPT/STEM OPT)\",\"International travel plans before the new program\"],\"sources\":[{\"url\":\"https://ois.usc.edu/maintaining-status/attending-another-institution/\",\"title\":\"Attending Another Institution - USC OIS\"},{\"url\":\"https://ois.usc.edu/employment/post-completion-opt/\",\"title\":\"Post-Completion OPT - USC OIS\"},{\"url\":\"https://ois.usc.edu/employment/stem-opt-extension/\",\"title\":\"STEM OPT Extension - USC OIS\"},{\"url\":\"https://ois.usc.edu/maintaining-status/program-completion-students/\",\"title\":\"Program Completion (Students) - USC OIS\"}]},{\"id\":\"request-leave-of-absence-ois\",\"topic\":\"11\",\"name\":\"Request a Leave of Absence (OIS)\",\"desc\":\"Take an approved semester off from USC while protecting your ability to return in F-1/J-1 status.\",\"system\":\"Academic department (undergraduates declare via MyUSC; Viterbi graduate students via VGASP) plus Trojan International \u2014 Leave of Absence (LOA) Request for F-1 or J-1 students\",\"steps\":[\"Confirm eligibility with your academic department (undergraduates also declare the leave via MyUSC; Viterbi graduate students consult VGASP; assistantship holders discuss their position).\",\"Submit the OIS Leave of Absence Request in Trojan International; your academic advisor signs it and it routes back to OIS.\",\"Make sure OIS receives the signed request by the first day of the semester; OIS processes it in 10 business days and emails approval.\",\"OIS terminates your SEVIS record for \u201cAuthorized Early Withdrawal\u201d on the last add/drop date; depart the U.S. within 15 days and stay abroad for the whole leave.\",\"An OIS55 hold blocks schedule changes until you return; to come back, request SEVIS reactivation (no earlier than 60 days before the return semester) or a Return to USC: Initial I-20.\"],\"req\":[\"Good academic and immigration standing (undergraduate GPA at least 2.0; graduate at least 3.0).\",\"Intend to return; depart and remain abroad for the entire leave.\",\"Approval from both the academic department and OIS before the semester starts.\",\"Not available to first-semester students, for late-semester withdrawals, to stay in the U.S. for treatment, to switch programs, or to work.\"],\"deadlines\":[\"OIS must receive the advisor-signed request by the first day of the semester.\",\"Depart within 15 days of the last add/drop date (SEVIS termination date).\",\"OIS processing: 10 business days.\"],\"costs\":[\"none stated on USC sites\"],\"fields\":[\"Leave semester(s)\",\"Reason for leave\",\"F-1 or J-1\",\"Academic advisor (or VGASP) approval\",\"Planned departure date from the U.S.\",\"Planned return semester and return route (reactivation vs. Initial I-20)\"],\"sources\":[{\"url\":\"https://ois.usc.edu/maintaining-status/leave-of-absence/\",\"title\":\"Leave of Absence - USC OIS\"}]},{\"id\":\"check-application-status\",\"topic\":\"12\",\"name\":\"Check application status\",\"desc\":\"See whether USC has received my application materials and view my admission decision.\",\"system\":\"USC Applicant Portal (admission.usc.edu/status) for undergraduate applicants; graduate applicants use the online graduate application's Notification status page and youSC for decisions\",\"steps\":[\"After submitting the Common App, watch for USC's confirmation email with instructions to set up your USC Applicant Portal account (the portal link arrives within one to two business days).\",\"Log in to the USC Applicant Portal (admission.usc.edu/status). Forgot your password? Use the Reset Password page to get a temporary PIN, using the same email address you put on your application.\",\"Review which materials show as received. Allow at least three weeks for transcripts and about 7-10 business days (up to three weeks at peak) for test scores to update.\",\"If an item still shows 'Not Received' after that, email USC Admission (via askUSC) with your name exactly as on the document, the sending institution or test date, how/when it was sent (vendor, date), the test appointment or IELTS TRF number, and an unofficial copy.\",\"Upload anything missing through 'Upload Materials' in the portal.\",\"Check the portal for your decision letter on the release date for your round; USC does not give decisions over the phone.\",\"Graduate applicants: check the Notification status page in the graduate application (official GRE/TOEFL scores, recommendations), ask via askUSC about transcripts, GMAT/IELTS/PTE scores or overall status, and view decisions on youSC after the decision email.\"],\"req\":[\"Portal access exists only after you submit the Common Application (undergraduate).\",\"Password resets require the same email address supplied in the application.\",\"USC does not provide decisions over the phone or say whether a decision has been made.\",\"Graduate Admission does not send confirmation emails when specific materials are received; it emails only if something is missing.\"],\"deadlines\":[\"Portal link: within one to two business days of submitting the Common App.\",\"Transcripts: at least three weeks to show as received; test scores: approximately 7-10 business days (up to three weeks at peak).\",\"Undergraduate decisions: Early Decision by mid-December; Early Action late January; Regular Decision by April 1; transfers by end of May (mid-July if spring grades are requested).\",\"Graduate: about 15 business days to process records during November-May; most fall decisions by June, spring decisions by December.\"],\"costs\":[\"none stated\"],\"fields\":[\"applicant type (first-year, transfer or graduate)\",\"email address used on the application\",\"which item appears missing\",\"date and method the item was sent\",\"name exactly as it appears on the document\"],\"sources\":[{\"url\":\"https://admission.usc.edu/contact-us/\",\"title\":\"Contact Us - Undergraduate Admission\"},{\"url\":\"https://ask.usc.edu/s/article/000002924\",\"title\":\"askUSC: How do I confirm receipt of application materials such as SAT scores, transcripts, etc.?\"},{\"url\":\"https://ask.usc.edu/s/article/000002548\",\"title\":\"askUSC: How do I reset my password for the USC Applicant Portal?\"},{\"url\":\"https://gradadm.usc.edu/domestic-students/how-to-apply/\",\"title\":\"How to Apply - Graduate Admission\"}]},{\"id\":\"submit-enrollment-deposit\",\"topic\":\"12\",\"name\":\"Submit enrollment deposit (commit to USC)\",\"desc\":\"Accept my undergraduate offer of admission and pay the $300 enrollment commitment deposit, or request a deposit waiver.\",\"system\":\"USC Applicant Portal: 'Admit Reply' form (fall admits) or 'Intent to Enroll' form (spring admits); graduate students submit the Intent to Enroll on youSC and pay any program-specific deposit\",\"steps\":[\"Log in to the USC Applicant Portal.\",\"Fall admits: complete the 'Admit Reply' form to accept your offer. Spring admits: complete the 'Intent to Enroll' form.\",\"Pay the $300 enrollment commitment deposit, or select the deposit waiver on the form if financial hardship prevents paying (fall first-years still waiting on an updated financial aid summary can also request the waiver).\",\"Submit by your deadline (fall first-years: May 1, 11:59 PM in your time zone).\",\"Watch for the confirmation email with your 10-digit USC ID, then activate your USC NetID; orientation information goes only to your USC email.\",\"The $300 is credited to your student account and applied to tuition and fees shortly after you register for classes; contact the Office of Admission if it hasn't been credited by early August.\",\"Not attending? Decline your offer on the same form instead.\"],\"req\":[\"You must be an admitted undergraduate.\",\"The deposit is nonrefundable and is applied to the tuition and fees of the term you were admitted for; it cannot be rolled over if you defer to another academic year.\",\"USC cannot guarantee your space if the deposit is submitted after the deadline.\",\"International students can request an I-20 only after committing and paying the deposit; USC Housing assigns rooms only to certified students (deposit or approved waiver).\"],\"deadlines\":[\"Fall first-year admits: May 1 (published for fall 2026 admits).\",\"Fall transfer admits: June 1 or within two weeks of receiving the admission letter.\",\"Spring 2027 admits: first-years submit the Intent to Enroll by May 1 and the deposit by August 1; transfers by August 1 or within two weeks of the offer, whichever is later.\",\"First-year spring admits who want fall consideration: Intent to Enroll by May 1 (deposit not required for fall consideration); the Spring Admit FAQ tells transfer spring admits to submit the Commitment Deposit by June 1 or within two weeks of the decision for fall consideration.\"],\"costs\":[\"$300 nonrefundable enrollment commitment deposit, applied to first-semester tuition and fees\",\"Deposit waiver available for financial hardship\"],\"fields\":[\"admit term (fall or spring)\",\"applicant type (first-year or transfer)\",\"accept or decline\",\"pay $300 or request a hardship waiver\",\"deadline that applies\",\"student understands the deposit is nonrefundable\"],\"sources\":[{\"url\":\"https://admission.usc.edu/admitted-students/next-steps-fall/\",\"title\":\"Next Steps Fall - Undergraduate Admission\"},{\"url\":\"https://ask.usc.edu/s/article/000002741\",\"title\":\"askUSC: Can I submit my commitment deposit even if I am waiting for my financial aid summary?\"},{\"url\":\"https://admission.usc.edu/admitted-students/next-steps-spring/\",\"title\":\"Next Steps Spring - Undergraduate Admission\"},{\"url\":\"https://ask.usc.edu/s/article/000001739\",\"title\":\"askUSC: What is the deadline to submit the enrollment commitment deposit for admitted transfer applicants?\"}]},{\"id\":\"register-for-orientation\",\"topic\":\"12\",\"name\":\"Register for Welcome Trojans Orientation\",\"desc\":\"Reserve my Welcome Trojans Orientation experience, pick my course registration session and add guests.\",\"system\":\"Welcome Trojans Orientation reservation (link in the invitation the Office of Orientation Programs emails to your USC email), then the Trojan Engagement Center, the Pre-Registration Guide in Brightspace and Advise USC\",\"steps\":[\"Submit your Intent to Enroll/Admit Reply AND your enrollment deposit (or waiver).\",\"Activate your USC NetID and check your USC email; invitations are sent only there.\",\"Wait for your Welcome Trojans invitation (rolling, beginning in April; allow 5-7 business days if you commit after April 1).\",\"Follow the invitation to reserve: choose an online or in-person Trojan event, select a course registration date/time (availability set by your academic department), add up to two guests (each needs a unique, current email), and enter accommodation requests (including extended time for placement exams).\",\"Review your confirmation email and log in to the Trojan Engagement Center.\",\"Complete the Pre-Registration Guide in Brightspace (department folder, placement exams, Pre-Advisement Worksheet) and schedule Orientation Academic Advising through Advise USC before your registration session.\",\"Need changes? Use the instructions in your confirmation email; if none of the dates work, reserve anyway and open a case with Orientation.\"],\"req\":[\"Invitation is sent only after both the intent to enroll and the enrollment commitment deposit (or waiver) are submitted.\",\"Undergraduates may add up to two guests; guest access requires a unique email per guest.\",\"Orientation Academic Advising must be completed before your Welcome Trojans Course Registration session.\",\"Graduate students don't make this reservation: the Trojan Engagement Center link is sent automatically and departments handle advising and registration.\"],\"deadlines\":[\"Invitations begin in April on a rolling basis.\",\"Spring 2027 admits: course registration and Trojan events in November and December (e.g., Dornsife first-years register Friday, December 4; transfers Friday, December 11).\",\"Fall admits: first-years register in June and transfers in July; Trojan events run June-August.\",\"Reservation changes depend on capacity and reservation deadlines (specific dates not published).\"],\"costs\":[\"One-time New Student Fee charged to the first-semester bill: $450 undergraduate / $55 graduate (covers Welcome Week activities)\",\"Additional guest fee if multiple guests attend an on-campus Trojan event (amount not stated on USC sites)\",\"Travel and lodging are not subsidized by USC\"],\"fields\":[\"student type and start term (first-year/transfer, fall/spring)\",\"in-person Trojan event or online only\",\"preferred course registration session\",\"guest names and unique email addresses (max 2)\",\"accommodation requests\",\"acknowledgment of guest fee and travel costs\"],\"sources\":[{\"url\":\"https://ask.usc.edu/s/article/How-do-I-sign-up-for-Orientation\",\"title\":\"askUSC: How do I sign up for Orientation?\"},{\"url\":\"https://orientation.usc.edu/undergraduate/\",\"title\":\"Undergraduate - Orientation Programs\"},{\"url\":\"https://ask.usc.edu/s/article/Do-I-register-for-classes-during-Orientation\",\"title\":\"askUSC: Do I register for classes during Orientation?\"},{\"url\":\"https://ask.usc.edu/s/article/Can-I-change-modify-or-update-my-Welcome-Trojans-Orientation-reservation\",\"title\":\"askUSC: Can I change, modify or update my Welcome Trojans Orientation reservation?\"}]},{\"id\":\"schedule-campus-tour\",\"topic\":\"12\",\"name\":\"Schedule a campus tour\",\"desc\":\"Book a student-led campus tour (and optionally an information session) of USC's University Park Campus.\",\"system\":\"USC Undergraduate Admission tour registration ('Register for a tour' on admission.usc.edu Meet Us > Tours, which links to applyto.usc.edu/portal/tours); Group Tours and Tommy's Tours calendars for groups; admitted students register for Explore USC events in the applicant portal\",\"steps\":[\"Go to admission.usc.edu > Prospective Students > Meet Us > Tours.\",\"Pick a student-led tour (Monday-Friday, 75-90 minutes) and click 'Register for a tour'; optionally also register for a first-year/transfer information session or an academic department session.\",\"Complete the reservation for everyone in your party (guests 13-17 coming without an adult need parent/guardian consent in the reservation).\",\"Need ADA accommodations? Email visitusc@usc.edu or call (213) 740-6605 at least five business days before the tour.\",\"Plan parking (buy a $20 parking permit; the Admission Center doesn't validate) and review the How to Access Campus page and campus map.\",\"Watch your email for any changes or cancellations and arrive on time (late arrivals receive a self-guided tour brochure).\",\"Alternatives: self-guided tours daily during campus entrance hours (no registration or check-in); school groups book via the Group Tours calendar (requested by a teacher/counselor/administrator); K-8 groups use Tommy's Tours; graduate applicants contact their department.\"],\"req\":[\"Prior registration is required for formal tours.\",\"Guests 12 and younger must be accompanied by an adult.\",\"Group tours must be requested by a teacher, counselor and/or administrator.\",\"Tours do not go inside residence halls, and guides from a specific major can't be requested.\"],\"deadlines\":[\"Student-led tours run Monday through Friday; self-guided tours daily during campus entrance hours.\",\"ADA accommodation requests: at least five business days before the tour.\",\"After 9 p.m. campus public access points are restricted and guests must be pre-registered.\"],\"costs\":[\"Tours are free of charge\",\"Parking permit: $20 (not validated by the Admission Center)\"],\"fields\":[\"tour date and time\",\"tour type (student-led, self-guided, group, admitted-student)\",\"number of guests and ages (minors)\",\"add an information or academic department session\",\"accessibility needs\",\"parking plan\"],\"sources\":[{\"url\":\"https://admission.usc.edu/prospective-students/meet-us/tours/\",\"title\":\"Tours - Undergraduate Admission\"},{\"url\":\"https://www.usc.edu/visit-usc/\",\"title\":\"Visit USC - USC\"},{\"url\":\"https://ask.usc.edu/s/article/000002168\",\"title\":\"askUSC: How do I make a reservation for one of your campus tours or visit programs?\"}]},{\"id\":\"submit-additional-application-materials\",\"topic\":\"12\",\"name\":\"Submit additional application materials\",\"desc\":\"Send USC a missing or new document for my application (transcript, mid-year or spring grades, recommendation letter, financial documents, test scores or portfolio).\",\"system\":\"USC Applicant Portal 'Upload Materials' (undergraduate); school-sent e-transcripts to uetrans@usc.edu; extra recommendation letters to admlors@usc.edu; arts supplements via SlideRoom; mail to the USC Office of Admission; graduate applicants use the online graduate application and etrans@usc.edu\",\"steps\":[\"Log in to the USC Applicant Portal and click 'Upload Materials'.\",\"Choose the matching document type (e.g., 'Mid-Year Transcript', 'Spring Grades (unofficial)', financial documentation) and upload the file.\",\"Official transcripts: have your school send them electronically (uetrans@usc.edu if the service needs an email) or mail them in a sealed official envelope to USC Office of Admission, Undergraduate, University Park Campus, Los Angeles, CA 90089-0911; if mailing, also upload an unofficial copy.\",\"Official test scores: order them from the testing agency (SAT code 4852, ACT code 0470).\",\"Additional recommendation letters: the recommender emails them to admlors@usc.edu.\",\"Arts portfolios/supplements: submit through SlideRoom following your department's instructions.\",\"To correct something already submitted, email your admission counselor with the subject 'Changes to Application' from the email on your application.\",\"Confirm receipt in the portal (transcripts can take at least three weeks to appear).\"],\"req\":[\"Portal access is available within one to two business days of submitting the Common App.\",\"Uploaded transcripts and score reports are unofficial; official ones must come from the school or testing agency.\",\"USC cannot retrieve documents from file-hosting links (Dropbox, OneDrive, iCloud).\",\"USC discourages supplemental materials beyond what departments require; admlors@usc.edu is only for recommendation letters and uetrans@usc.edu only for transcript services.\"],\"deadlines\":[\"All elements should arrive by your application deadline; late supporting documents leave the file incomplete (not late) until received.\",\"International Financial Statement and English test scores: within two weeks of your application deadline.\",\"Mid-year grades: as soon as available (requests go out in January and February).\",\"Transfer spring grades: when requested; decisions follow through mid-July.\",\"After admission, first-year final transcripts are due July 1.\"],\"costs\":[\"none stated\"],\"fields\":[\"document type\",\"official or unofficial copy\",\"sending method (portal upload, school e-transcript, mail or email)\",\"applicant's full name and USC/reference ID on the document\",\"applicable deadline\"],\"sources\":[{\"url\":\"https://ask.usc.edu/s/article/000001434\",\"title\":\"askUSC: How do I add materials or make changes to my undergraduate application after I have submitted it?\"},{\"url\":\"https://admission.usc.edu/contact-us/\",\"title\":\"Contact Us - Undergraduate Admission\"},{\"url\":\"https://ask.usc.edu/s/article/000001466\",\"title\":\"askUSC: Are letters of recommendation required to apply for undergraduate admission?\"},{\"url\":\"https://ask.usc.edu/s/article/000001485\",\"title\":\"askUSC: Can I share supplemental admission materials on a cloud drive?\"}]}]";

